--[[
	Midnight Helper — Russian strings (ruRU).
	Translated 11 Oct 2026 by the build chat's helpers from the enUS text, with a glossary of the words the
	ruRU client itself shows (measured in Blizzard data, wago build 12.1.0.69933). NOT reviewed by a native
	speaker: corrections welcome (GitHub issue, "Translation" template).

	Load order: after every other Locales file and before Locale.lua, so this one table is the whole pack.
	Any key missing here falls back to English via ns:L(). Proper names (bosses, NPCs, items, zones) stay
	English like the other packs; game terms follow the ruRU client. Since 11 Oct 2026 plain-text spell, proc,
	talent and hero-tree names in the play cards (PLAYCARD_*) also follow the ruRU client (SpellName /
	TraitSubTree / Creature, wago 12.1.0.69933), not English; they stay nominative inside straight quotes.
]]

local _, ns = ...

ns._mhLocales = ns._mhLocales or {}

-- Locale-gating (Spec 11 3a): only build this pack when the client is ruRU.
if GetLocale() ~= "ruRU" then
	return
end

ns._mhLocales.ruRU = {
	ABOUT_BUTTON = "Об аддоне",
	ABOUT_VERSION_FMT = "Установленная версия: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Авторы: TwelveInchy & Claude\n\nВаш помощник для Midnight – все в одном. Он разделен на четыре комнаты: \"Я\", \"Кодекс\", \"Инструменты\" и \"Настройки\". Закрепляйте избранное под строкой поиска и начинайте вводить текст, чтобы перейти куда угодно. Внутри: \"Эта неделя\", \"Вылазки и хранилище\", тренеры вылазок и ритуалов, советник по чарам и самоцветам, \"Сводка по учетной записи\", руководства Кодекса, профессии и встроенные инструменты аддонов – EN / NL / DE / FR / ES / PT / IT.\n\nСпасибо аддонам и руководствам, по которым мы сверяли факты: DBM (способности боссов и ID заклинаний), HandyNotes_Midnight (места редких существ и кладов), GTFO (ID опасных заклинаний), RareScanner (обработка виньеток), а также Wowhead, Icy Veins, Method и wowcarry. ID и числа для нас – это подсказки, и везде, где можем, мы проверяем их в самой игре; код этих аддонов не используется.",
	ABOUT_WINDOW_TITLE = "О Midnight Helper",
	ACADEMY_CHAT_COPY_TIP = "Выделите эту строку (Ctrl+C)",
	ACADEMY_CHAT_HINT = "Нажмите на строку (или на ее значок копирования) и нажмите Ctrl+C. Нажмите Enter: чат откроется в канале \"Сказать\", который видят только игроки рядом с вами. Чтобы написать группе, сначала введите /p и пробел; в подземелье из Поиска группы вместо этого введите /i. Затем нажмите Ctrl+V, чтобы вставить, и Enter, чтобы отправить. Там, где написано [название заклинания], впишите название заклинания врага.",
	ACADEMY_CLASS_FMT = "Вы вошли: %s – %s. Карта вашей специализации: /mh play",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Открыты макросы для %s – %s. Загляните и в \"Расходуемые\": там настои и зелья.",
	ACADEMY_DPS_BOTH_BODY = "Вы уже знаете бои с места бойца, а это большая часть работы. Танк попадает в подземелья сразу; лечение требует больше всего выдержки, но лекари нужнее всех.\n\nСначала попробуйте новую роль в вылазке или в подземелье с соратниками, где вас никто не ждет. Потом какое-то время держите одну роль основной, а не меняйте ее в каждой случайной группе.",
	ACADEMY_DPS_BOTH_TITLE = "Думаете о танке или лекаре?",
	ACADEMY_DPS_COOLDOWNS_BODY = "Ваши атакующие способности с долгим восстановлением дают большую часть вашего урона. Нажимать их, как только они восстановились, лучше, чем копить их для \"идеального\" момента, который так и не наступит.\n\nНа боссе начните с них или сохраните их для важной фазы. Набор инструментов выше перечисляет их для вашей специализации.",
	ACADEMY_DPS_COOLDOWNS_TITLE = "Сочетайте способности с восстановлением",
	ACADEMY_DPS_INTRO_BODY = "Ваша задача – урон, но мертвый боец наносит ноль. Сначала выжить и выполнять механики, урон – потом.\n\nВам не нужно быть первым в счетчике урона. Ровный урон, пока вы делаете свою работу, лучше огромных чисел, за которыми следует смерть.",
	ACADEMY_DPS_INTRO_TITLE = "Мышление бойца",
	ACADEMY_DPS_MECHANICS_BODY = "Выходите из опасных зон, даже если это стоит одного заклинания. Куча урона, которого можно было избежать, губит группу быстрее, чем низкий урон.\n\nЖадность – стоять в огне ради еще одного заклинания. Правильно – потратить полсекунды на смену позиции и остаться в живых, чтобы нажать остальное.",
	ACADEMY_DPS_MECHANICS_TITLE = "Механики важнее урона",
	ACADEMY_DPS_MISTAKES_BODY = "1. Копить способности с восстановлением \"на всякий случай\"\n2. Упираться в максимум ресурса (накопленное уходит впустую)\n3. Стоять в опасной зоне ради еще одного заклинания\n4. Никогда не прерывать и не использовать вспомогательные способности\n5. Смотреть только на урон, пока ваше здоровье падает до дна\n\nИсправляйте одну ошибку за забег – не все пять сразу.",
	ACADEMY_DPS_MISTAKES_TITLE = "Частые ошибки новичков",
	ACADEMY_DPS_PRACTICE_BODY = "Побейте тренировочный манекен две минуты: пусть ресурс не простаивает, вплетайте способности с восстановлением и смотрите, какие эффекты спадают.\n\nПотом вылазки, потом обычные подземелья. Чтобы начать, не нужна идеальная ротация – нужно продолжать нажимать и оставаться в живых.",
	ACADEMY_DPS_PRACTICE_TITLE = "Тренировка на мишени",
	ACADEMY_DPS_ROTATION_BODY = "Большинство специализаций копят ресурс, а потом тратят его. Пусть способность-накопитель и способность-трата работают без перерыва; не упирайтесь в максимум ресурса и не давайте периодическим и положительным эффектам спадать.\n\nОдна-две кнопки, нажатые вовремя, лучше беспорядочного нажатия пяти. Учите приоритет, а не заученный порядок.",
	ACADEMY_DPS_ROTATION_TITLE = "Приоритет, а не жесткая ротация",
	ACADEMY_DPS_UTILITY_BODY = "Прерывайте опасные заклинания, используйте контроль и нажимайте личную защитную способность, когда получаете сильный удар.\n\nБоец, который прерывает и выживает, стоит намного больше того, кто только набивает цифры.",
	ACADEMY_DPS_UTILITY_TITLE = "Вы не просто машина для урона",
	ACADEMY_HEAL_BOTH_BODY = "Путь бойца – самая мягкая вторая роль: только ваши кнопки, прерывания и место, где вы стоите, без давления на группу. Танк меньше всех ждет группу в подземелье – когда танковать станет не так страшно.\n\nДве роли за одну неделю в группах с незнакомцами – это много. Выберите одну \"основной\", чтобы было меньше страха.",
	ACADEMY_HEAL_BOTH_TITLE = "Учите еще танка или бойца?",
	ACADEMY_HEAL_CHAT_BODY = "\"Учусь лечить – скажу, когда будет мало маны.\"\n\"Танк в приоритете – скажите, если нужна передышка.\"\n\"Большое исцеление на вас – следите за здоровьем.\"\n\"Нет маны, 5 сек. между боями.\"\n\"Это моя ошибка – в следующем бою сохраню больше для танка.\"",
	ACADEMY_HEAL_CHAT_TITLE = "Чат группы",
	ACADEMY_HEAL_CONFIDENCE_BODY = "Кто-то умрет, пока вы лечите. Каждый лекарь хоть раз терял союзников – так узнают, где пределы.\n\nОдна смерть – это не гибель всей группы, а гибель группы – не приговор вам. Запомните одну вещь, которую сделали бы иначе, и отпустите.\n\nГруппы гораздо лучше запоминают спокойного лекаря, который общается, чем идеального.",
	ACADEMY_HEAL_CONFIDENCE_TITLE = "Потерять кого-то – это нормально",
	ACADEMY_HEAL_COOLDOWNS_BODY = "Ваши исцеляющие способности с восстановлением – это кнопки с долгим ожиданием. Некоторые нужны для больших моментов – удар босса по всей группе или когда многие падают одновременно, – а не для случайных царапин. Другие вы используете часто, почти сразу после восстановления.\n\nДержать способность \"на всякий случай\" весь бой – значит потратить ее впустую. Нажать ее примерно вовремя лучше, чем не нажать вовсе.\n\nВведите /mh healcds: там способности вашей специализации и когда использовать каждую. Работает, когда у вас активна специализация лекаря.",
	ACADEMY_HEAL_COOLDOWNS_TITLE = "Используйте способности с восстановлением вовремя",
	ACADEMY_HEAL_DUNGEON_BODY = "С друзьями, если можете, иначе со случайной группой (пошаговый план выше показывает, как). Отметьте значок \"Лекарь\", прежде чем нажать \"Найти группу\".\n\nСкажите группе, что вы учитесь. Держитесь достаточно близко к танку, чтобы ваше исцеление доставало (в зоне досягаемости); пусть бойцы немного поцарапаются, прежде чем вы тратите ману.\n\nМежду боями: пейте, обновляйте положительные эффекты, дышите. Сказать \"Нет маны, 5 сек.\" – можно.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Ваше первое обычное подземелье (после подземелья с соратниками)",
	ACADEMY_HEAL_INTRO_BODY = "Вы не обязаны держать всех на 100% здоровья все время.\n\nВаша задача – сортировка: сохранить танка, спасти того, кто вот-вот умрет, потом остальных. Немного урона – это нормально; паническое лечение сверх нужного опустошает ману.",
	ACADEMY_HEAL_INTRO_TITLE = "Мышление лекаря",
	ACADEMY_HEAL_LADDER_BODY = "1. Полечите друга в открытом мире (не в подземелье)\n2. Вылазки с небольшой группой\n3. Подземелье с соратниками: NPC заполняют остаток группы (уровень 80-90). Поиск группы -> Поиск подземелий -> Подземелья с соратниками\n4. Обычное подземелье с терпеливыми друзьями\n5. Рейд: Поиск рейда / героический режим, когда будете готовы\n\nВылазки – самый мягкий шаг к прохождению подземелий.",
	ACADEMY_HEAL_LADDER_TITLE = "Лестница страха (рекомендуемый порядок)",
	ACADEMY_HEAL_MANA_BODY = "Мана – ваша настоящая полоса здоровья. Если она кончится, вы вообще не сможете лечить.\n\nКакое исцеление дешевое, зависит от специализации: у одних экономное – медленное, у других – быстрое. Наведите курсор на исцеление: подсказка показывает его стоимость в мане. Некоторые подсказки еще и словами говорят, экономное это исцеление или дорогое. Не всем нужно полное здоровье – пусть люди побудут на 80%.\n\nПейте между всеми боями. \"Нет маны (OOM), 5 сек.\" – нормальная, профессиональная фраза.",
	ACADEMY_HEAL_MANA_TITLE = "Мана и экономность",
	ACADEMY_HEAL_MISTAKES_BODY = "1. Смотреть только на одну полосу здоровья, пока три другие падают\n2. В панике лечить до 100% и опустошать ману\n3. Стоять в опасной зоне, уставившись на рамки\n4. Никогда не нажимать способности с восстановлением\n5. Лечить урон, который можно исправить, вместо того чтобы попросить прерывание\n\nСледите за одной ошибкой за забег – не за всеми пятью сразу.",
	ACADEMY_HEAL_MISTAKES_TITLE = "Частые ошибки новичков",
	ACADEMY_HEAL_POSITION_BODY = "Оставайтесь в зоне досягаемости всей группы, но не вплотную к боссу. Дальний угол, откуда видно всех, лучше, чем стоять вплотную к танку.\n\nУворачиваться все равно нужно. Мертвый лекарь никого не лечит – выходите из опасной зоны, даже если это стоит полсекунды произнесения.\n\nСохраняйте прямую видимость: через стену или колонну лечить нельзя.",
	ACADEMY_HEAL_POSITION_TITLE = "Где стоять",
	ACADEMY_HEAL_RAID_BODY = "Поиск рейда: урон по всему рейду становится предсказуемым после одной гибели группы. Учите, когда приходят сильные удары босса (их показывает шкала \"Способности босса\"), а не полосы каждого игрока.\n\nВ рейде та же сортировка: сначала танк и окна для рейдовых способностей с восстановлением.",
	ACADEMY_HEAL_RAID_TITLE = "Рейды и Поиск рейда (позже)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Вы сами (если умираете – мертвый лекарь никого не лечит)\n2. Танк (если группа врагов все еще на нем)\n3. Все, у кого меньше ~40% здоровья или опасный отрицательный эффект\n4. Все остальные – экономными исцелениями\n\nКто-то вот-вот умрет: сначала исцеление, которое срабатывает сразу (в наборе инструментов оно отмечено [Мгновенное], и в его подсказке тоже сказано, что оно мгновенное). Ничего не готово? Ваше исцеление [Короткое]. Много урона и есть время на произнесение: ваше большое исцеление (друид, Исцеление: Regrowth, ваше прямое исцеление). Спокойно: исцеление, которое стоит мало маны (подсказка показывает стоимость).",
	ACADEMY_HEAL_TRIAGE_TITLE = "Сортировка (кого первым?)",
	ACADEMY_HEAL_WHAT_BODY = "Лекарь сохраняет группе жизнь. Враги ранят ваших друзей; ваше исцеление восполняет их здоровье.\n\nВыберите, кого лечить: нажмите на полосу этого игрока (его рамку), затем нажмите исцеление. Никто не выбран или выбран враг? Тогда обычное исцеление попадет в вас самих. Заклинания, которые могут и ранить врагов (например, Holy Shock и Divine Toll), в этом случае уйдут во врага.\n\nРамки – это полосы здоровья вашей группы на экране. Читать их легче так: Esc -> Редактировать -> нажмите \"Интерфейс группы\" -> отметьте \"Рейдовый интерфейс для группы\".\n\nСледующий шаг, когда нажимать станет легко: \"Заклинания: кнопки мыши\". Вы ставите исцеление на кнопку мыши, и нажатие на рамку сразу лечит этого игрока. Esc -> Параметры -> Игровой процесс -> Назначение клавиш -> \"Заклинания: кнопки мыши\", затем \"Новая команда\" и \"Сохранить\". Используете рамки из аддона со своей настройкой кнопок мыши (DandersFrames, Cell, VuhDo)? Тогда настройте исцеление там, а \"Заклинания: кнопки мыши\" от Blizzard оставьте пустыми: две такие настройки на одной кнопке мешают друг другу.\n\nЭкипировка: основная характеристика вашей специализации лекаря (у лекарей – Интеллект). Игра показывает ее под каждой специализацией как \"Основная характеристика\".\n\nПереключитесь на специализацию лекаря: Таланты и способности -> Специализация -> Активировать (бесплатно). Специализация для добычи – та, для которой выпадает добыча: правой кнопкой мыши по своему портрету (изображению вашего персонажа рядом с полосой здоровья) -> \"Добыча для специализации\".",
	ACADEMY_HEAL_WHAT_TITLE = "Что такое лекарь?",
	ACADEMY_HEAL_WIPE_BODY = "\"Можно ли было спасти танка?\" – вот полезный вопрос, а не \"почему боец стоял в опасной зоне?\"\n\nЕсли кончилась мана, в следующий раз используйте более экономные заклинания. Одна гибель группы не значит, что вы не умеете лечить.",
	ACADEMY_HEAL_WIPE_TITLE = "Когда все идет не так",
	ACADEMY_PREF_DPS_COOLDOWNS = "Атакующие способности с восстановлением на клавишах (не затеряны на панели)",
	ACADEMY_PREF_DPS_DEFENSIVE = "Личная защитная способность на панели",
	ACADEMY_PREF_DPS_INTERRUPT = "Прерывание на клавише (один раз проверено на манекене)",
	ACADEMY_PREF_DPS_ROTATION = "Основные способности на удобных клавишах",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Зелье маны / настой (вкладка \"Расходуемые\")",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Личная защитная способность на панели (ваша карта: /mh play -> Не умереть)",
	ACADEMY_PREF_HEAL_MACROS = "Макросы лечения по наведению / на фокус (вкладка \"Макросы\")",
	ACADEMY_PREF_HEAL_PRACTICE = "Друг один раз вылечен нажатием на его рамку",
	ACADEMY_PREF_HINT = "Отметки сохраняются в ваших настройках. \"Макросы\" и \"Расходуемые\" – в комнате \"Инструменты\".",
	ACADEMY_PREF_TANK_CONSUMABLES = "Настой / зелье наготове (вкладка \"Расходуемые\")",
	ACADEMY_PREF_TANK_DEFENSIVE = "Одна защитная способность наготове (ваша карта: /mh play -> Не умереть)",
	ACADEMY_PREF_TANK_INTERRUPT = "Прерывание на панели: сама кнопка или готовый макрос (вкладка \"Макросы\")",
	ACADEMY_PREF_TANK_TAUNT = "Знаю клавишу провокации (один раз проверено на тренировочном манекене – в Луносвете они есть)",
	ACADEMY_PREF_TITLE = "Проверка перед стартом (отмечайте, когда готово)",
	ACADEMY_SEE_BODY = "В бою с боссом игра сама вас предупреждает: значки отсчитывают время на шкале \"Способности босса\", а крупные предупреждения появляются в центре экрана. И то и другое включено по умолчанию (Esc -> Параметры -> Игровой процесс -> Улучшения процесса -> Предупреждения боссов).\n\nКогда враг произносит заклинание, под его полосой здоровья заполняется полоса (и под его портретом – маленьким изображением, – если он ваша цель). Заклинание срабатывает в тот момент, когда полоса заполнена. Поэтому прерывайте, отходите или нажимайте защитную способность, пока полоса еще заполняется – как только увидели, уже хорошо. Полная полоса – слишком поздно. Полосу со щитом прервать нельзя.\n\nСветящаяся полоса означает важное заклинание. Отсутствие свечения не значит, что оно безопасно.\n\nПрежде чем начать бой, изучите босса: Shift+J (Путеводитель по приключениям) -> босс -> Способности, или введите /mh bosswin. Окно MH закрывается, когда начинается бой, поэтому читайте заранее.\n\nФизический урон или магия? В Путеводителе по приключениям откройте босса -> Обзор -> раздел для танков или лекарей. Там указан урон сильной атаки: \"Физический\" – это физический урон; школа вроде \"Огонь\" или \"Тень\" означает магию.",
	ACADEMY_SEE_TITLE = "Как заметить сильный удар заранее",
	ACADEMY_STEP_CARD = "Один раз прочитайте карту своей специализации: кнопка \"Как вы играете\" ниже, или нажмите Enter, введите /mh play, нажмите Enter",
	ACADEMY_STEP_FOLLOWER = "Пройдено одно подземелье с соратниками (Поиск группы внизу справа -> Поиск подземелий -> Подземелья с соратниками -> Найти группу)",
	ACADEMY_STEP_HEAL_FRAMES = "Рейдовый интерфейс для группы включен (Esc -> Редактировать -> Интерфейс группы)",
	ACADEMY_STEP_HEAL_FRIEND = "Друг один раз вылечен вне подземелья нажатием на его рамку (сначала пригласите его: правой кнопкой мыши по его имени в чате -> Пригласить, или введите /inv и его имя)",
	ACADEMY_STEP_HEAL_GEAR = "Экипировка с Интеллектом – основной характеристикой любой специализации лекаря (Таланты и способности -> Специализация показывает ее как \"Основная характеристика\"). Прежде всего оружие с Интеллектом. Паладин остается в латах: латы с Интеллектом бывают. Где взять? Вставайте в очередь в роли \"Боец\", а \"Добычу для специализации\" поставьте на специализацию лекаря (правой кнопкой мыши по портрету). Тогда подземелья могут дать экипировку с Интеллектом, но какой предмет вы получите, не гарантировано. Потом снова выберите \"Текущая специализация\".",
	ACADEMY_STEP_HEAL_KEYS = "Ваши исцеления и развеивание на клавишах, до которых легко достать: перетащите их из Таланты и способности -> Способности на панель команд",
	ACADEMY_STEP_HEAL_SPEC = "Переключитесь на специализацию лекаря: Таланты и способности (внизу справа) -> Специализация -> Активировать",
	ACADEMY_STEP_HINT = "Отмечайте шаг, когда выполните его. \"Специализация\" и, для танков, \"клавиши\" отмечаются сами, когда игра это видит. Совет: наведите курсор на кнопку в ряду маленьких кнопок внизу справа экрана – подсказка покажет ее клавишу.",
	ACADEMY_STEP_NORMAL = "Пройдено одно обычное подземелье с живыми игроками: с друзьями или согильдийцами, если можете, иначе со случайной группой. Сначала пригласите друзей (правой кнопкой мыши по имени в чате -> Пригласить, или введите /inv и имя). Затем Поиск группы -> Поиск подземелий -> случайное подземелье (Midnight), отметьте значок \"Танк\" или \"Лекарь\" и нажмите \"Найти группу\" (в группе ее нажимает лидер). Не лидер? Заранее отметьте свою роль в Поиске подземелий или подождите: когда лидер нажмет \"Найти группу\", вы увидите \"Подтвердите свою роль:\" – отметьте роль и нажмите \"Принять\"",
	ACADEMY_STEP_TANK_DUMMY = "Кнопки отработаны на тренировочных манекенах в Луносвете (западная сторона, у Площади Соколиных Крыльев; на вкладке MH \"Луносвет\" есть точка на карте). Normal Tank Dummy бьет в ответ.",
	ACADEMY_STEP_TANK_GEAR = "Экипировка с основной характеристикой вашей специализации танка (паладину и воину в Защите – еще и щит). Таланты и способности -> Специализация показывает ее под каждой специализацией как \"Основная характеристика\"; окно персонажа показывает только основную характеристику текущей специализации. Еще нет щита? На 90-м уровне: Аукционный дом -> Броня -> Разное -> Щит, плюс одноручное оружие с вашей основной характеристикой (двуручное оружие со щитом не носят). Ниже 90-го уровня: вставайте в очередь в роли \"Боец\", а \"Добычу для специализации\" поставьте на специализацию танка (правой кнопкой мыши по портрету). Тогда подземелья могут дать экипировку танка, в том числе щит, но это не гарантировано. Потом снова выберите \"Текущая специализация\".",
	ACADEMY_STEP_TANK_KEYS = "Ваша провокация и прерывание на клавишах (набор инструментов ниже их называет): Таланты и способности -> Способности, перетащите каждое заклинание левой кнопкой мыши на панель команд",
	ACADEMY_STEP_TANK_SPEC = "Переключитесь на специализацию танка: Таланты и способности (внизу справа) -> Специализация -> Активировать",
	ACADEMY_STEP_TITLE = "Смена роли, шаг за шагом",
	ACADEMY_SUBTITLE = "Короткий курс игры за танка, лекаря и бойца в группе: как думать, что настроить сначала и спокойный путь в подземелья.",
	ACADEMY_TANK_BOTH_BODY = "Путь бойца – самая мягкая вторая роль: ваши кнопки, прерывания и место, где вы стоите, и группа от вас не зависит. Лечение – скачок побольше, но вы уже умеете читать бои, а это половина дела.\n\nКакое-то время держите одну основную роль в подземельях, а другую тренируйте в вылазках или в открытом мире. Смена ролей в одной группе \"Эпохальный+\" с незнакомцами удваивает стресс; уверенность в одной роли помогает освоить вторую.",
	ACADEMY_TANK_BOTH_TITLE = "Учите еще лекаря или бойца?",
	ACADEMY_TANK_CHAT_BODY = "\"Еще учусь танковать – пожалуйста, не спешите.\"\n\"Начинаю бой через 3...\"\n\"Нужна передышка для маны.\"\n\"Прерывание на [название заклинания] – следующее за мной.\"\n\"Еще попытка – теперь я знаю этот бой.\"",
	ACADEMY_TANK_CHAT_TITLE = "Чат группы",
	ACADEMY_TANK_DUNGEON_BODY = "Идите с друзьями или согильдийцами, если можете; иначе подойдет и случайная группа. Сначала пригласите друзей: правой кнопкой мыши по имени в чате -> Пригласить, или введите /inv и имя. Затем лидер группы нажимает \"Найти группу\".\n\nПеред \"Найти группу\" отметьте значок \"Танк\" (лекари – значок \"Лекарь\"). Без отмеченной роли кнопка не работает. Не лидер? Когда лидер нажмет \"Найти группу\", вы увидите \"Подтвердите свою роль:\": отметьте роль и нажмите \"Принять\".\n\nНе торопитесь с боями: две маленькие группы врагов лучше одного огромного боя со многими группами сразу.\n\nСледите за маной лекаря; делайте паузы между боями. Можно попросить контроль (CC) или сказать \"пока без больших боев\".",
	ACADEMY_TANK_DUNGEON_TITLE = "Ваше первое обычное подземелье (после подземелья с соратниками)",
	ACADEMY_TANK_INTRO_BODY = "Ваша задача: чтобы враги били вас, а не вашу группу, и задавать темп прохождения – а не наносить больше всех урона.\n\nОдин спокойный бой лучше идеального порядка кнопок с мертвой группой. Если помогает, объявляйте бои вслух: \"начинаю через 3\".",
	ACADEMY_TANK_INTRO_TITLE = "Мышление танка",
	ACADEMY_TANK_LADDER_BODY = "1. Элитные (более сильные) враги в открытом мире, с другом\n2. Вылазки (небольшое подземелье – вкладка \"Вылазки и хранилище\")\n3. Подземелье с соратниками: NPC заполняют остаток группы (уровень 80-90). Поиск группы -> Поиск подземелий -> Подземелья с соратниками\n4. Обычное подземелье с людьми, которым вы доверяете\n5. Героический режим / Поиск рейда, когда будет комфортно\n\nОставайтесь на каждой ступени, пока не станет скучно, а не страшно. Потом поднимайтесь выше.",
	ACADEMY_TANK_LADDER_TITLE = "Лестница страха (рекомендуемый порядок)",
	ACADEMY_TANK_PULL_BODY = "1. Соберите группу врагов: бейте всех атаками, которые поражают много врагов сразу (AoE). Провоцируйте только того, кто бежит к кому-то другому.\n2. Когда можете, разворачивайте врагов так, чтобы они смотрели в сторону от группы: некоторые враги бьют все перед собой, и иначе это заденет и вашу группу.\n3. Нажимайте защитную способность перед сильным уроном или в начале большого боя – а не когда здоровья уже мало. По одной за раз; самую сильную держите для самого тяжелого удара.\n4. Прерывайте заклинание, которое больнее всего (часто исцеление или сильный удар).\n\nНе нужно нажимать все кнопки сразу.",
	ACADEMY_TANK_PULL_TITLE = "Во время боя (первые 10 секунд)",
	ACADEMY_TANK_RAID_BODY = "Поиск рейда – мягкое знакомство с рейдами: он прощает ошибки, лекарей много. Сосредоточьтесь на сильных атаках босса и на том, чтобы стоять в правильном месте.\n\nТанковать в эпохальном рейде – не следующий шаг. Сначала освойтесь в героическом режиме и Поиске рейда.",
	ACADEMY_TANK_RAID_TITLE = "Рейды и Поиск рейда (позже)",
	ACADEMY_TANK_WHAT_BODY = "Танк заставляет врагов бить ВАС, а не вашу группу. Враг атакует вас – это называется aggro (\"нападение\").\n\nУгроза – это то, насколько враг на вас зол. Он бьет того, на кого злится сильнее всего. Атаки танка создают много угрозы, так что продолжайте бить каждого врага.\n\nПровокация (taunt) – одна кнопка, которая заставляет одного врага атаковать вас 6 секунд. После этого нужно 8 секунд, прежде чем ее можно нажать снова. Используйте ее, когда враг бьет кого-то другого, и продолжайте атаковать этого врага: если перестанете, через эти 6 секунд он вернется к прежней цели. Чтобы собрать целую группу врагов, используйте атаки, которые поражают много врагов сразу (AoE), а не провокацию.\n\nВы идете впереди и задаете темп. Группа следует за вами.\n\nЭкипировка: основная характеристика вашей специализации танка. Игра показывает ее под каждой специализацией как \"Основная характеристика\". Паладину и воину в Защите нужен щит: без него их ключевые кнопки не работают. Где его взять, сказано в шаге про экипировку ниже.\n\nПереключитесь на специализацию танка: Таланты и способности -> Специализация -> Активировать (бесплатно). Специализация для добычи – та, для которой выпадает добыча: правой кнопкой мыши по своему портрету (изображению вашего персонажа рядом с полосой здоровья) -> \"Добыча для специализации\".",
	ACADEMY_TANK_WHAT_TITLE = "Что такое танк?",
	ACADEMY_TANK_WIPE_BODY = "Гибель группы – это данные, а не приговор. Спросите себя: \"Не слишком ли далеко я был впереди?\" или \"Была ли нажата защитная способность перед сильным ударом?\"\n\nПереведите дух, поешьте и попейте, попробуйте снова.",
	ACADEMY_TANK_WIPE_TITLE = "Когда все идет не так",
	ACADEMY_TRACK_DPS = "Курс бойца",
	ACADEMY_TRACK_HEAL = "Курс лекаря",
	ACADEMY_TRACK_TANK = "Курс танка",
	ACADEMY_WORDS_BODY = "Pull: начало боя с группой врагов.\nPack: группа врагов, которые сражаются вместе.\nTrash: обычные враги между боссами.\nБосс: большой, сильный враг со своими приемами.\nAggro (\"нападение\"): враг атакует вас.\nУгроза (threat): насколько враг на вас зол. Он атакует того, у кого ее больше всего.\nTaunt (провокация): кнопка танка, которая заставляет одного врага атаковать вас.\nВосстановление (cooldown): ожидание, прежде чем кнопку можно нажать снова. \"(1.5 min)\" рядом с кнопкой – это ожидание.\nOn cooldown (как в \"нажимайте on cooldown\"): нажимайте снова, как только кнопка готова.\nЗащитная способность (defensive): кнопка, которая на короткое время снижает получаемый урон.\nActive mitigation: кнопка танка, которую нажимают снова и снова, чтобы получать меньше урона. В наборе инструментов [Блок] отмечает ту, что использует ваш щит.\nПрерывание (kick): кнопка, которая останавливает заклинание врага, пока оно произносится.\nCC (контроль): вывести врага из боя на время, например оглушением.\nОтрицательный эффект (debuff): плохой эффект на ком-то, например яд.\nРазвеивание (dispel): снятие отрицательного эффекта с кого-то.\nВайп (wipe): вся группа погибает. Вы бежите обратно и пробуете снова.\nOOM: нет маны (out of mana). Лекарь без маны не может лечить.\nРамки (frames): полосы здоровья вашей группы на экране.\nDPS: игроки, которые наносят урон (в Поиске группы эта роль называется \"Боец\"). Еще это значит урон в секунду.\nСпециализация (spec): направление, которое вы выбираете внутри класса, например Свет, Защита или Воздаяние у паладина.\nHP (здоровье): ваши очки здоровья. При 0 вы умираете.\nПоложительный эффект (buff): хороший эффект на ком-то, например больше характеристик или исцеление, которое продолжает действовать. Ваши положительные эффекты видны значками вверху справа.\nОбычный, Героический, Эпохальный: сложность подземелья или рейда, от легкой к трудной.\nLFR (Поиск рейда): самый легкий способ ходить в рейды. Записывайтесь в Поиске группы -> Подземелья и рейды -> Поиск рейда.\nM+ (Эпохальный+): эпохальное подземелье с эпохальным ключом. Вы соревнуетесь с таймером, и каждый уровень + делает врагов сильнее.\nПодземелье с соратниками: подземелье, где компьютерные персонажи (NPC) заполняют остаток вашей группы.\nТренировочный манекен: мишень в городе, которая никогда не умирает. Бейте ее, чтобы отработать кнопки.\nЭкипировка (gear): броня и оружие, которые вы носите.\nCast (произнесение): заклинание, которому нужно время: сначала заполняется полоса. Instant: заклинание, которое срабатывает сразу.\nHoT (heal over time): исцеление, которое лечит еще какое-то время.\nOverheal: исцеление сверх того, чего кому-то не хватает. Этот избыток – потраченная впустую мана.\nРейд: группа больше, чем в подземелье, против более сильных боссов.\nInstance: место, куда входит только ваша группа, например подземелье, рейд или вылазка.\nОпасные зоны (bad stuff): вредные места на земле, например огонь. Выходите из них.\nКлавиши: MH пишет их коротко, как и сама игра: s-3 – это Shift+3, c- – это Ctrl.",
	ACADEMY_WORDS_TITLE = "Слова, которые вы услышите",
	ACCOUNT_WEEKLY_ALL_CURRENT = "Данные всех сохраненных персонажей свежие – после еженедельного обновления.",
	ACCOUNT_WEEKLY_CLICK_FILTER = "Нажмите, чтобы показать в таблице ниже только подходящих персонажей (нажмите еще раз, чтобы сбросить).",
	ACCOUNT_WEEKLY_DELVER_ALTS_FMT = "Задания \"Вызов в вылазку\" не завершены у других персонажей: %d (%s)",
	ACCOUNT_WEEKLY_DELVER_BANKED_ALTS_FMT = "Задания \"Вызов в вылазку\" в запасе у других персонажей: %d (%s)",
	ACCOUNT_WEEKLY_DELVER_BANKED_SUFFIX = " · в запасе: %d",
	ACCOUNT_WEEKLY_DELVER_FMT = "Вызов в вылазку (этот персонаж): сдано %d / %d",
	ACCOUNT_WEEKLY_DUNDUN_FMT = "Профессии: меньше 8 Shards of Dundun на этой неделе: %d (%s)",
	ACCOUNT_WEEKLY_FILTER_ACTIVE = " |cffffcc00· фильтр таблицы|r",
	ACCOUNT_WEEKLY_FLUX_CAPPED_FMT = "Заряды катализатора полны и больше не растут: %d (%s)",
	ACCOUNT_WEEKLY_FLUX_FMT = "Заряды катализатора ждут: %d (персонажей: %d)",
	ACCOUNT_WEEKLY_FOLIO_FMT = "Фолиант омниума: выполните Mote этой недели (открыто рядов: %d/5)",
	ACCOUNT_WEEKLY_FOLIO_TT_BODY = "На всю учетную запись: выполните еженедельное задание фолианта на Террасе Магистров (Grand Magister Rommath), чтобы открыть следующий ряд рун. Одного раза на персонажа достаточно; эта строка исчезнет, когда будет 5/5.",
	ACCOUNT_WEEKLY_FOLIO_TT_TITLE = "Фолиант омниума – еженедельный Mote",
	ACCOUNT_WEEKLY_GILDED_ALTS_FMT = "Gilded Stash не завершено у других персонажей: %d (%s)",
