	DELVES_VAULT_TIER = "%d-й уровень (ур. предмета %d)",
	DELVES_VAULT_TOOLTIP_MORE = "Пройдите больше вылазок, чтобы открыть эту награду.",
	DELVE_CHAT_ATAL_AMAN_BOSS = "Духи от {SPELL:@flaying_knife} = +10% урона каждый – подбирайте свои. Уклоняйтесь от {SPELL:@raging_spirits}. До {SPELL:@claim_spirits} соберите духов, иначе бафф получит Jin'Ma.",
	DELVE_CHAT_ATAL_AMAN_OVERVIEW = "Запад Зул'Амана. Ritual / Toadly / Totem: босс Spiritflayer Jin'Ma. Venomous Vapors: босс Disciple of Vashnik.",
	DELVE_CHAT_ATAL_AMAN_ROUTE = "Ritual: спасите фурболгов. Toadly: Hex Stick на заколдованных Amani. Totem: уничтожьте тотемы, освободите Akil'zon.",
	DELVE_CHAT_ATAL_AMAN_TRASH = "Прерывайте Vilebranch. Totem: сначала тотемы на пути.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_BOSS = "Hydrangea: убейте {SPELL:@wildroot_weave} до {SPELL:@lightbloom_salvo}. Garand: уклоняйтесь от {SPELL:@shadow_laceration}, разойдитесь на {SPELL:@twilight_crash}. Vagrant: прервите {SPELL:@terrifying_power}.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_OVERVIEW = "СЗ Луносвета / Лесов Вечной Песни (университет). Siege, Faculty и Glow заканчиваются боссом. В Academic Antitoxin босса нет, только сундук.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_ROUTE = "Siege: закройте порталы Бездны. Faculty: Eye of Revelation, желтые студенты сквозь стены. Glow: Deweeder + Luminbulb. Antitoxin: 10 книг, ингредиенты, вылечить 7.",
	DELVE_CHAT_COLLEGIATE_CALAMITY_TRASH = "Siege: выходите из Void Crash, не стойте перед Phaseblades. Faculty: раскройте, затем убейте студентов. Glow: соберите Weedlings, затем один раз бросьте Deweeder.",
	DELVE_CHAT_GRUDGE_PIT_BOSS = "Brightthorn: уклоняйтесь от {SPELL:@solar_charge}, прерывайте Bloom Thorn, отвернитесь от {SPELL:@blinding_burst}. Gyrospore: уклоняйтесь от {SPELL:@fungalstorm}, выкладывайтесь во время головокружения. Mycomight: лужи подальше от боя.",
	DELVE_CHAT_GRUDGE_PIT_OVERVIEW = "ЮВ Харандара, вылазка-арена. Champion / Rotstalk / Invasion / Pharmacon. Боссы: Brightthorn, Gyrospore, Mycomight или Replicating Venomborne.",
	DELVE_CHAT_GRUDGE_PIT_ROUTE = "Champion: волны на арене (Sporbits помогают). Rotstalk: пинайте фанатов, дразните толпу. Invasion: освободите бойцов, взорвите точки появления.",
	DELVE_CHAT_GRUDGE_PIT_TRASH = "Используйте Sporbits на арене. Зачищайте волны вторжения. Не игнорируйте фанатов в Rotstalk.",
	DELVE_CHAT_GULF_OF_MEMORY_BOSS = "Lumenia: убейте помощника от {SPELL:@radiant_command}, пока он до вас не дошел. Mul'tha'ul: развейте {SPELL:@hopeless_curse}, уводите от {SPELL:@tear_it_down}, берегитесь {SPELL:@unanswered_call}.",
	DELVE_CHAT_GULF_OF_MEMORY_OVERVIEW = "Запад Харандара. Munchies / Descent / Sporasaur. Боссы: Lumenia или Mul'tha'ul.",
	DELVE_CHAT_GULF_OF_MEMORY_ROUTE = "Munchies: Alnmoth Storm на ходу. Descent: зажигайте свечи, избегайте темноты. Sporasaur: пинайте Sporbits в защищенных противников.",
	DELVE_CHAT_GULF_OF_MEMORY_TRASH = "В Descent оставайтесь на свету. Пинайте Sporbits заранее. Во время бури можно двигаться.",
	DELVE_CHAT_PARHELION_PLAZA_BOSS = "Быстро убейте 3 Voidcallers (прерывайте Void Bolt). Если один переживет {SPELL:@devouring_nova}, Slaurna сильно усиливается. Уклоняйтесь от {SPELL:@voidscar_raze}, деритесь в центре.",
	DELVE_CHAT_PARHELION_PLAZA_OVERVIEW = "Запад острова Кель'Данас (Солнечный Колодец), сложная вылазка. Bombing Run / Holding the Line / Brigade: босс Gladius Slaurna. Caustic Crush: уничтожьте Ritual Pillar.",
	DELVE_CHAT_PARHELION_PLAZA_ROUTE = "Bombing Run: тайное устройство для порталов (нести 40 с). Holding the Line: оружие + баррикады. Brigade: часовые против пилонов. Caustic Crush: убейте Slimecallers и Wavecallers.",
	DELVE_CHAT_PARHELION_PLAZA_TRASH = "Прерывайте Void Bolt у Voidcaller. Зачистите волны Devouring Host до босса.",
	DELVE_CHAT_SHADOWGUARD_POINT_BOSS = "Прерывайте {SPELL:@void_bolt_patram} и {SPELL:@submit_to_the_void}. После {SPELL:@dark_communion}: убейте помощника до конца его заклинания, иначе бафф получит Patram. Уклоняйтесь от {SPELL:@discordant_hymn}.",
	DELVE_CHAT_SHADOWGUARD_POINT_OVERVIEW = "Запад Бури Бездны. Calamitous / Wildlife / Stolen Mana против эфириалов: босс Chief-Arcanist Patram. Basilisk Blitz: босс Disciple of Vashnik.",
	DELVE_CHAT_SHADOWGUARD_POINT_ROUTE = "Calamitous: перегрузите стабилизаторы с помощью Arcane Charges. Wildlife: осторожно освобождайте существ. Mana: Galvanic Blast по контейнерам, пока не спадет Barrier. Basilisk Blitz: перенастройте генераторы, убейте 4 Energized Basilisks.",
	DELVE_CHAT_SHADOWGUARD_POINT_TRASH = "Прерывайте эфириалов. Носите заряды осторожно.",
	DELVE_CHAT_SHADOW_ENCLAVE_BOSS = "Прерывайте {SPELL:@shadow_bolt}. Телепорт оставляет лужу – держите его в центре. {SPELL:@shadowveil_annihilation}: убейте 3 сферы (бьется только сфера без щита). Бейте сферы всем, что есть.",
	DELVE_CHAT_SHADOW_ENCLAVE_OVERVIEW = "ЮЗ Лесов Вечной Песни (Смертхольм). Mirrors, supplies, traitor: босс Lord Antenorian. Infiltrate and Ameliorate: босс Abominable Blunder.",
	DELVE_CHAT_SHADOW_ENCLAVE_ROUTE = "Mirrors: бейте Shadow Nexuses ради света. Supplies: собирайте ценности Twilight. Traitor: остановите ритуалы, преследуйте до босса. Infiltrate and Ameliorate: сбросьте 5 Summoners в бездну, положите странные ингредиенты в 4 котла.",
	DELVE_CHAT_SHADOW_ENCLAVE_TRASH = "Свет зеркал = Dazzled (больше критов). Прерывайте теневых заклинателей. Не стойте толпой на опасной земле.",
	DELVE_CHAT_SUNKILLER_SANCTUM_BOSS = "Все Voidcallers должны умереть до {SPELL:@gorge}, иначе копятся стаки урона. Прерывайте {SPELL:@calling_bolt}. {SPELL:@coalescing_malediction} заканчивается появлением Voidcaller. Уклоняйтесь от {SPELL:@crushing_rift} (4 призывателя).",
	DELVE_CHAT_SUNKILLER_SANCTUM_OVERVIEW = "Восток Бури Бездны. Варианты Core / Not Expected / Gravity. Босс: Esuritus (или 3 Umbraroot, без босса).",
	DELVE_CHAT_SUNKILLER_SANCTUM_ROUTE = "Core: не дайте Domanaar украсть сферы (бафф: скорость + снижение урона). Not Expected: 3 Corrupted Umbraroot. Gravity: сингулярности снимают щиты.",
	DELVE_CHAT_SUNKILLER_SANCTUM_TRASH = "В Core подбирайте сферы. Not What I Expected: тяните 3 Corrupted Umbraroot по одному.",
	DELVE_CHAT_THE_DARKWAY_BOSS = "Прерывайте Seekers. Уклоняйтесь от {SPELL:@abyssal_burst}. {SPELL:@illusory_deceit}: держитесь подальше от взрывающихся иллюзий.",
	DELVE_CHAT_THE_DARKWAY_OVERVIEW = "Север Arcway в Луносвете. Focusers, Leyline или 7 Aberrations: босс Infiltrator Gulkat. Eggsplosive Growth: босс Replicating Venomborne.",
	DELVE_CHAT_THE_DARKWAY_ROUTE = "Focusers: верните фокусирующие устройства в центр. Leyline: активируйте каналы ради 3 кристаллов. Ogre: убейте 7 Unstable Aberrations в середине.",
	DELVE_CHAT_THE_DARKWAY_TRASH = "Прерывайте Twilight Seekers и Arcane Deluge. Выводите бой из тесных углов.",
	DELVE_CHAT_TORMENTS_RISE_BOSS = "Прерывайте каждый {SPELL:@emptiness_of_the_void}. Развейте {SPELL:@devouring_essence}. {SPELL:@oblivion_shell}: убейте помощников. Сохраните мощные способности для {SPELL:@umbral_rage}.",
	DELVE_CHAT_TORMENTS_RISE_OVERVIEW = "Вылазка Nemesis 1-го сезона (Буря Бездны), босс Nullaeus. Награды за нее больше не выдаются; Nemesis 2-го сезона – в Ядоносных глубинах.",
	DELVE_CHAT_TORMENTS_RISE_ROUTE = "Отдельный портал (Shift-J / TomTom). Это не обычная вылазка в мире с ротацией.",
	DELVE_CHAT_TORMENTS_RISE_TRASH = "Сохраните мощные способности для Nullaeus – обычных противников Pactsworn внутри нет.",
	DELVE_CHAT_TWILIGHT_CRYPTS_BOSS = "Уклоняйтесь от {SPELL:@shade_cleave} (ближний бой не дает ей использовать {SPELL:@dark_pursuit}). Вытаскивайте Darza из {SPELL:@bask_in_the_twilight} (+30% урона внутри).",
	DELVE_CHAT_TWILIGHT_CRYPTS_OVERVIEW = "ЮЗ Зул'Амана (Разрушенный трон). Loa / Party Crasher / Trapped: босс Blademaster Darza. Why'd it have to be snakes?: босс Replicating Venomborne.",
	DELVE_CHAT_TWILIGHT_CRYPTS_ROUTE = "Loa: не пересекайте путь Mot'amra. Party Crasher: сопровождение, ловушки, рычаги. Trapped: заложники + рычаги.",
	DELVE_CHAT_TWILIGHT_CRYPTS_TRASH = "Mot'amra = сильное отбрасывание на его пути. Прерывайте призывателей. Следите за плитками-ловушками.",
	DELVE_CHAT_VENOMFALL_DEEPS_BOSS = "Порядок всегда один: Noxious Bile, Void Toxin, Soul Extinction, Venom Storm – третью прерывайте всегда. На 90/60/30% встаньте в чистую четверть и запомните ПОРЯДОК; он повторяет его без подсказок. На ?? убейте Echo. Одно попадание = +500% урона от магии природы.",
	DELVE_CHAT_VENOMFALL_DEEPS_OVERVIEW = "Вылазка Nemesis, северный остров Спирального острова. Azta'rec. Уровень предметов 290 для ?, 309 для ??. Валира – лекарь. Координаты здесь не работают.",
