	LVL1080_1 = "Кампания прошлого (часто ее называют Chromie Time): поговорите с Хроми у Embassy в Штормграде или Оргриммаре и выберите сюжет одного из старых дополнений; его зоны подстроятся под ваш уровень. Игра пишет: уровни 10-70. Начните до 68-го уровня, позже войти уже нельзя.",
	LVL1080_10 = "После Кампании прошлого: The War Within (70-80). Когда один персонаж завершит кампанию этого дополнения, Режим приключений позволит другим вашим персонажам проходить его зоны в любом порядке. Вступление в Dalaran можно пропустить у Thrall в Silithus. Затем Midnight (80-90): разделы ниже.",
	LVL1080_2 = "Обучение у наставников отряда: каждый ваш персонаж, достигший 80-го уровня в The War Within, дает +5% опыта до 80-го уровня, всего до +25%. Ваш отряд – это все персонажи на вашем аккаунте.",
	LVL1080_3 = "Отдохнувший: время в таверне или городе делает вас отдохнувшим, и тогда убийства дают двойной опыт, пока запас не кончится. За 8 часов копится 5% уровня, максимум 150% уровня.",
	LVL1080_4 = "Режим войны: переключатель, при котором игроки другой фракции могут нападать на вас в открытом мире; взамен вы получаете дополнительный опыт и лучшие награды за задания. Включить его можно только в столице, а выключить – в любой таверне.",
	LVL1080_5 = "Наследство: снаряжение, которое вы собираете один раз для всего аккаунта; оно становится сильнее по мере прокачки, с улучшениями до 70-го уровня. Прямого бонуса к опыту оно больше не дает, зато есть бонус комплекта: при 2 и при 6 предметах опыт отдыха каждый раз тратится на 30% медленнее, а 5 предметов после каждого нового уровня дают прибавку к основной характеристике. Берите Наследство со Скоростью, если оно есть для вашего класса.",
	LVL1080_6 = "Высший пилотаж (быстрый стиль полета: пикируйте ради скорости, взмахивайте крыльями, чтобы набрать высоту) работает с 10-го уровня, если он уже есть на вашем аккаунте. С 20-го уровня можно переключиться на Спокойный полет – классический, более медленный стиль.",
	LVL1080_7 = "Подземелья: вставать в очередь можно с 15-го уровня. В роли бойца ждать долго, так что продолжайте выполнять задания, пока ждете.",
	LVL1080_8 = "Профессии: Травничество и Горное дело дают опыт за каждую собранную траву или руду; Снятие шкур – нет. Материалы Midnight и Знание (очки для специализаций вашей профессии) появляются только примерно на 78-80-м уровне.",
	LVL1080_9 = "Банк отряда: банк, общий для всех ваших персонажей (персональные предметы туда положить нельзя). Передавайте через него сумки, Gunshoes, планеры и Battle Standard of Coordination (+15% опыта за убийства в радиусе 100 метров).",
	LVL1080_SEC_TITLE = "1. С 10 до 80 уровня, для любого класса",
	LVL8090_BTN_OPEN_CONSUMABLES = "Открыть вкладку расходуемых предметов",
	LVL8090_BTN_OPEN_DELVES = "Открыть вылазки и хранилище",
	LVL8090_BTN_OPEN_RITUALS = "Открыть редких и ритуалы",
	LVL8090_CONS_1 = "Приоритет: сначала настой и еда, затем зелья здоровья, затем по ситуации руны или зелья урона.",
	LVL8090_CONS_2 = "Во время прокачки обычно хватает настоя и еды – руны усиления и дорогие зелья приберегите для более сложного контента.",
	LVL8090_CONS_3 = "Масла для оружия и точильные камни не дают опыта (только боевые характеристики, для конца игры) – во время прокачки пропускайте их.",
	LVL8090_GEAR_1 = "Зеленые предметы из заданий и синие из подземелий подходят на всем пути – снаряжение для прокачки одноразовое.",
	LVL8090_GEAR_2 = "Не накладывайте чары и не вставляйте самоцветы в зеленые предметы для прокачки (вы постоянно их меняете) – чары приберегите для свежего комплекта на 90-м уровне.",
	LVL8090_GEAR_3 = "Созданное снаряжение и Sparks of Radiance нужны, чтобы догнать в конце игры, а не во время прокачки.",
	LVL8090_GEAR_4 = "С наложением чар можно по пути распылять зеленые предметы из заданий (бесплатные материалы и немного опыта профессии).",
	LVL8090_GEAR_5 = "Не беспокойтесь о снаряжении до 90-го уровня – настоящий сбор снаряжения (подземелья, вылазки, хранилище) начинается на максимальном уровне.",
	LVL8090_HANDOFF_1 = "Если вы достигли 90-го уровня до конца сюжета, сначала завершите кампанию (она открывает локальные задания, известность и Режим приключений).",
	LVL8090_HANDOFF_2 = "Охота начинается у Astalor Bloodsworn в Покоях Асталора в Луносвете (вход в Закоулке душегубов). Она засчитывается в Великое хранилище, а после Охоты сложности Nightmare можно потратить Туманный сердечник Бездны на бонусный бросок.",
	LVL8090_HANDOFF_3 = "Снаряжение в 1-ю неделю: Обычный -> Героический -> Эпохальный 0 -> Эпохальный+ / обычный рейд; вылазки ради еженедельного тайника.",
	LVL8090_HANDOFF_4 = "Великое хранилище: в 1-ю неделю наберите пороги вылазок / Эпохального+ / рейдов, чтобы открыть ячейки хранилища.",
	LVL8090_HANDOFF_5 = "Дальше в дело вступают инструменты Midnight Helper для конца игры (вылазки, хранилище, редкие, ритуалы, недельная рутина).",
	LVL8090_INTRO = "Советы для любого класса: сначала уровни с 10 до 80 для всех классов, затем Midnight с 80 до 90. Таланты и ротации смотрите на Icy Veins или Wowhead.",
	LVL8090_PATH_1 = "Кампания Midnight (17 глав) доводит вас почти до 90-го уровня; остальное добирают локальные задания.",
	LVL8090_PATH_2 = "Ваш первый персонаж должен пройти кампанию – она открывает последнюю зону, Бурю Бездны.",
	LVL8090_PATH_3 = "Порядок зон: Леса Вечной Песни (80-82) -> Зул'Аман / Харандар (~82-88) -> Буря Бездны (88-90).",
	LVL8090_PATH_4 = "После кампании на одном персонаже используйте Режим приключений для других персонажей (зоны в любом порядке, без линейных 17 глав).",
	LVL8090_PATH_5 = "Короткий путь для других персонажей: на низком уровне пройдите каждую вылазку 1-го уровня, возьмите каждое задание \"Вызов в вылазку\", но не сдавайте; выполняйте задания до ~87-88-го уровня, затем сдайте их все сразу.",
	LVL8090_PATH_6 = "Первое создание предмета в профессии дает хорошую прибавку опыта, чтобы добить последний отрезок.",
	LVL8090_PATH_7 = "На других персонажах кампания дает меньше опыта, чем обычные задания; задания подземелий медленные, так что на других персонажах их пропускайте.",
	LVL8090_PATH_8 = "Всего с 80 до 90 – 4 963 065 опыта. Первое неспешное прохождение – примерно 8-10 часов; оптимизированный персонаж со всеми бонусами часто укладывается в 3-5 часов.",
	LVL8090_SEC_CONS_TITLE = "5. Расходуемые предметы во время прокачки",
	LVL8090_SEC_GEAR_TITLE = "6. Снаряжение по пути",
	LVL8090_SEC_HANDOFF_TITLE = "7. Переход на 90-м уровне",
	LVL8090_SEC_PATH_TITLE = "2. Самый быстрый путь с 80 до 90",
	LVL8090_SEC_UNLOCKS_TITLE = "4. Что открывается на каждом уровне (с 80 до 90)",
	LVL8090_SEC_XP_TITLE = "3. Ускорение опыта и бонусы аккаунта",
	LVL8090_TITLE = "Прокачка (с 10 до 90)",
	LVL8090_UNLOCK_1 = "Высший пилотаж доступен с самого начала Midnight (без Pathfinder и без прокачки репутации).",
	LVL8090_UNLOCK_2 = "Кампания прошлого (Chromie Time) охватывает уровни 10-70; на 70-м вы получаете ускоренную прокачку TWW.",
	LVL8090_UNLOCK_3 = "Режим приключений открывается для других персонажей только после того, как вы пройдете кампанию одним персонажем.",
	LVL8090_UNLOCK_4 = "До 90-го уровня персонажа вылазки доступны максимум на 3-м уровне сложности. На 90-м открываются многообещающие вылазки, а также 4-й уровень, если кампания Midnight пройдена в вашем отряде; каждый следующий уровень открывается после прохождения предыдущего.",
	LVL8090_UNLOCK_5 = "Профессии можно взять во время прокачки (Горное дело/Травничество ради золота; первые созданные предметы дают опыт).",
	LVL8090_UNLOCK_6 = "Места проведения ритуалов открываются через известность (для всего отряда) и короткую вступительную цепочку, а не на определенном уровне.",
	LVL8090_XP_1 = "Пять наставников отряда: Midnight – каждый персонаж, которого вы доведете до 90-го уровня, дает +5% к опыту при прокачке для всего аккаунта, до +25% при пяти персонажах 90-го уровня.",
	LVL8090_XP_2 = "Отдохнувший: выходите из игры в таверне или городе, чтобы получать двойной опыт, пока он не израсходуется.",
	LVL8090_XP_3 = "Режим войны дает дополнительный опыт и лучшие награды за задания в открытом мире, но игроки другой фракции могут там на вас нападать.",
	LVL8090_XP_4 = "Darkmoon Faire (первая полная неделя месяца): WHEE! (карусель) или Darkmoon Top Hat дают +10% опыта (друг с другом не складываются).",
	LVL8090_XP_5 = "Наследство перестает расти на 70-м уровне, так что с 80 до 90 оно ничего не дает (что оно делает раньше, сказано в разделе 10-80).",
	LVL8090_XP_6 = "Опыт за задания \"Вызов в вылазку\" растет с вашим уровнем, поэтому если сдать эти задания поздно (около 88-го), вы получите много опыта.",
	LVL8090_XP_7 = "Battle Standard или гильдейский флаг в группе часто дает немного дополнительного опыта.",
	MACROS_CONSUMABLES_SUBTITLE = "Лучший выбор для Midnight (настой, зелья, пир, еда). Наведите курсор на строку, чтобы увидеть подсказку предмета.",
