	PLAYCARD_102_S4 = "Тратьте астральную мощь на {SPELL:78674}, пока шкала не заполнилась.",
	PLAYCARD_102_S5 = "Больше нечего делать? {SPELL:190984}.",
	PLAYCARD_102_TERMS = "Астральная мощь – это шкала, которую заполняют ваши заклинания, а тратят {SPELL:78674} и {SPELL:191034}. {SPELL:1239669} – кнопка, которая на время усиливает вас: после {SPELL:190984} она превращается в \"Солнечное затмение\" (сильнее бьют заклинания природной магии и {SPELL:190984}), после {SPELL:194153} – в \"Лунное затмение\" (сильнее бьют заклинания тайной магии и {SPELL:194153}), а {SPELL:78674} и {SPELL:191034} усиливаются в обоих случаях.",
	PLAYCARD_102_W1 = "{SPELL:194223} включает сразу оба вида {SPELL:1239669} и ускоряет применение заклинаний. Все, что вы нажимаете в это время, бьет сильнее, поэтому берегите для этого остальные способности с восстановлением и аксессуары.",
	PLAYCARD_102_W2 = "{SPELL:8921} и {SPELL:93402} жгут цель сами по себе, а каждое их срабатывание может сбросить падающую звезду, которая дает астральную мощь. Накладывайте их до {SPELL:1239669}: усиление на них все равно действует, а внутри {SPELL:1239669} каждое применение должно быть сильным ударом.",
	PLAYCARD_102_W3 = "{SPELL:1239669} ненадолго усиливает ваши заклинания, и {SPELL:78674} тоже, поэтому приходите с накопленной астральной мощью и тратьте ее внутри. Когда оба заряда полны, новый заряд не копится, и это ожидание пропадает зря.",
	PLAYCARD_102_W4 = "{SPELL:78674} превращает астральную мощь в один из ваших самых сильных ударов. Шкала останавливается на максимуме, поэтому все, что вы получите после, теряется; к тому же это мгновенное заклинание – ваша кнопка для атаки на ходу.",
	PLAYCARD_102_W5 = "{SPELL:190984} не имеет времени восстановления, поэтому это заклинание заполняет каждую паузу и шкалу астральной мощи. Во время эффекта \"Солнечное затмение\" оно бьет намного сильнее.",
	PLAYCARD_102_WAOE = "{SPELL:93402} сжигает сразу всех врагов рядом с целью, поэтому ждите, пока они соберутся вместе; {SPELL:8921} накладывайте на каждого по очереди. {SPELL:191034} обрушивает звезды на все вокруг вас, а {SPELL:194153} задевает и врагов рядом с целью.",
	PLAYCARD_103_AOE = "{SPELL:285381} вместо {SPELL:1079}, {SPELL:213764} вместо {SPELL:5221}. Накладывайте {SPELL:1822} на нескольких врагов.",
	PLAYCARD_103_HERO1 = "Друид-хищник: на месте {SPELL:22568} загорается \"Терзание\". Нажимайте при 5 приемах серии и 50 ед. энергии.",
	PLAYCARD_103_HERO2 = "Следопыт: новых кнопок нет. Играйте по шагам выше.",
	PLAYCARD_103_IDEA = "Накапливайте приемы серии ударами когтей, затем тратьте сразу 5 на кровотечения и сильные укусы.",
	PLAYCARD_103_MISTAKE = "Нажимать {SPELL:22568}, пока на цели нет {SPELL:1079}. Кровотечения спадают, и урон падает.",
	PLAYCARD_103_S1 = "Ваш главный момент: {SPELL:106951} вместе с {SPELL:5217}. {SPELL:391528} – в то же окно.",
	PLAYCARD_103_S2 = "{SPELL:5217} – по готовности. {SPELL:274837} – пока действует {SPELL:5217}.",
	PLAYCARD_103_S3 = "Держите {SPELL:1822} и {SPELL:1079} на цели. Для {SPELL:1079} нужно 5 приемов серии.",
	PLAYCARD_103_S4 = "5 приемов серии и {SPELL:1079} на цели: {SPELL:22568}. Сначала дождитесь 50 ед. энергии.",
	PLAYCARD_103_S5 = "Больше ничего? {SPELL:5221} – ради приемов серии.",
	PLAYCARD_103_TERMS = "Приемы серии – это маленькие очки, которые копят ваши атаки когтями, до 5. Завершающий прием, например {SPELL:1079} или {SPELL:22568}, тратит их все сразу: чем больше очков, тем сильнее прием. Энергия оплачивает каждую атаку и восполняется сама.",
	PLAYCARD_103_W1 = "{SPELL:106951} усиливает все ваши удары и на время дает дополнительные приемы серии, а {SPELL:5217} добавляет свое усиление сверху. {SPELL:391528} выпускает быструю серию бесплатных атак, поэтому сильнее всего действует, когда включены оба усиления.",
	PLAYCARD_103_W2 = "{SPELL:5217} дает большой глоток энергии и усиливает ваши удары; кровотечение, начатое в это время, остается сильнее до самого конца. {SPELL:274837} дает сразу 5 приемов серии и оставляет кровотечение, поэтому применяйте эту способность во время {SPELL:5217}.",
	PLAYCARD_103_W3 = "{SPELL:1822} и {SPELL:1079} – это кровотечения: они наносят урон сами по себе и дают больше всего урона за потраченную энергию. {SPELL:1079} длится дольше за каждый потраченный прием серии, так что с 5 приемами – дольше всего.",
	PLAYCARD_103_W4 = "{SPELL:22568} может забрать дополнительную энергию, чтобы ударить до двух раз сильнее, и 50 ед. энергии дают этот бонус полностью. Используйте эту способность, только когда {SPELL:1079} надежно висит на цели: кровотечение ценнее.",
	PLAYCARD_103_W5 = "{SPELL:5221} – ваш главный способ получать приемы серии: по одному за удар. Время от времени загорается \"Ясность мысли\", и следующий удар становится бесплатным.",
	PLAYCARD_103_WAOE = "{SPELL:285381} одним нажатием накладывает кровотечение {SPELL:1079} на всех врагов вокруг вас. {SPELL:213764} бьет их всех сразу и дает прием серии, а каждое дополнительное применение {SPELL:1822} – еще одно кровотечение.",
	PLAYCARD_104_AOE = "Те же кнопки. По вам бьет больше врагов, поэтому держите больше слоев {SPELL:192081}.",
	PLAYCARD_104_HERO1 = "Друид-хищник: иногда на месте {SPELL:6807} загорается \"Терзание\" – более сильный удар, который задевает и врагов перед вами.",
	PLAYCARD_104_HERO2 = "Избранник Элуны: {SPELL:204066} – по готовности. Заполнитель: {SPELL:8921} вместо {SPELL:213764}.",
	PLAYCARD_104_IDEA = "{SPELL:33917} и {SPELL:77758} дают ярость; тратьте ее на {SPELL:192081}: это ваша броня.",
	PLAYCARD_104_MISTAKE = "Тратить всю ярость на {SPELL:6807}. Тогда на {SPELL:192081} ничего не остается, когда приходят удары.",
	PLAYCARD_104_S1 = "Идут физические удары: держите хотя бы 1 слой {SPELL:192081}. Против сильных ударов – больше слоев.",
	PLAYCARD_104_S2 = "{SPELL:33917} и {SPELL:77758} – по готовности: они дают ярость. Держите {SPELL:8921} на цели (или {SPELL:1252871} по готовности, если вы взяли этот талант).",
	PLAYCARD_104_S3 = "Перед сильным ударом или когда здоровье проседает: {SPELL:22842}. {SPELL:22812} – часто; {SPELL:61336} – для самых сильных ударов.",
	PLAYCARD_104_S4 = "Осталась ярость и вам ничто не грозит: {SPELL:6807} (или {SPELL:400254}). Больше ничего? {SPELL:213764}.",
	PLAYCARD_104_TERMS = "Ярость – боевая шкала медведя. Вы заполняете ее с помощью {SPELL:33917} и {SPELL:77758} (и немного – самим боем) и тратите на {SPELL:192081}, чтобы выжить, или на {SPELL:6807}, чтобы сильно ударить. Полная шкала больше не вмещает, поэтому тратьте до того, как она заполнится.",
	PLAYCARD_104_W1 = "{SPELL:192081} на несколько секунд делает вашу броню намного толще, а броня защищает от физических ударов вроде когтей и оружия, но намного хуже – от магии. Каждое нажатие добавляет новый слой к тем, что еще действуют, поэтому больше нажатий – меньше урона.",
	PLAYCARD_104_W2 = "{SPELL:33917} и {SPELL:77758} – источник вашей ярости, поэтому каждая секунда, пока они стоят готовыми, – это ярость, которую вы уже не получите. С талантом {SPELL:238049} эффект {SPELL:8921} на враге еще и ослабляет его удары по вам.",
	PLAYCARD_104_W3 = "{SPELL:22842} восстанавливает здоровье в течение нескольких секунд, поэтому нажимайте эту кнопку прямо перед ударом или в момент удара. {SPELL:22812} немного снижает весь урон и быстро восстанавливается; {SPELL:61336} вдвое снижает урон, но восстанавливается намного дольше.",
	PLAYCARD_104_W4 = "{SPELL:6807} превращает лишнюю ярость в сильный удар, а с талантом {SPELL:377210} этот удар еще и дает небольшой щит. {SPELL:213764} не имеет времени восстановления, но не дает ярости, поэтому только заполняет пустые моменты.",
	PLAYCARD_104_WAOE = "Больше врагов – больше физических ударов одновременно, поэтому одного слоя {SPELL:192081} мало: держите несколько. Но есть предел: после большого числа слоев новые уже не помогают.",
	PLAYCARD_105_AOE = "Перед уроном по группе: {SPELL:774} на 5 человек. Затем {SPELL:48438} и {SPELL:8936} – теперь это дешево. Огромный урон: {SPELL:740}.",
	PLAYCARD_105_EASY = "1. Заранее накладывайте HoT (исцеления, которые лечат какое-то время): {SPELL:33763} на танка, {SPELL:774} на других, по кому будут бить.\n2. У кого-то сильно просело здоровье? Восполните: {SPELL:8936}.\n3. Никого не нужно лечить? {SPELL:5176} по врагу.",
	PLAYCARD_105_HERO1 = "Следопыт (лучший выбор в этом сезоне): новой кнопки нет. {SPELL:18562} оставляет цветок: эта цель получает больше исцеления.",
	PLAYCARD_105_HERO2 = "Хранитель рощи: новой кнопки нет. Каждый маленький помощник-древень усиливает ваши исцеления, а иногда {SPELL:18562} также призывает дриаду, которая применяет уменьшенную версию {SPELL:740}.",
	PLAYCARD_105_IDEA = "Заранее накладывайте HoT, а большие провалы здоровья закрывайте с помощью {SPELL:8936}.",
	PLAYCARD_105_MISTAKE = "Делать {SPELL:8936} основным исцелением, когда не наложены 5 {SPELL:774}. Тогда это стоит много маны. С 5 наложенными – на 60% дешевле.",
	PLAYCARD_105_S1 = "Держите {SPELL:33763} постоянно: на танке или на себе в рейде. С талантом \"Поступь жизни\" {SPELL:145205} следует за этой целью; без таланта ставьте эту способность под группу.",
	PLAYCARD_105_S2 = "{SPELL:18562} – по готовности, затем {SPELL:774}: эффект {SPELL:774} ляжет сразу на 3 человек.",
	PLAYCARD_105_S3 = "Кто-то вот-вот умрет: {SPELL:8936} можно всегда. Если кнопка {SPELL:132158} готова, сначала нажмите ее – тогда это мгновенно и бесплатно.",
	PLAYCARD_105_S4 = "Никого не нужно лечить? {SPELL:5176} по врагу.",
	PLAYCARD_105_TERMS = "HoT – периодическое исцеление: оно лечит какое-то время, как {SPELL:774} и {SPELL:33763}. Каждый ваш HoT на союзнике усиливает остальные ваши исцеления на нем, а при 5 наложенных {SPELL:774} стоимость {SPELL:8936} ниже на 60%.",
	PLAYCARD_105_W1 = "{SPELL:33763} лечит все время действия, в конце распускается большим исцелением, а срабатывания эффекта могут сделать следующее применение {SPELL:8936} бесплатным. {SPELL:145205} лечит всех, кто стоит в зоне; с талантом {SPELL:1217941} зона сама следует за целью с {SPELL:33763}.",
	PLAYCARD_105_W2 = "{SPELL:18562} – мгновенное сильное исцеление, которое усиливает следующее применение {SPELL:774}: эффект лечит больше и ложится еще на двух союзников рядом. Три за одно нажатие быстро доводят до 5 {SPELL:774}, а при 5 стоимость {SPELL:8936} падает.",
	PLAYCARD_105_W3 = "{SPELL:8936} – ваше большое исцеление без времени восстановления, и на тех, у кого уже есть ваши HoT, это исцеление еще сильнее. {SPELL:132158} делает это исцеление мгновенным, бесплатным и более сильным: как раз когда нет времени на применение.",
	PLAYCARD_105_W4 = "{SPELL:5176} почти не стоит маны, а с талантом {SPELL:289237} даже возвращает часть. Каждая единица урона помогает группе быстрее закончить бой.",
	PLAYCARD_105_WAOE = "При 5 наложенных {SPELL:774} вы получаете {SPELL:207383}: {SPELL:8936} стоит намного меньше и гораздо чаще срабатывает как критическое исцеление. {SPELL:48438} лечит сразу пятерых союзников, а {SPELL:740} – всех вокруг вас, но у этой способности долгое время восстановления.",
	PLAYCARD_1467_AOE = "{SPELL:362969} становится вашим заполнителем. Удерживайте {SPELL:359073} дольше: каждый уровень задевает больше врагов. Большие группы (5 и больше): {SPELL:357211} вместо {SPELL:356995}.",
	PLAYCARD_1467_HERO1 = "Дракомандир (лучший выбор в этом сезоне): {SPELL:357210} – по готовности, до {SPELL:375087}. Прерывайте полет, как только долетите до врагов.",
	PLAYCARD_1467_HERO2 = "Ваятель огня: держите горение от {SPELL:357208} на цели; {SPELL:356995} заставляет его взорваться. Не используйте {SPELL:370553} на {SPELL:357208}.",
	PLAYCARD_1467_IDEA = "Выдыхайте огонь и синюю магию, затем тратьте сущность на длинный луч магии.",
	PLAYCARD_1467_MISTAKE = "Удерживать {SPELL:357208}, чтобы зарядить сильнее. Лучше всего первый уровень: отпускайте сразу.",
	PLAYCARD_1467_S1 = "Ваш главный момент, раз в 2 минуты: {SPELL:375087}. Сразу после – {SPELL:370553} и {SPELL:359073}.",
	PLAYCARD_1467_S2 = "{SPELL:357208} и {SPELL:359073} – по готовности. Отпускайте на первом уровне: так лучше всего.",
	PLAYCARD_1467_S3 = "Тратьте сущность на {SPELL:356995}. Загорелся эффект \"Взрывная сущность\"? Используйте: это бесплатно.",
	PLAYCARD_1467_S4 = "Больше ничего не готово? После {SPELL:359073} кнопка {SPELL:362969} превращается в {SPELL:1265867}: нажмите ее. Иначе {SPELL:361469}. На ходу: {SPELL:362969}.",
	PLAYCARD_1467_TERMS = "Сущность – шкала пробудителя: до 5 сфер (6 с талантом), которые медленно заполняются сами. {SPELL:356995} и {SPELL:357211} стоят 3. {SPELL:359565} – бесплатный заряд: следующее такое заклинание ничего не стоит.",
	PLAYCARD_1467_W1 = "Во время {SPELL:375087} {SPELL:361469} и {SPELL:362969} всегда зажигают {SPELL:359565}: много бесплатных применений {SPELL:356995}. С талантом {SPELL:375797} каждое усиленное заклинание продлевает эффект, а {SPELL:370553} делает следующее мгновенным.",
	PLAYCARD_1467_W2 = "Усиленные заклинания заряжаются, пока вы держите клавишу; отпустите, чтобы применить. Более высокий уровень {SPELL:357208} не наносит больше урона в сумме, а лишь горит короче, а {SPELL:359073} только задевает больше врагов. Поэтому против одного врага первый уровень быстрее всего и ничего не теряет.",
	PLAYCARD_1467_W3 = "{SPELL:356995} – ваш большой луч, стоит 3 ед. сущности. {SPELL:359565} делает следующее применение бесплатным, но много таких зарядов не накопить, поэтому тратьте заряд до того, как загорится новый.",
	PLAYCARD_1467_W4 = "{SPELL:361469} и {SPELL:362969} заполняют паузы и могут зажечь {SPELL:359565}. {SPELL:362969} применяется мгновенно, поэтому это ваша кнопка на бегу. После {SPELL:359073} эта кнопка на время превращается в усиленную версию – {SPELL:1265867}: сначала используйте ее.",
	PLAYCARD_1467_WAOE = "{SPELL:362969} бьет сразу 2 врагов, а {SPELL:359073} – на одного врага больше за каждый уровень, поэтому против группы удерживайте дольше. {SPELL:357211} стоит те же 3 ед. сущности, что и {SPELL:356995}, но бьет все вокруг цели, так что против большой группы наносит больше урона.",
	PLAYCARD_1468_AOE = "Перед сильным уроном по группе: \"Отголосок\" на многих. Вся группа быстро теряет здоровье: {SPELL:363534} или {SPELL:359816}, если вы взяли этот талант.",
	PLAYCARD_1468_EASY = "1. {SPELL:373861} – каждый раз по готовности. Эта способность ставит щит на группу и накладывает на нее \"Отголосок\": ваше следующее исцеление копируется на всех, на ком \"Отголосок\".\n2. {SPELL:355936} – часто: удерживайте клавишу и отпустите на первом уровне.\n3. Никто не ранен? {SPELL:361469} по врагу. Не лечите этим заклинанием: оно стоит много маны.",
	PLAYCARD_1468_HERO1 = "Ваятель огня (лучший выбор в этом сезоне): у {SPELL:355936} 2 заряда. Один тратьте по готовности, второй – когда идет сильный урон.",
	PLAYCARD_1468_HERO2 = "Хроностраж: {SPELL:370553} – по готовности, и {SPELL:360995} – часто: каждое применение ускоряет вас.",
	PLAYCARD_1468_IDEA = "Накладывайте \"Отголосок\" на союзников, затем примените одно исцеление, которое скопируется на всех.",
	PLAYCARD_1468_MISTAKE = "Лечить с помощью {SPELL:361469}. Это стоит много маны: лучше применяйте по врагам.",
	PLAYCARD_1468_S1 = "{SPELL:373861} – по готовности: щит на группу и \"Отголосок\" на всех.",
	PLAYCARD_1468_S2 = "{SPELL:355936} – часто, отпускайте на первом уровне. Это зажигает \"Благословение Меритры\".",
	PLAYCARD_1468_S3 = "Тратьте сущность на {SPELL:364343}. Загорелся эффект \"Взрывная сущность\"? {SPELL:355913}: это бесплатно.",
	PLAYCARD_1468_S4 = "Кнопка {SPELL:366155} загорелась как {SPELL:1256577}? Нажмите: все, на ком \"Отголосок\", тоже получат эффект.",
	PLAYCARD_1468_S5 = "У одного человека мало здоровья: {SPELL:360995}. Никто не ранен: {SPELL:361469} по врагу.",
	PLAYCARD_1468_TERMS = "{SPELL:364343} – бронзовая метка на союзнике. Следующее ваше исцеление (не заклинание за сущность) также применяется ко всем, на ком есть {SPELL:364343}, чуть слабее. {SPELL:364343} дает полную метку {SPELL:364343} за 2 ед. сущности; {SPELL:373861} дает более слабые без затрат сущности.",
	PLAYCARD_1468_W1 = "{SPELL:373861} летит вперед по линии: ставит щит на всех, кого коснется, и накладывает ослабленную метку {SPELL:364343} не более чем на 5 из них. Сущность не нужна, так что ваша сущность остается для новых меток {SPELL:364343}.",
	PLAYCARD_1468_W2 = "Каждый уровень {SPELL:355936} в сумме лечит одинаково; первый просто растягивает исцеление на большее время и быстрее всего применяется. Кроме того, каждое применение {SPELL:355936} зажигает для вас {SPELL:1256577}.",
	PLAYCARD_1468_W3 = "{SPELL:364343} стоит 2 ед. сущности, и ваше следующее исцеление также попадает на этого союзника. {SPELL:355913} стоит 3, поэтому применяйте это заклинание, когда {SPELL:369297} делает его бесплатным: ваши метки {SPELL:364343} при этом не расходуются.",
	PLAYCARD_1468_W4 = "{SPELL:1256577} – усиленная версия {SPELL:366155}, которая появляется на этой кнопке: лечит вашу цель, а затем перескакивает еще на 4 союзников. Все с {SPELL:364343} тоже получают копию, поэтому применяйте, когда метки {SPELL:364343} разложены.",
	PLAYCARD_1468_W5 = "{SPELL:360995} переносит вас к союзнику и сразу сильно его лечит: ваша самая быстрая помощь одному человеку. {SPELL:361469} по врагу возвращает часть маны и может зажечь {SPELL:369297}.",
	PLAYCARD_1468_WAOE = "Сначала {SPELL:364343}, потом исцеление: одно исцеление тогда попадает на всех с {SPELL:364343}, так что подготовьте метки до урона. {SPELL:363534} возвращает часть урона, полученного всеми рядом с вами за последние несколько секунд; {SPELL:359816} лечит всех, над кем вы пролетаете.",
	PLAYCARD_1473_AOE = "Те же кнопки. Удерживайте {SPELL:396286} дольше, чтобы круг задел больше врагов.",
	PLAYCARD_1473_HERO1 = "Хроностраж (лучший выбор в этом сезоне): {SPELL:370553} еще и ускоряет вас. Нажимайте вместе с {SPELL:403631}.",
	PLAYCARD_1473_HERO2 = "Дракомандир: {SPELL:395160} бьет сильнее. Кнопки остаются те же.",
	PLAYCARD_1473_IDEA = "Вы усиливаете союзников. Поддерживайте свои положительные эффекты и тратьте сущность, пока действует {SPELL:395152}.",
	PLAYCARD_1473_MISTAKE = "Тратить сущность, когда {SPELL:395152} не действует. Ваши удары продлевают эффект, только пока он действует.",
	PLAYCARD_1473_S1 = "Держите {SPELL:395152} активным. Применяйте снова, когда осталось 4 сек. или меньше.",
	PLAYCARD_1473_S2 = "{SPELL:409311} – на двух самых сильных бойцов. Поддерживайте эффект на них.",
	PLAYCARD_1473_S3 = "Главный момент: {SPELL:403631} по готовности; не задерживайте надолго ради группы. Затем {SPELL:370553} и {SPELL:357208}.",
	PLAYCARD_1473_S4 = "{SPELL:357208} и {SPELL:396286} – по готовности, пока действует {SPELL:395152}. {SPELL:396286}: отпускайте на первом уровне. {SPELL:357208}: удерживайте до максимума, если только не готова и кнопка {SPELL:396286}.",
	PLAYCARD_1473_S5 = "Тратьте сущность на {SPELL:395160}. Больше ничего не готово? {SPELL:361469}.",
	PLAYCARD_1473_TERMS = "Сущность – шкала пробудителя: до 5 сфер (6 с талантом), которые медленно заполняются сами; {SPELL:395160} стоит 3. Пока действует {SPELL:395152}, каждое применение {SPELL:395160}, каждое усиленное заклинание и {SPELL:403631} продлевают эффект: вот почему тратить нужно в это время.",
	PLAYCARD_1473_W1 = "{SPELL:395152} усиливает ваших бойцов частью вашей основной характеристики, и вы сами тоже бьете сильнее. Обновляйте эффект, когда осталось несколько секунд: оставшееся время добавится, так что разрыва не будет.",
	PLAYCARD_1473_W2 = "{SPELL:409311} дает одному союзнику дополнительный шанс критического удара, а с талантом {SPELL:412774} часть его ударов получает небольшую дополнительную копию. Больше всего пользы получают лучшие игроки, так что отдавайте эффект им.",
	PLAYCARD_1473_W3 = "{SPELL:403631} помечает врагов, над которыми вы пролетаете: пока метка действует, часть всего урона ваших союзников под {SPELL:395152} накапливается и бьет по ним еще раз. Способность также призывает вашу копию (талант {SPELL:1259173}), поэтому нажимать по готовности лучше, чем ждать; затем {SPELL:370553} делает применение {SPELL:357208} на максимальном уровне мгновенным.",
	PLAYCARD_1473_W4 = "Каждое усиленное заклинание немного продлевает {SPELL:395152}, поэтому применяйте их, только пока эффект действует. {SPELL:396286} при более долгом удержании лишь расширяет круг, так что против одного врага хватит первого уровня. {SPELL:357208} максимального уровня заставляет следующее применение {SPELL:361469} лететь в большее число целей, и каждое попадание может зажечь {SPELL:396187}.",
	PLAYCARD_1473_W5 = "Каждое применение {SPELL:395160} немного продлевает {SPELL:395152}, поэтому сущность уходит туда. {SPELL:361469} заполняет паузы и может зажечь {SPELL:396187}: бесплатное применение {SPELL:395160}.",
	PLAYCARD_1473_WAOE = "Круг {SPELL:396286} растет с каждым уровнем удержания, поэтому удерживайте, пока круг не накроет всю группу врагов.",
	PLAYCARD_1480_AOE = "Не используйте обычную версию {SPELL:1226019}. После полного применения {SPELL:473728} кнопка превращается в {SPELL:1225826}: нажимайте ее, когда вокруг около 10 душ.",
	PLAYCARD_1480_HERO1 = "Зараженные Бездной (лучший выбор в этом сезоне): {SPELL:1245412} и {SPELL:1246167} прямо перед {SPELL:1217605}, затем нажимайте {SPELL:1245483}, {SPELL:1259431} и {SPELL:1245470}, когда они загораются.",
	PLAYCARD_1480_HERO2 = "Разрушитель: при 3 стаках эффекта \"Безднопад\" – сразу {SPELL:1226019}. В облике демона – {SPELL:1221150} каждый раз, когда кнопка загорается.",
	PLAYCARD_1480_IDEA = "Собирайте души и гнев на расстоянии. Когда душ достаточно, вы превращаетесь в демона Бездны, который бьет гораздо сильнее.",
	PLAYCARD_1480_MISTAKE = "Прерывать {SPELL:473728} раньше времени, чтобы сдвинуться: вы теряете урон, и {SPELL:1225826} не загорается.",
	PLAYCARD_1480_S1 = "Достаточно душ? {SPELL:1217605}. Вы остаетесь демоном, пока не кончится гнев.",
	PLAYCARD_1480_S2 = "{SPELL:1226019} – когда вокруг лежат 4 души или больше: способность собирает их. В облике демона кнопка превращается в {SPELL:1245453}.",
	PLAYCARD_1480_S3 = "100 ед. гнева: {SPELL:473728}. В облике демона это бесплатно: применяйте по готовности.",
	PLAYCARD_1480_S4 = "{SPELL:1241937} – когда эффект не действует, но не в облике демона: дает души, гнев и исцеление.",
	PLAYCARD_1480_S5 = "Больше ничего не готово? {SPELL:473662}. В облике демона кнопка превращается в {SPELL:1217610}.",
	PLAYCARD_1480_TERMS = "Души – маленькие сферы, которые выскакивают из врагов, когда вы их бьете. Каждая подобранная душа дает гнев и засчитывается для {SPELL:1217605}, а для этого нужно 50 душ (35 с талантом {SPELL:1247534}). {SPELL:1226019} притягивает до 4 душ рядом за раз.",
	PLAYCARD_1480_W1 = "Каждая подобранная душа засчитывается для {SPELL:1217605}; когда душ достаточно, кнопка загорается. В облике демона Бездны все ваши заклинания бьют сильнее, но гнев медленно утекает, и облик заканчивается, когда гнев доходит до нуля.",
	PLAYCARD_1480_W2 = "{SPELL:1226019} притягивает до 4 душ за раз, и каждая душа дает гнев и засчитывается для облика демона. Если душ рядом меньше, часть эффекта пропадает, так что ждите 4. В облике демона кнопка превращается в более сильную версию – {SPELL:1245453}.",
	PLAYCARD_1480_W3 = "{SPELL:473728} – ваш большой луч: ему нужно 100 ед. гнева, и он превращает их в мощный урон, так что не давайте гневу копиться впустую. В облике демона луч ничего не стоит и даже замедляет утекание гнева, пока действует.",
	PLAYCARD_1480_W4 = "{SPELL:1241937} на несколько секунд поджигает вашу душу: лечит вас, дает гнев и выбивает души, пока вы продолжаете применять заклинания. В облике демона время лучше потратить на {SPELL:1217610}, так что используйте эту способность вне облика.",
	PLAYCARD_1480_W5 = "{SPELL:473662} не имеет времени восстановления и применяется на ходу, поэтому заполняет каждую паузу и дает гнев (с талантом – еще и душу). В облике демона кнопка превращается в {SPELL:1217610}, а эта версия к тому же быстрее готовит {SPELL:1245453}.",
	PLAYCARD_1480_WAOE = "Обычное применение {SPELL:1226019} съело бы души, которые вы копите. После полного применения {SPELL:473728} способность {SPELL:1225826} бьет целый конус врагов и может притянуть до 10 душ за раз, так что дайте душам накопиться.",
	PLAYCARD_250_AOE = "{SPELL:50842} чаще: бьет всех врагов вокруг вас. Держите {SPELL:43265} под группой врагов.",
	PLAYCARD_250_HERO1 = "Сан'лейн (лучший выбор в этом сезоне): во время {SPELL:49028} один раз {SPELL:50842}, затем только {SPELL:433895} и {SPELL:49998}.",
	PLAYCARD_250_HERO2 = "Вестник Смерти: сначала {SPELL:439843}, затем {SPELL:49028}. Когда загорается {SPELL:195182}, используйте, пока подсветка не погасла.",
	PLAYCARD_250_IDEA = "Лечите себя с помощью {SPELL:49998} и поддерживайте {SPELL:195181} с помощью {SPELL:195182}: это ваша броня.",
	PLAYCARD_250_MISTAKE = "{SPELL:49998} при полном здоровье. Эта способность лечит на величину урона за последние 5 секунд, поэтому нажимайте ее после удара (если только сила рун не почти полная).",
	PLAYCARD_250_S1 = "Только что получили сильный удар или силы рун больше 70? {SPELL:49998}.",
	PLAYCARD_250_S2 = "Зарядов {SPELL:195181} 5 или меньше? {SPELL:195182}. Никогда не давайте эффекту спасть.",
	PLAYCARD_250_S3 = "{SPELL:49028} – по готовности. Стойте в зоне {SPELL:43265}; ставьте заново, когда она исчезнет.",
	PLAYCARD_250_S4 = "{SPELL:50842} – до того, как накопятся все заряды. Больше ничего не готово? {SPELL:206930}.",
	PLAYCARD_250_TERMS = "У рыцарей смерти два ресурса. У вас 6 рун; они восполняются сами, но только по 3 одновременно, поэтому тратьте их постоянно. Каждая потраченная руна заполняет шкалу силы рун, а {SPELL:49998} ее тратит.",
	PLAYCARD_250_W1 = "{SPELL:49998} восстанавливает часть урона, полученного за последние 5 секунд, поэтому лучше всего лечит сразу после сильного удара. Шкала силы рун перестает заполняться, когда полна, так что тратьте силу рун раньше.",
	PLAYCARD_250_W2 = "{SPELL:195181} дает дополнительную броню и ускоряет восполнение рун. Каждый полученный удар тратит заряд, а при 5 зарядах и больше {SPELL:49998} стоит меньше (талант {SPELL:219786}), поэтому {SPELL:195182} добавляет 3 новых заряда, пока их не стало меньше.",
	PLAYCARD_250_W3 = "{SPELL:49028} призывает парящую копию вашего оружия, которая повторяет ваши атаки: на короткое время больше урона, больше силы рун и выше шанс парирования. Если стоять в зоне {SPELL:43265}, {SPELL:206930} задевает больше врагов, а с нужными талантами вы там сильнее бьете и больше лечитесь.",
	PLAYCARD_250_W4 = "{SPELL:50842} не стоит рун, а заряды восполняются сами, но восполнение останавливается, когда все заряды полны, так что тратьте один заранее. {SPELL:206930} тратит руну и дает силу рун; не давайте рунам простаивать, ведь восполняются только 3 одновременно.",
	PLAYCARD_250_WAOE = "{SPELL:50842} бьет всех врагов рядом и накладывает на них всех болезнь \"Кровавая чума\", а с талантом {SPELL:273946} каждый пораженный враг усиливает следующее применение {SPELL:49998}. {SPELL:43265} под группой ранит всех врагов, а внутри зоны {SPELL:206930} задевает больше из них.",
	PLAYCARD_251_AOE = "3 врага и больше: {SPELL:207230} вместо {SPELL:49020} и {SPELL:194913} вместо {SPELL:49143}.",
	PLAYCARD_251_HERO1 = "Вестник Смерти: {SPELL:439843} вместе с {SPELL:51271} (одним макросом). Это дает дополнительные эффекты \"Машина для убийств\", которые нужно потратить в это время.",
	PLAYCARD_251_HERO2 = "Всадник апокалипсиса: дополнительной кнопки нет. Всадники приходят сами; просто играйте по шагам выше.",
	PLAYCARD_251_IDEA = "Тратьте руны на {SPELL:49020}, силу рун – на {SPELL:49143}, и пользуйтесь бесплатными ударами, когда они загораются.",
	PLAYCARD_251_MISTAKE = "{SPELL:49184} без эффекта \"Иней\". Без подсветки эта способность слишком слаба, чтобы тратить на нее руну.",
	PLAYCARD_251_S1 = "{SPELL:51271} по готовности, затем {SPELL:279302}: ваш главный момент. {SPELL:1249658} – туда же, если есть.",
	PLAYCARD_251_S2 = "{SPELL:49020} – когда кнопку подсвечивает \"Машина для убийств\". {SPELL:49184} – только когда кнопку подсвечивает \"Иней\".",
	PLAYCARD_251_S3 = "Тратьте силу рун на {SPELL:49143}. Сила рун кончилась? {SPELL:47568}.",
	PLAYCARD_251_S4 = "Больше ничего не готово? Обычное применение {SPELL:49020}.",
	PLAYCARD_251_TERMS = "У рыцарей смерти два ресурса. У вас 6 рун для {SPELL:49020}; они восполняются сами, но только по 3 одновременно. Траты рун заполняют шкалу силы рун, а {SPELL:49143} ее тратит.",
	PLAYCARD_251_W1 = "{SPELL:51271} на несколько секунд делает вас намного сильнее, поэтому вкладывайте в это время самые сильные удары. {SPELL:279302} пускает ледяного змея сквозь врагов перед вами, а {SPELL:1249658} дышит морозом дольше каждый раз, когда вы используете {SPELL:51128} или {SPELL:59057}.",
	PLAYCARD_251_W2 = "{SPELL:51128} делает следующее применение {SPELL:49020} гарантированным критическим ударом с уроном от магии льда, поэтому удар намного сильнее; эффект приходит в основном от обычных атак, и накопить можно только 2. {SPELL:59057} делает следующее применение {SPELL:49184} бесплатным и намного более сильным; этот эффект дает {SPELL:49143}.",
	PLAYCARD_251_W3 = "{SPELL:49143} превращает силу рун в сильный ледяной удар, может зажечь {SPELL:59057} и иногда возвращает руну. Пусто? {SPELL:47568} дает {SPELL:51128} и новую силу рун, так что вы пропускаете слабое обычное применение {SPELL:49020}.",
	PLAYCARD_251_W4 = "Обычное применение {SPELL:49020} бьет слабо, но тратит руны и заполняет силу рун для {SPELL:49143}. Руны восполняются только по 3 одновременно, поэтому полная шкала рун – это потерянное время.",
	PLAYCARD_251_WAOE = "{SPELL:207230} рассекает всех врагов перед вами, а с {SPELL:51128} критический удар этой способности бьет в 4 раза сильнее. {SPELL:194913} пускает ледяные шипы по линии через группу врагов, поэтому встаньте у края и повернитесь к группе.",
	PLAYCARD_252_AOE = "Поставьте {SPELL:43265} под группу врагов (с талантом \"Цикл смерти\"). 3 врага и больше: {SPELL:207317} вместо {SPELL:47541}.",
	PLAYCARD_252_HERO1 = "Всадник апокалипсиса: дополнительной кнопки нет. Всадники приходят сами; просто играйте по шагам выше.",
	PLAYCARD_252_HERO2 = "Сан'лейн: во время {SPELL:1233448} кнопка {SPELL:55090} превращается в {SPELL:433895}. Нажимайте ее часто, чтобы ее положительный эффект не спадал.",
	PLAYCARD_252_IDEA = "Накапливайте помощников \"Мелкий вурдалак\" с помощью {SPELL:85948}, используйте их с помощью {SPELL:55090} и тратьте силу рун на {SPELL:47541}.",
	PLAYCARD_252_MISTAKE = "Позволять болезни спасть с цели: нет болезни – меньше дешевых и сильных применений {SPELL:47541}.",
	PLAYCARD_252_S1 = "{SPELL:1233448} – по готовности, каждый второй раз вместе с {SPELL:42650}: ваш главный момент.",
	PLAYCARD_252_S2 = "Держите болезнь на цели с помощью {SPELL:77575}. Пока действует {SPELL:1233448}, нажимайте {SPELL:1247378}.",
	PLAYCARD_252_S3 = "{SPELL:47541} – когда кнопка загорается. {SPELL:458128} (появляется после {SPELL:85948}) – когда эффект на враге почти закончился.",
	PLAYCARD_252_S4 = "Нет помощников \"Мелкий вурдалак\"? {SPELL:85948}. Есть? {SPELL:55090}.",
	PLAYCARD_252_S5 = "Больше ничего не готово? {SPELL:47541}.",
	PLAYCARD_252_TERMS = "\"Мелкий вурдалак\" – маленький помощник, который сражается недолго. {SPELL:85948} дает заряды для них, а каждое применение {SPELL:55090} тратит один заряд, чтобы призвать вурдалака; число на кнопке {SPELL:55090} показывает, сколько осталось.",
	PLAYCARD_252_W1 = "{SPELL:1233448} превращает вашего вурдалака в чудовище, а с талантом {SPELL:390259} сильнее бьет и остальная ваша нежить, поэтому нажимайте, когда {SPELL:42650} приводит своих вурдалаков. Эта способность восстанавливается вдвое быстрее армии, так что между ними используйте ее отдельно.",
	PLAYCARD_252_W2 = "\"Ужасная чума\" от {SPELL:77575} – то, что зажигает {SPELL:47541}, поэтому болезнь должна висеть постоянно. {SPELL:1247378} бросает взрывающегося вурдалака, а {SPELL:1233448} усиливает взрыв ({SPELL:390259}), так что тратьте в это время.",
	PLAYCARD_252_W3 = "Когда {SPELL:47541} загорается ({SPELL:49530}), это стоит меньше и бьет сильнее, так что используйте, пока подсветка не погасла. {SPELL:458128} на время ускоряет срабатывание ваших болезней, а более частые срабатывания чаще зажигают {SPELL:47541}.",
	PLAYCARD_252_W4 = "{SPELL:85948} заряжает ваше оружие, чтобы следующие несколько применений {SPELL:55090} призывали по помощнику \"Мелкий вурдалак\", который сражается за вас. {SPELL:55090} также заставляет ваши болезни взрываться, нанося дополнительный урон.",
	PLAYCARD_252_W5 = "{SPELL:47541} тратит силу рун, которая иначе переполнилась бы, немного продлевает ваши болезни и {SPELL:1233448}, а трата силы рун может ускорить восполнение рун.",
	PLAYCARD_252_WAOE = "{SPELL:207317} заставляет чуму на всех врагах взорваться разом, поэтому при 3 врагах и больше эта способность сильнее, чем {SPELL:47541}. С талантом {SPELL:1290864} каждый враг в зоне {SPELL:43265} ускоряет готовность {SPELL:1247378}.",
	PLAYCARD_253_AOE = "{SPELL:1264359} – по готовности и сразу после {SPELL:19574}: тогда ваши питомцы бьют всех врагов.",
	PLAYCARD_253_HERO1 = "Вожак стаи (лучший выбор в этом сезоне): после {SPELL:19574} кнопка {SPELL:34026} призывает зверя и \"Звериный натиск\". Направьте эту линию через группу врагов.",
	PLAYCARD_253_HERO2 = "Темный следопыт: {SPELL:466930} – при любой возможности в первые 10 секунд {SPELL:19574}; завершите это окно с помощью {SPELL:392060}.",
	PLAYCARD_253_IDEA = "Основную работу делают питомцы: вы отправляете их в бой и поддерживаете их ярость.",
	PLAYCARD_253_MISTAKE = "Позволять {SPELL:217200} или {SPELL:34026} стоять с 2 зарядами: это выброшенный бесплатный урон.",
	PLAYCARD_253_S1 = "{SPELL:19574} – каждый раз по готовности, примерно раз в 30 секунд. Прямо перед этим выпустите {SPELL:217200}.",
	PLAYCARD_253_S2 = "{SPELL:34026} – по готовности, но между двумя применениями вставляйте другой выстрел.",
	PLAYCARD_253_S3 = "{SPELL:217200} – до того, как накопятся 2 заряда: кровотечение растет и дает концентрацию.",
	PLAYCARD_253_S4 = "Больше ничего не готово? {SPELL:193455}. Это также ускоряет готовность {SPELL:34026}.",
	PLAYCARD_253_TERMS = "Заряды: некоторые кнопки можно копить, как стрелы в колчане. У {SPELL:217200} и {SPELL:34026} по 2 заряда. Пока оба полны, новый не заряжается, и это время теряется.",
	PLAYCARD_253_W1 = "{SPELL:19574} на время усиливает вас и ваших питомцев и дает дополнительный заряд {SPELL:217200}. Выпустите один заряд прямо перед этим, чтобы для дополнительного было место и он не пропал.",
	PLAYCARD_253_W2 = "{SPELL:34026} посылает питомца нанести один из ваших самых сильных ударов. Другие ваши выстрелы усиливают следующее применение {SPELL:34026} (талант {SPELL:1273126}), но этот бонус не суммируется, поэтому два применения {SPELL:34026} подряд тратят его впустую.",
	PLAYCARD_253_W3 = "{SPELL:217200} вызывает у врага кровотечение и дает вам концентрацию, пока оно идет. Новый выстрел добавляет остаток старого кровотечения к новому, а при 2 зарядах перезарядка останавливается, так что продолжайте использовать.",
	PLAYCARD_253_W4 = "{SPELL:193455} стоит немного и ускоряет готовность {SPELL:34026}. Во время {SPELL:19574} эта способность может даже сразу восстановить {SPELL:34026} (талант {SPELL:199532}).",
	PLAYCARD_253_WAOE = "{SPELL:1264359} ненадолго заставляет укусы ваших питомцев бить всех врагов рядом с ними. {SPELL:19574} также заставляет питомцев наносить сильные удары, а {SPELL:1264359} сразу после этого позволяет этим ударам задеть и всю группу врагов.",
	PLAYCARD_254_AOE = "{SPELL:257620} вместо {SPELL:185358}. Если выстрел заденет 3 врагов или больше, следующее применение {SPELL:19434} или {SPELL:257044} тоже заденет тех, кто вокруг цели: перед каждым из них – снова {SPELL:257620}.",
	PLAYCARD_254_HERO1 = "Часовой (лучший выбор в этом сезоне): бросайте \"Лунный шакрам\" ближе к концу {SPELL:288613}, когда остается около 5 секунд.",
	PLAYCARD_254_HERO2 = "Темный следопыт: вместо этого тратьте подсвеченный выстрел на {SPELL:466930}. Затем кнопка {SPELL:288613} превращается в {SPELL:392060}: нажмите ее один раз.",
	PLAYCARD_254_IDEA = "Стреляйте издалека: {SPELL:19434} усиливает ваш следующий выстрел, и вы тратите его на {SPELL:185358}.",
	PLAYCARD_254_MISTAKE = "Позволять {SPELL:19434} стоять с 2 зарядами: эта мощная стрела потеряна навсегда.",
	PLAYCARD_254_S1 = "{SPELL:212431} дважды подряд и {SPELL:260243} – по готовности.",
	PLAYCARD_254_S2 = "{SPELL:288613} – по готовности: ваш главный момент, примерно раз в 1,5–2 минуты.",
	PLAYCARD_254_S3 = "{SPELL:257044} – по готовности. Затем {SPELL:19434}; не давайте этой кнопке стоять с 2 зарядами.",
	PLAYCARD_254_S4 = "После {SPELL:19434} загорелся следующий выстрел? Потратьте его на {SPELL:185358} до следующего применения способности \"Прицельный выстрел\".",
	PLAYCARD_254_S5 = "Больше ничего не готово? {SPELL:56641}. Продолжайте стрелять, в том числе на ходу.",
	PLAYCARD_254_TERMS = "{SPELL:260240}: после {SPELL:19434} загорается кнопка {SPELL:185358} или {SPELL:257620}. Этот выстрел бьет сильнее и стоит меньше концентрации. Держать можно только один, поэтому тратьте его до следующего применения {SPELL:19434}.",
	PLAYCARD_254_W1 = "{SPELL:212431} – бомба, которая жжет врага и взрывается на соседних врагах; с талантом {SPELL:473520} вторая сразу после первой бесплатна. {SPELL:260243} обрушивает дождь стрел, и пока он идет, ваши выстрелы отскакивают в других врагов.",
	PLAYCARD_254_W2 = "{SPELL:288613} повышает шанс и силу критических ударов ваших выстрелов и намного быстрее восстанавливает {SPELL:19434} и {SPELL:257044}. Так в это время помещается гораздо больше мощных выстрелов.",
	PLAYCARD_254_W3 = "{SPELL:257044} выпускает быструю очередь стрел, даже на ходу, а с талантом {SPELL:389019} усиливает следующее применение {SPELL:19434}. У {SPELL:19434} 2 заряда; пока оба полны, новый не заряжается.",
	PLAYCARD_254_W4 = "После {SPELL:19434} следующее применение {SPELL:185358} бьет намного сильнее и стоит меньше концентрации. Держать можно только один такой эффект, поэтому второе применение {SPELL:19434} сначала выбрасывает первый.",
	PLAYCARD_254_W5 = "{SPELL:56641} работает на ходу, дает концентрацию и ускоряет готовность {SPELL:19434}. Так даже самая слабая кнопка помогает самой сильной.",
	PLAYCARD_254_WAOE = "{SPELL:257620} бьет все рядом с целью. Если задето 3 врага или больше, следующее применение {SPELL:19434} или {SPELL:257044} тоже отскакивает во врагов вокруг, поэтому нажимайте {SPELL:257620} снова перед каждым из них.",
	PLAYCARD_255_AOE = "Те же кнопки. Вставайте так, чтобы конусы {SPELL:1261193} и {SPELL:259495} задевали всю группу врагов.",
	PLAYCARD_255_HERO1 = "Часовой (лучший выбор в этом сезоне): {SPELL:1250646} один раз превращается в \"Лунный шакрам\"; бросьте его до конца эффекта \"Захват врасплох\". Загорелся эффект \"Метка часового\" на цели? Сразу {SPELL:259495}.",
	PLAYCARD_255_HERO2 = "Вожак стаи: когда загорается \"Вой вожака стаи\", {SPELL:259489} призывает зверя. Во время {SPELL:1250646} направьте линию эффекта \"Звериный натиск\".",
	PLAYCARD_255_IDEA = "Сражайтесь вблизи вместе с питомцем: каждое применение {SPELL:259489} усиливает ваши следующие 2 атаки.",
	PLAYCARD_255_MISTAKE = "Нажимать {SPELL:259489} слишком часто: лишняя концентрация и усиления пропадают. Вставляйте между ними две другие атаки.",
	PLAYCARD_255_S1 = "{SPELL:1250646} – по готовности: ваш главный момент. Прямо перед этим нажмите {SPELL:259489}.",
	PLAYCARD_255_S2 = "Цикл: {SPELL:259489}, затем две другие атаки, затем снова {SPELL:259489}.",
	PLAYCARD_255_S3 = "{SPELL:1261193} и {SPELL:259495} – по готовности. Не давайте {SPELL:259495} стоять с 2 зарядами.",
	PLAYCARD_255_S4 = "Остаток концентрации тратьте на {SPELL:186270}. Каждое второе применение превращается в \"Взмах ящера\".",
	PLAYCARD_255_TERMS = "{SPELL:260285}: каждое применение {SPELL:259489} дает 2 таких эффекта (1 без таланта {SPELL:1272154}). Ваша следующая атака тратит один и бьет сильнее. Держать можно максимум 3; лишние теряются.",
	PLAYCARD_255_W1 = "{SPELL:1250646} – мощный удар в прыжке, и на короткое время вы с питомцем бьете сильнее. Вы и питомец тратите на него по одному эффекту {SPELL:260285}, поэтому прямо перед этим нажмите {SPELL:259489} (с талантом {SPELL:1272139} способность {SPELL:1250646} приносит свои эффекты: тогда применяйте ее без них).",
	PLAYCARD_255_W2 = "Каждое применение {SPELL:259489} дает 2 эффекта {SPELL:260285} (талант {SPELL:1272154}), и следующие 2 атаки тратят их, чтобы бить сильнее. Держать можно только 3, поэтому два применения {SPELL:259489} подряд тратят один впустую.",
	PLAYCARD_255_W3 = "{SPELL:259495} взрывается конусом за врагом и поджигает врагов; у этой способности 2 заряда, и пока оба полны, новый не заряжается. {SPELL:1261193} – мощный выстрел дробью с долгим временем восстановления, так что никогда не заставляйте эту кнопку ждать.",
	PLAYCARD_255_W4 = "{SPELL:186270} – то, на что уходит концентрация. На 90-м уровне каждое второе применение превращается в {SPELL:1259003}, а эта версия бьет всех перед вами и намного сильнее, поэтому тратьте на нее {SPELL:260285}.",
	PLAYCARD_255_WAOE = "{SPELL:1261193} и {SPELL:259495} бьют конусом, поэтому вставайте так, чтобы конусы накрывали всю группу. Каждый враг, по которому попадает {SPELL:259495}, ускоряет готовность {SPELL:1261193} (талант {SPELL:1262409}), так что в большой группе кнопка {SPELL:1261193} готова очень часто.",
	PLAYCARD_256_AOE = "Перед уроном по всей группе: {SPELL:194509} дает {SPELL:81749} до пяти союзников, затем бейте сильно. Идет сильный удар? Сначала {SPELL:472433}.",
	PLAYCARD_256_EASY = "1. {SPELL:17} на союзника, по которому вот-вот ударят. Это дает ему {SPELL:81749}: пока эффект действует, ваш урон его лечит.\n2. Бейте врага: держите на нем {SPELL:589}, {SPELL:8092} и {SPELL:47540} – по готовности, а {SPELL:585} – когда больше ничего не готово.\n3. У кого-то очень мало здоровья? {SPELL:186263} на него (или {SPELL:2061}, если этого заклинания у вас нет). Затем снова шаг 1.",
	PLAYCARD_256_HERO1 = "Ткач Бездны (лучший выбор в рейдах): {SPELL:8092} открывает разлом. Стойте на месте и применяйте {SPELL:450215}, пока он открыт.",
	PLAYCARD_256_HERO2 = "Оракул (лучший выбор в подземельях): у {SPELL:47540} появляется второй заряд. Применяйте {SPELL:17} сразу после каждого применения {SPELL:47540}.",
	PLAYCARD_256_IDEA = "Вы лечите, нанося урон врагам: каждый союзник с {SPELL:81749} получает исцеление от вашего урона.",
	PLAYCARD_256_MISTAKE = "Бить врагов, когда ни у кого нет {SPELL:81749}: тогда ваш урон никого не лечит.",
	PLAYCARD_256_S1 = "Постоянно держите {SPELL:589} на враге.",
	PLAYCARD_256_S2 = "{SPELL:17} на союзника, по которому вот-вот ударят: щит, плюс {SPELL:81749}. Когда кнопка превращается в {SPELL:1253593}, используйте ее поскорее.",
	PLAYCARD_256_S3 = "{SPELL:8092} и {SPELL:47540} – по готовности: они сильно бьют и усиливают ваши щиты.",
	PLAYCARD_256_S4 = "Больше ничего не готово? {SPELL:585}. У кого-то очень мало здоровья? {SPELL:186263} на него или {SPELL:2061}, если вы не выбрали этот талант.",
	PLAYCARD_256_TERMS = "{SPELL:81749} – метка, которую вы накладываете на союзника с помощью {SPELL:17}, {SPELL:194509}, {SPELL:2061} или {SPELL:186263}. Пока она действует, часть всего вашего урона лечит этого союзника. Если помеченных больше 5, каждый получает чуть меньше.",
	PLAYCARD_256_W1 = "{SPELL:589} – периодический урон по врагу, и каждое срабатывание лечит ваших союзников с {SPELL:81749}. Эти срабатывания также могут усилить следующее применение {SPELL:47540}.",
	PLAYCARD_256_W2 = "{SPELL:17} дает союзнику {SPELL:81749} и щит, поглощающий урон. Иногда кнопка превращается в {SPELL:1253593}: эта версия ставит щиты сразу на нескольких союзников, так что используйте ее поскорее.",
	PLAYCARD_256_W3 = "Ваш урон лечит каждого союзника с {SPELL:81749}, поэтому атаки по готовности поддерживают исцеление. {SPELL:47540} сильно бьет и работает на ходу; {SPELL:8092} также может превратить следующее применение {SPELL:17} в {SPELL:1253593}.",
	PLAYCARD_256_W4 = "{SPELL:585} почти не стоит маны и все равно лечит союзников с {SPELL:81749}. {SPELL:186263} лечит сильнее, чем {SPELL:2061}, но за это ваш союзник потом получает немного урона от темной магии.",
	PLAYCARD_256_WAOE = "{SPELL:194509} лечит до пяти союзников сразу и дает им всем {SPELL:81749}, так что следующие удары лечат всю группу. {SPELL:472433} сразу применяет усиленную версию и делает следующие две мгновенными.",
	PLAYCARD_257_AOE = "Группа ранена: {SPELL:596} и {SPELL:34861}, если они у вас есть. У всех мало здоровья: {SPELL:64843} или {SPELL:200183} – ради большего числа заклинаний \"Слово Света\".",
	PLAYCARD_257_EASY = "1. {SPELL:33076} – каждый раз по готовности, даже когда у всех полное здоровье: эффект лечит, когда по союзнику бьют.\n2. У кого-то мало здоровья? {SPELL:2050} (это заклинание \"Слово Света\": быстро восстанавливается, так что не берегите). Не готово? {SPELL:2061}: это ускоряет готовность {SPELL:2050}.\n3. Никого не нужно лечить? {SPELL:88625}, {SPELL:14914} и {SPELL:585} по врагу.",
	PLAYCARD_257_HERO1 = "Архонт: {SPELL:120517} примерно раз в минуту, прямо перед {SPELL:200183} или {SPELL:64843}.",
	PLAYCARD_257_HERO2 = "Оракул: у {SPELL:33076} появляется второй заряд. Применяйте на раненых союзников как можно чаще.",
	PLAYCARD_257_IDEA = "Лечите с помощью заклинаний \"Слово Света\". {SPELL:2061}, {SPELL:596} и {SPELL:585} ускоряют их готовность.",
	PLAYCARD_257_MISTAKE = "{SPELL:2061}, когда кнопка {SPELL:2050} готова: это стоит больше маны и лечит меньше.",
	PLAYCARD_257_S1 = "{SPELL:33076} – каждый раз по готовности, даже когда у всех полное здоровье: эффект лечит, когда по союзнику бьют.",
	PLAYCARD_257_S2 = "{SPELL:2050} – на союзника, у которого мало здоровья. Не берегите: быстро восстанавливается.",
	PLAYCARD_257_S3 = "{SPELL:2061} – на раненого, лучше всего когда кнопка загорается: тогда это мгновенно и дешевле.",
	PLAYCARD_257_S4 = "Никого не нужно лечить? {SPELL:88625}, {SPELL:14914} и {SPELL:585} по врагу.",
	PLAYCARD_257_TERMS = "\"Слово Света\" – это три сильных заклинания с долгим временем восстановления: {SPELL:2050} для одного союзника, {SPELL:34861} для группы, {SPELL:88625} против врага. Каждое восстанавливается быстрее, когда вы применяете его пару: {SPELL:2061}, {SPELL:596} и {SPELL:585}. Талант может заменить {SPELL:34861}; тогда {SPELL:596} ускоряет {SPELL:2050}.",
	PLAYCARD_257_W1 = "{SPELL:33076} ждет на союзнике и лечит его в момент удара, а затем перескакивает на другого союзника. Поскольку эффект ждет, раннее применение почти никогда не пропадает зря.",
	PLAYCARD_257_W2 = "{SPELL:2050} – одно из ваших самых сильных исцелений, и оно стоит меньше маны, чем {SPELL:2061}. Каждое применение {SPELL:2061} снимает несколько секунд с его времени восстановления, так что оно действительно быстро возвращается.",
	PLAYCARD_257_W3 = "Ваши исцеления и {SPELL:585} иногда зажигают {SPELL:109186}: тогда применение {SPELL:2061} мгновенно и намного дешевле. Каждое применение {SPELL:2061} также ускоряет готовность {SPELL:2050}.",
	PLAYCARD_257_W4 = "Когда никого не нужно лечить, атаки все равно помогают: {SPELL:585} ускоряет готовность {SPELL:88625} и может зажечь {SPELL:109186}. {SPELL:88625} к тому же ненадолго останавливает врага.",
	PLAYCARD_257_WAOE = "{SPELL:596} лечит пятерых союзников сразу и ускоряет готовность {SPELL:34861}. {SPELL:64843} лечит всех рядом с вами и усиливает все исцеление на них; {SPELL:200183} сразу снова делает ваши заклинания \"Слово Света\" готовыми.",
	PLAYCARD_258_AOE = "Сначала {SPELL:1227280} по группе врагов, затем {SPELL:34914} на тех, кто проживет какое-то время. Дальше те же кнопки.",
	PLAYCARD_258_HERO1 = "Архонт: {SPELL:120644} – по готовности, прямо перед {SPELL:228260}. Когда загорается {SPELL:391403}, примените.",
	PLAYCARD_258_HERO2 = "Ткач Бездны: {SPELL:263165} открывает разлом. Пока он открыт, кнопка {SPELL:8092} превращается в {SPELL:450983}: нажимайте по готовности.",
	PLAYCARD_258_IDEA = "Держите свои медленные заклинания темной магии на врагах, копите безумие и тратьте его на {SPELL:335467}.",
	PLAYCARD_258_MISTAKE = "{SPELL:228260}, пока ваши заклинания темной магии не наложены на цель: вы тратите главный момент на то, чтобы их наложить.",
	PLAYCARD_258_S1 = "Держите {SPELL:34914} и {SPELL:589} на цели. {SPELL:1227280} накладывает {SPELL:34914} на многих врагов сразу.",
	PLAYCARD_258_S2 = "{SPELL:228260} вместе с {SPELL:10060}: ваш главный момент. Сначала наложите на цель свои заклинания темной магии.",
	PLAYCARD_258_S3 = "Тратьте безумие на {SPELL:335467}, пока шкала не заполнилась или когда {SPELL:335467} на цели вот-вот закончится. Во время {SPELL:228260} – при каждой возможности.",
	PLAYCARD_258_S4 = "{SPELL:8092} и {SPELL:1242173} – по готовности. Больше ничего не готово? {SPELL:15407}.",
	PLAYCARD_258_TERMS = "Безумие – шкала специализации \"Тьма\". {SPELL:8092}, {SPELL:34914}, {SPELL:15407} и другие заклинания ее заполняют; {SPELL:335467} ее тратит. Шкала останавливается на 100 и не убывает в бою, поэтому тратьте до того, как она заполнится.",
	PLAYCARD_258_W1 = "Каждое ваше заклинание темной магии, действующее на враге, немного усиливает весь ваш урон по нему. {SPELL:34914} к тому же лечит вас, а {SPELL:1227280} одним нажатием накладывает этот эффект не более чем на шесть врагов.",
	PLAYCARD_258_W2 = "{SPELL:228260} на время усиливает все ваши заклинания, а {SPELL:10060} ускоряет их применение. Обе способности восстанавливаются каждые две минуты, поэтому используйте их вместе, когда заклинания темной магии уже действуют.",
	PLAYCARD_258_W3 = "Безумие, полученное при полной шкале, теряется. Обновлять {SPELL:335467} заранее безопасно: оставшийся урон добавляется к новому эффекту.",
	PLAYCARD_258_W4 = "{SPELL:8092} и {SPELL:1242173} дают много безумия. {SPELL:1242173} появляется на кнопке {SPELL:228260} – во время {SPELL:228260} или как бесплатный бонус; {SPELL:15407} заполняет паузы, и это заклинание можно прервать, как только готово что-то получше.",
	PLAYCARD_258_WAOE = "{SPELL:1227280} одним нажатием накладывает {SPELL:34914} не более чем на шесть врагов. Тогда ваши прямые удары задевают и каждого врага с {SPELL:34914} (это {SPELL:199484}), так что группа под вашими эффектами получает урон от каждого сильного удара.",
	PLAYCARD_259_AOE = "{SPELL:1247227}, пока не начнут кровоточить все враги, затем {SPELL:51723} вместо {SPELL:1329}.",
	PLAYCARD_259_HERO1 = "Ловчий смерти: {SPELL:703} ставит вашу метку на цель. Когда загорается \"Непроглядная ночь\" – {SPELL:32645} при 7 приемах серии.",
	PLAYCARD_259_HERO2 = "Служитель судьбы: ничего дополнительно нажимать не нужно. Завершающие приемы сами подбрасывают монеты; просто используйте обычные кнопки.",
	PLAYCARD_259_IDEA = "Травите врага ядами и вызывайте кровотечения, затем добивайте с помощью {SPELL:32645} – сильного удара ядом.",
	PLAYCARD_259_MISTAKE = "Позволять {SPELL:703} или {SPELL:1943} спасть: вместе с ними пропадает большая часть урона.",
	PLAYCARD_259_S1 = "Раз в 2 минуты: {SPELL:1856}, {SPELL:703}, затем {SPELL:360194} и {SPELL:385627} вместе. В промежутках – {SPELL:385627} отдельно.",
	PLAYCARD_259_S2 = "Держите {SPELL:703} и {SPELL:1943} на цели. {SPELL:1943} – при 5 приемах серии и больше.",
	PLAYCARD_259_S3 = "{SPELL:1329} – чтобы накопить приемы серии.",
	PLAYCARD_259_S4 = "5 приемов серии и больше: {SPELL:32645}. Применяйте снова, пока не закончился эффект предыдущего.",
	PLAYCARD_259_TERMS = "Приемы серии – очки разбойника. Атаки, например {SPELL:1329}, их добавляют, а завершающие приемы, например {SPELL:32645} и {SPELL:1943}, тратят их все, и каждое очко делает завершающий прием сильнее или длительнее. Держать можно 5, или 7 с талантами; лишние теряются. Почти каждая кнопка стоит еще и энергию, которая восполняется сама.",
	PLAYCARD_259_W1 = "{SPELL:360194} усиливает урон ваших кровотечений и ядов по этому врагу, и каждый ваш яд срабатывает на нем дважды. {SPELL:385627} растет с каждым ядом, поэтому вместе с {SPELL:360194} растет вдвое быстрее. {SPELL:703} сразу после {SPELL:1856} бьет сильнее все время, пока идет кровотечение.",
	PLAYCARD_259_W2 = "{SPELL:703} и {SPELL:1943} – кровотечения: они наносят урон врагу сами по себе. По отравленному врагу они еще и возвращают энергию (талант {SPELL:79134}), а больше приемов серии продлевают {SPELL:1943}.",
	PLAYCARD_259_W3 = "{SPELL:1329} бьет сразу обоими кинжалами: дает 2 приема серии, и каждый кинжал может нанести яд. С талантом {SPELL:14190} каждый критический удар дает еще один прием.",
	PLAYCARD_259_W4 = "{SPELL:32645} – сильный удар ядом, который также оставляет короткий положительный эффект: пока он действует, ваши яды срабатывают чаще. Таланты вознаграждают за повторное применение, пока этот эффект еще висит, поэтому нажимайте прямо перед его окончанием.",
	PLAYCARD_259_WAOE = "{SPELL:1247227} бьет всех вокруг вас и каждый раз копирует ваши {SPELL:703} и {SPELL:1943} еще на нескольких врагов, пока не будет кровоточить вся группа. Затем {SPELL:51723} бьет всех сразу и может отравить каждого.",
	PLAYCARD_260_AOE = "{SPELL:13877}, когда рядом 2 врага или больше: тогда ваши удары задевают и их.",
	PLAYCARD_260_HERO1 = "Ловкач (лучший выбор в этом сезоне): после 4 ударов эффекта \"Незримый клинок\" кнопка {SPELL:2098} превращается в \"Удар милосердия\". Нажмите сразу: этот прием считается за 5 дополнительных приемов серии, так что ваши способности тоже восстанавливаются быстрее.",
	PLAYCARD_260_HERO2 = "Служитель судьбы: ничего дополнительно нажимать не нужно, монеты подбрасываются сами. Используйте {SPELL:2098} уже при 5 приемах серии.",
	PLAYCARD_260_IDEA = "Быстрый пират: бейте быстро и быстро тратьте приемы серии – и ваши способности восстанавливаются быстрее.",
	PLAYCARD_260_MISTAKE = "Сидеть на полных приемах серии: каждый завершающий прием ускоряет восстановление ваших способностей, так что тратьте сразу.",
	PLAYCARD_260_S1 = "{SPELL:13750} – по готовности, когда приемов серии мало. Затем {SPELL:51690} при 6 и больше.",
	PLAYCARD_260_S2 = "{SPELL:1214909} – по готовности. Пропускайте, только если текущий бросок на стадии 2 или выше.",
	PLAYCARD_260_S3 = "6 приемов серии и больше: {SPELL:315341}, если кнопка готова, иначе {SPELL:2098}.",
	PLAYCARD_260_S4 = "Копите с помощью {SPELL:193315}. Загорелась кнопка {SPELL:185763}: стреляйте при 6 стаках или при 3, если приемов серии мало.",
	PLAYCARD_260_TERMS = "Приемы серии – очки разбойника. {SPELL:193315} и {SPELL:185763} их добавляют; завершающие приемы, например {SPELL:315341} и {SPELL:2098}, тратят их все и становятся сильнее за каждое очко. Держать можно 5, или 7 с талантами; лишние теряются. Каждый завершающий прием также ускоряет восстановление ваших способностей – немного за каждое потраченное очко.",
	PLAYCARD_260_W1 = "{SPELL:13750} намного ускоряет восполнение энергии и ваши атаки. С талантом {SPELL:395422} эта способность также сразу заполняет приемы серии, так что нажимайте ее, когда очков мало, иначе лишние пропадут. Она также заряжает очко (талант {SPELL:470347}), а {SPELL:51690} с заряженным очком бьет сильнее.",
	PLAYCARD_260_W2 = "{SPELL:1214909} дает случайный бонус из 4 стадий, и каждая стадия включает все, что ниже. Начиная со стадии 2 (\"Двойные неприятности\") {SPELL:193315} дает дополнительный прием серии. Новый бросок отменяет старый, так что бросайте, только когда бонуса нет или есть лишь стадия 1 (\"Единственный в своем роде\").",
	PLAYCARD_260_W3 = "{SPELL:315341} сильно бьет и затем на время немного повышает весь ваш урон; больше приемов серии – дольше эффект. {SPELL:2098} – обычный завершающий прием на случай, когда {SPELL:315341} еще восстанавливается.",
	PLAYCARD_260_W4 = "{SPELL:193315} иногда бьет дважды и зажигает {SPELL:185763}: более дешевый и сильный выстрел, который тоже дает приемы серии. С {SPELL:381846} можно накопить до 6; лишние теряются, так что стреляйте при 6. Один выстрел дает много очков, поэтому при 3 стреляйте, только если очков мало.",
	PLAYCARD_260_WAOE = "{SPELL:13877} ненадолго заставляет каждый удар по цели задевать и нескольких врагов вокруг вас. Эффект идет от вас, а не от цели, так что считается все рядом с вами. С {SPELL:381878} способность также дает прием серии за каждого задетого врага.",
	PLAYCARD_261_AOE = "{SPELL:197835} вместо {SPELL:53} и {SPELL:185438}, {SPELL:319175} вместо {SPELL:196819}. {SPELL:280719} – по-прежнему в первую очередь.",
	PLAYCARD_261_HERO1 = "Ловчий смерти (лучший выбор в этом сезоне): начинайте с {SPELL:185438}, чтобы поставить метку, и входите в {SPELL:185313}, когда приемов серии мало. Когда загорается \"Непроглядная ночь\", в первую очередь – следующее применение {SPELL:196819} при 6 очках и больше.",
	PLAYCARD_261_HERO2 = "Ловкач: входите в {SPELL:185313} с полными приемами серии. Когда загорается \"Удар милосердия\", нажмите {SPELL:196819}, чтобы его применить.",
	PLAYCARD_261_IDEA = "Удары из тени: {SPELL:185313} позволяет использовать атаки из незаметности посреди боя.",
	PLAYCARD_261_MISTAKE = "Использовать {SPELL:185313}, когда кнопка {SPELL:280719} не готова. Исключения: второе применение во время {SPELL:121471} и с талантами героя \"Ловчий смерти\", когда горит \"Непроглядная ночь\".",
	PLAYCARD_261_S1 = "{SPELL:185313} – когда готова кнопка {SPELL:280719}. Добавьте {SPELL:121471}, если и эта способность готова.",
	PLAYCARD_261_S2 = "Во время {SPELL:185313}: {SPELL:185438} для накопления. При 6 приемах серии и больше: сначала {SPELL:280719}, затем {SPELL:196819}.",
	PLAYCARD_261_S3 = "{SPELL:426591} – по готовности, прямо перед другими способностями с восстановлением. {SPELL:1856} вне {SPELL:185313}, когда приемов серии мало, затем {SPELL:185438}.",
	PLAYCARD_261_S4 = "Вне {SPELL:185313}: {SPELL:53} для накопления, {SPELL:196819} при 6 приемах серии и больше.",
	PLAYCARD_261_TERMS = "Приемы серии – очки разбойника. Атаки, например {SPELL:53} и {SPELL:185438}, их добавляют; завершающие приемы, например {SPELL:196819} и {SPELL:280719}, тратят их все и бьют сильнее за каждое очко. Держать можно 5, или 7 с талантами; лишние теряются. Ваши автоатаки иногда сохраняют несколько дополнительных для следующей накапливающей атаки ({SPELL:196912}).",
	PLAYCARD_261_W1 = "{SPELL:185313} – короткое окно, в котором можно использовать атаки из незаметности, а ваши удары наносят больше урона. {SPELL:280719} – ваш самый сильный завершающий прием, поэтому этот прием берегут для такого окна. {SPELL:121471} удваивает накапливаемые приемы серии и добавляет к каждому удару урон от темной магии, так что окно становится еще сильнее.",
	PLAYCARD_261_W2 = "Во время {SPELL:185313} можно использовать {SPELL:185438}: удар из тени, который бьет намного сильнее, чем {SPELL:53}, и дает 2 приема серии. В первую очередь – {SPELL:280719}: ваши теневые клоны бьют вместе с вами, а с талантом {SPELL:470347} первые завершающие приемы в окне засчитывают дополнительные очки.",
	PLAYCARD_261_W3 = "Какое-то время после {SPELL:426591} часть урона ваших завершающих приемов повторяется как урон от темной магии, поэтому применяйте эту способность прямо перед сильными завершающими приемами. {SPELL:1856} ненадолго скрывает вас: одно дополнительное применение {SPELL:185438} вне {SPELL:185313}, а с талантом {SPELL:343160} это заполняет приемы серии, так что делайте это, когда их мало.",
	PLAYCARD_261_W4 = "Вне {SPELL:185313} энергии меньше, и это нормально: копите с помощью {SPELL:53} (со спины врага эта атака сильнее) и тратьте с помощью {SPELL:196819}. Ваши автоатаки также сохраняют лишние приемы серии для следующей накапливающей атаки ({SPELL:196912}), так что держитесь рядом и продолжайте бить.",
	PLAYCARD_261_WAOE = "{SPELL:197835} бьет всех врагов вокруг вас и дает прием серии за каждого, так что в группе очки заполняются за одно нажатие. Затем {SPELL:319175} тратит их на всех сразу. {SPELL:280719} и так бьет всех врагов рядом с целью, поэтому порядок не меняется: этот прием по-прежнему идет первым.",
	PLAYCARD_262_AOE = "{SPELL:470057} – по готовности, {SPELL:188443} вместо {SPELL:188196}. 3 врага и больше: {SPELL:61882} вместо {SPELL:117014}.",
	PLAYCARD_262_HERO1 = "Предсказатель (лучший выбор в этом сезоне): {SPELL:443454} – по готовности, затем заклинание со временем применения.",
	PLAYCARD_262_HERO2 = "Вестник шторма: без {SPELL:443454}. Применяйте {SPELL:454009} каждый раз, когда кнопка загорается, вместо {SPELL:188196}.",
	PLAYCARD_262_IDEA = "Жгите лавой, бейте молнией и тратьте энергию Водоворота на сильный удар, пока шкала не заполнилась.",
	PLAYCARD_262_MISTAKE = "{SPELL:51505} без {SPELL:470411} на цели: тогда критический удар уже не гарантирован.",
	PLAYCARD_262_S1 = "Ваш главный момент, раз в 2–3 минуты: {SPELL:191634}, затем {SPELL:443454}, затем {SPELL:114050}. В промежутках первые два – по готовности.",
	PLAYCARD_262_S2 = "Держите {SPELL:470411} на цели. Обновляйте, когда осталось меньше 6 секунд.",
	PLAYCARD_262_S3 = "{SPELL:51505} – по готовности, когда на цели есть {SPELL:470411}.",
	PLAYCARD_262_S4 = "Тратьте энергию Водоворота на {SPELL:117014} (или {SPELL:8042}), пока шкала не заполнилась.",
	PLAYCARD_262_S5 = "Больше ничего не готово? {SPELL:188196}.",
	PLAYCARD_262_TERMS = "Энергия Водоворота – шкала специализации \"Стихии\". {SPELL:51505}, {SPELL:188196} и другие заклинания ее заполняют; {SPELL:117014} (или {SPELL:8042}) и {SPELL:61882} ее тратят. Когда шкала полна, она останавливается, поэтому тратьте раньше.",
	PLAYCARD_262_W1 = "{SPELL:114050} на время заставляет ваши заклинания выпускать дополнительную копию. Поэтому заряжайте {SPELL:191634} прямо перед этим: ваши самые сильные разряды придутся на это время. С талантами героя \"Предсказатель\": {SPELL:443454} также призывает духа, который применяет заклинания вместе с вами.",
	PLAYCARD_262_W2 = "Пока горит {SPELL:470411}, {SPELL:51505} всегда наносит этому врагу критический удар. Каждое срабатывание горения также может сразу восстановить {SPELL:51505}. Обновлять заранее безопасно: оставшееся время добавится.",
	PLAYCARD_262_W3 = "По горящему врагу {SPELL:51505} всегда наносит критический удар: это один из самых сильных ваших ударов, и он заметно заполняет шкалу энергии Водоворота. Кнопка загорелась раньше времени? Это {SPELL:77756}: снова готово и мгновенно.",
	PLAYCARD_262_W4 = "Шкала энергии Водоворота останавливается, когда полна: все, что вы получите тогда, теряется. {SPELL:117014} к тому же дает короткое усиление. {SPELL:8042} стоит меньше и применяется мгновенно – удобно, когда нужно двигаться.",
	PLAYCARD_262_W5 = "{SPELL:188196} не имеет времени восстановления, поэтому это заклинание заполняет каждую паузу и шкалу энергии Водоворота. Иногда оно бесплатно выпускает дополнительный разряд поменьше.",
	PLAYCARD_262_WAOE = "{SPELL:470057} поджигает целую группу одним нажатием. {SPELL:188443} перескакивает с врага на врага и дает тем больше энергии Водоворота, чем больше целей поразит. Тратьте ее на {SPELL:61882}: это заклинание ранит всех, кто стоит в зоне.",
	PLAYCARD_263_AOE = "От 2 врагов: {SPELL:188443} вместо {SPELL:188196}. Продолжайте нажимать {SPELL:187874} по готовности.",
	PLAYCARD_263_HERO1 = "Вестник шторма (лучший выбор в этом сезоне): загорелась кнопка {SPELL:454009}? Применяйте при 10 стаках вместо {SPELL:188196}. {SPELL:114051} – ваш всплеск урона раз в 2 минуты.",
	PLAYCARD_263_HERO2 = "Тотемист: каждую минуту {SPELL:444995}, затем {SPELL:197214}, затем {SPELL:384352}. Загорелся эффект \"Горячая рука\"? Сначала {SPELL:60103}.",
	PLAYCARD_263_IDEA = "Бейте оружием, чтобы накопить стаки эффекта \"Оружие Водоворота\", затем тратьте стаки на мгновенное заклинание молнии.",
	PLAYCARD_263_MISTAKE = "{SPELL:188196} меньше чем при 5 стаках: тогда заклинание применяется медленно и бьет слабо.",
	PLAYCARD_263_S1 = "Ваш главный момент: {SPELL:114051} (Тотемист: {SPELL:384352}). Пока эффект действует, нажимайте {SPELL:187874} и {SPELL:17364} как можно чаще.",
	PLAYCARD_263_S2 = "{SPELL:470057} и {SPELL:187874} – по готовности.",
	PLAYCARD_263_S3 = "При 10 стаках эффекта \"Оружие Водоворота\": {SPELL:188196}. Никогда не применяйте меньше чем при 5.",
	PLAYCARD_263_S4 = "Больше ничего не готово? {SPELL:17364}, затем {SPELL:60103}.",
	PLAYCARD_263_TERMS = "{SPELL:187880} – стаки, которые вы копите ударами оружия. Каждый стак делает следующее применение {SPELL:188196} или {SPELL:188443} быстрее и сильнее: при 5 – мгновенно, а с талантами можно держать и тратить 10. Трата стаков также ускоряет восстановление ваших ударов.",
	PLAYCARD_263_W1 = "Во время {SPELL:114051} или {SPELL:384352} вы получаете {SPELL:187880} сами собой, а каждое применение {SPELL:17364} и {SPELL:187874} еще и тратит стаки на заклинание молнии без отдельного нажатия. Так эти две кнопки одновременно бьют и тратят (во время {SPELL:114051} кнопка {SPELL:17364} превращается в \"Удар ветра\").",
	PLAYCARD_263_W2 = "{SPELL:470057} всегда наносит критический удар, накладывает {SPELL:470411} на цель и нескольких врагов рядом и дает {SPELL:187880}; с комплектом этого сезона это также вызывает \"Кольцо огня\". {SPELL:187874} бьет все перед вами, и какое-то время после этого {SPELL:17364} и {SPELL:60103} тоже бьют этих врагов молнией.",
	PLAYCARD_263_W3 = "Каждый стак {SPELL:187880} делает {SPELL:188196} быстрее и сильнее, а при 5 заклинание мгновенное. Держать можно 10, так что ждите 10 ради одного мощного удара, но не превышайте: стаки сверх 10 теряются.",
	PLAYCARD_263_W4 = "{SPELL:17364} бьет обоими оружиями, а удары оружием как раз дают {SPELL:187880}. Каждый потраченный стак ускоряет готовность {SPELL:17364} и {SPELL:60103}, так что не давайте им простаивать.",
	PLAYCARD_263_WAOE = "{SPELL:188443} перескакивает с врага на врага, поэтому начиная с 2 врагов те же стаки наносят больше урона, чем с {SPELL:188196}. {SPELL:187874} заставляет ваши удары бить молнией и врагов перед вами, так что поддерживайте эффект.",
	PLAYCARD_264_AOE = "Группа ранена: {SPELL:73920} под ними, затем {SPELL:1064}. Идет сильный удар: {SPELL:114052} (или {SPELL:108280}, если вы выбрали этот талант). Кто-то вот-вот умрет: {SPELL:98008}.",
	PLAYCARD_264_EASY = "1. Ставьте {SPELL:5394} по готовности: это тотем, который лечит за вас.\n2. Кто-то ранен? {SPELL:61295} на него, затем {SPELL:77472}. Ранено несколько человек? {SPELL:1064}.\n3. Никого не нужно лечить? {SPELL:470411}, {SPELL:51505}, затем {SPELL:188196} по врагу.",
	PLAYCARD_264_HERO1 = "Тотемист (лучший выбор в этом сезоне): {SPELL:444995} заменяет {SPELL:73920}. Держите тотем там, где стоит группа. {SPELL:378081} – по готовности: зажигает \"Тотем потока бури\".",
	PLAYCARD_264_HERO2 = "Предсказатель: {SPELL:443454} – по готовности: приходит предок, который лечит вместе с вами, и загорается \"Тотем потока бури\". Ваша большая способность с восстановлением – {SPELL:114052}.",
	PLAYCARD_264_IDEA = "Ставьте лечащие тотемы, поддерживайте {SPELL:61295} и лечите одного союзника или всю группу сразу.",
	PLAYCARD_264_MISTAKE = "Позволять {SPELL:61295} и {SPELL:5394} стоять с полными зарядами: это выброшенное бесплатное исцеление.",
	PLAYCARD_264_S1 = "{SPELL:5394} – по готовности. Никогда не держите оба заряда полными. Когда кнопка загорается как \"Тотем потока бури\", нажмите поскорее: это одно из ваших самых сильных исцелений.",
	PLAYCARD_264_S2 = "{SPELL:61295} – по готовности, на того, у кого этого эффекта еще нет.",
	PLAYCARD_264_S3 = "{SPELL:73685} – по готовности, если есть, затем {SPELL:77472} на одного раненого союзника или {SPELL:1064}, когда ранено несколько.",
	PLAYCARD_264_S4 = "Никого не нужно лечить? {SPELL:470411}, {SPELL:51505}, затем {SPELL:188196}: они почти не стоят маны.",
	PLAYCARD_264_TERMS = "{SPELL:1267016} – усиленная версия {SPELL:5394}. {SPELL:61295} иногда превращает в нее следующий тотем, а {SPELL:378081} (Предсказатель: {SPELL:443454}) всегда дает такой тотем. Эта версия лечит больше союзников, некоторых – сразу, и не тратит заряд {SPELL:5394}.",
	PLAYCARD_264_W1 = "{SPELL:5394} – тотем, который продолжает лечить раненых союзников, пока вы заняты другим. Заряд, который стоит полным, – это исцеление, которое вы уже не вернете, а версия {SPELL:1267016} лечит намного больше, так что ее тоже нажимайте поскорее.",
	PLAYCARD_264_W2 = "{SPELL:61295} лечит сразу и затем продолжает лечить какое-то время; многие ваши таланты работают лучше, чем больше союзников под этим эффектом, так что давайте его новому союзнику. Каждое применение также ускоряет следующее применение {SPELL:77472} или {SPELL:1064} и может зажечь {SPELL:1267016}.",
	PLAYCARD_264_W3 = "{SPELL:73685} немного лечит и делает следующее применение {SPELL:77472} или {SPELL:1064} сильнее и быстрее. {SPELL:77472} – дешевое и сильное исцеление одной цели; {SPELL:1064} стоит больше маны, но перескакивает на самых раненых союзников рядом.",
	PLAYCARD_264_W4 = "{SPELL:51505} всегда наносит критический удар врагу с {SPELL:470411}, так что сначала наложите этот эффект. Эти три заклинания почти не стоят маны, поэтому в спокойные моменты вы помогаете убивать врагов, пока мана восполняется.",
	PLAYCARD_264_WAOE = "{SPELL:73920} какое-то время лечит всех, кто стоит в зоне, поэтому ставьте ее там, где стоит группа, а затем {SPELL:1064} – на тех, у кого все еще мало здоровья. {SPELL:98008} распределяет здоровье поровну между всеми рядом с тотемом и снижает получаемый ими урон, так что почти мертвый игрок сразу в безопасности.",
	PLAYCARD_265_AOE = "{SPELL:980} на как можно больше врагов (примерно до 10). 3 врага и больше рядом друг с другом: {SPELL:27243}, чтобы наложить {SPELL:172} на всех; тратьте на это осколки души от 6 врагов (от 3 с талантом \"Посадка семян\"), иначе продолжайте использовать {SPELL:1259790}.",
	PLAYCARD_265_HERO1 = "Пожинатель душ (лучший выбор в этом сезоне): сначала потратьте осколки души, затем {SPELL:1257052}: это вернет 3.",
	PLAYCARD_265_HERO2 = "Призыватель огня: {SPELL:172} превращается в {SPELL:445468}. Сохраните несколько осколков души, нажмите {SPELL:442726}, затем тратьте их.",
	PLAYCARD_265_IDEA = "Накладывайте на врага заклинания, которые продолжают наносить урон, и тратьте осколки души на {SPELL:1259790}.",
	PLAYCARD_265_MISTAKE = "Позволять {SPELL:980} закончиться. Это заклинание дает вам осколки души, и ему нужно время, чтобы снова набрать силу.",
	PLAYCARD_265_S1 = "Ваш главный момент: {SPELL:205180}, затем потратьте все осколки души на {SPELL:1259790}.",
	PLAYCARD_265_S2 = "Постоянно держите {SPELL:980} и {SPELL:172} на цели. {SPELL:980} дает осколки души.",
	PLAYCARD_265_S3 = "{SPELL:48181} и {SPELL:1257052} – по готовности.",
	PLAYCARD_265_S4 = "Почти 5 осколков души? {SPELL:1259790}, чтобы ни один не пропал.",
	PLAYCARD_265_S5 = "Больше ничего? {SPELL:198590} (или {SPELL:686}).",
	PLAYCARD_265_TERMS = "Осколки души – сила чернокнижника: держать можно максимум 5. В специализации \"Колдовство\" их дает {SPELL:980}, пока наносит урон; {SPELL:1259790} и {SPELL:27243} тратят по 1. Вне боя они медленно восполняются до 3.",
	PLAYCARD_265_W1 = "Пока действует {SPELL:205180}, каждое ваше заклинание, которое продолжает ранить врага, бьет сильнее, и {SPELL:1259790} тоже. Поэтому сначала эта способность, затем как можно больше применений {SPELL:1259790}, пока она действует.",
	PLAYCARD_265_W2 = "{SPELL:980} иногда дает осколок души, пока наносит урон: вот откуда берутся ваши осколки души. {SPELL:172} тоже продолжает наносить урон и иногда зажигает {SPELL:108558}: тогда следующее заклинание-заполнитель быстрее и бьет сильнее.",
	PLAYCARD_265_W3 = "{SPELL:48181} на время увеличивает урон, который враг получает от вас. {SPELL:1257052} ранит каждого врага с вашими заклинаниями, а с талантами героя \"Пожинатель душ\" еще и дает осколки души.",
	PLAYCARD_265_W4 = "Держать можно максимум 5 осколков души: все полученные сверх этого теряются. Каждое применение {SPELL:1259790} стоит 1 и является отдельным заклинанием на враге, так что несколько таких заклинаний могут ранить его одновременно.",
	PLAYCARD_265_W5 = "{SPELL:198590} или {SPELL:686} заполняет паузы и может зажечь {SPELL:1260264}: тогда следующее применение {SPELL:1259790} бесплатное и мгновенное. Пока действует {SPELL:205180}, та же кнопка превращается в {SPELL:1261149}: все ваши остальные заклинания на враге сразу наносят немного дополнительного урона.",
	PLAYCARD_265_WAOE = "Каждый враг с {SPELL:980} может давать осколки души, так что больше таких врагов – больше осколков души. {SPELL:27243} взрывается на группе и накладывает {SPELL:172} на каждого врага рядом.",
	PLAYCARD_266_AOE = "{SPELL:196277}, когда призвано 6 и больше существ \"Дикий бес\". Распределяйте {SPELL:264178} по разным врагам.",
	PLAYCARD_266_HERO1 = "Демонопоклонник (лучший выбор в этом сезоне): после появления существа \"Властитель преисподней\" кнопка {SPELL:105174} превращается в \"Гибель миров\". Нажмите, пока подсветка не погасла.",
	PLAYCARD_266_HERO2 = "Пожинатель душ: нажимайте {SPELL:265187} при 2 осколках души или меньше: это вернет 3.",
	PLAYCARD_266_IDEA = "Призовите существо \"Демонический тиран\", затем тратьте осколки души на армию демонов: каждый демон делает его сильнее.",
	PLAYCARD_266_MISTAKE = "Нажимать {SPELL:265187} без осколков души и без эффекта \"Сердце демона\": тогда нечем заполнить это время с помощью {SPELL:105174}.",
	PLAYCARD_266_S1 = "Ваш главный момент: {SPELL:265187}. Сразу после – как можно больше применений {SPELL:105174}.",
	PLAYCARD_266_S2 = "{SPELL:104316} – по готовности. {SPELL:1276672} и ваш Grimoire тоже, если они есть.",
	PLAYCARD_266_S3 = "3 осколка души и больше: {SPELL:105174}.",
	PLAYCARD_266_S4 = "Загорелся эффект \"Сердце демона\" (2 и больше)? {SPELL:264178}: тогда это мгновенно.",
	PLAYCARD_266_S5 = "Больше ничего? {SPELL:686}: дает осколки души.",
	PLAYCARD_266_TERMS = "Осколки души – сила чернокнижника: держать можно максимум 5. В специализации \"Демонология\" их дают {SPELL:686} и {SPELL:264178}, а {SPELL:105174} тратит 3, чтобы призвать существ \"Дикий бес\". Вне боя они медленно восполняются до 3.",
	PLAYCARD_266_W1 = "{SPELL:265187} бьет сильнее за каждое призванное существо \"Дикий бес\" и \"Зловещий охотник\" – счет идет все время, пока он сражается. Поэтому каждое применение {SPELL:105174} сразу после призыва добавляет бесов, которые его усиливают, а с {SPELL:1276163} еще и призывает дополнительных демонов.",
	PLAYCARD_266_W2 = "{SPELL:104316} призывает два существа \"Зловещий охотник\", которые сильно бьют. Уходя, они всегда дают вам {SPELL:267102}, а пока они здесь, они усиливают {SPELL:265187}.",
	PLAYCARD_266_W3 = "{SPELL:105174} всегда стоит 3 осколка души и выпускает существ \"Дикий бес\", которые сражаются за вас. Каждый исчезающий бес также может оставить {SPELL:267102}.",
	PLAYCARD_266_W4 = "{SPELL:267102} делает применение {SPELL:264178} мгновенным, а {SPELL:264178} быстро дает осколки души. Держать можно максимум 4 стака {SPELL:267102}, так что тратьте их, пока новые не начали пропадать; один про запас удобен, когда нужно двигаться.",
	PLAYCARD_266_W5 = "{SPELL:686} не имеет времени восстановления и дает осколок души за каждое применение, поэтому заполняет каждую паузу.",
	PLAYCARD_266_WAOE = "{SPELL:196277} взрывает до 6 существ \"Дикий бес\" сразу, после чего восстанавливается, так что ждите, пока их будет 6. С {SPELL:460551} каждое применение {SPELL:264178} закладывает на своего врага медленную бомбу, так что дайте каждому врагу свою.",
	PLAYCARD_267_AOE = "2 врага: {SPELL:80240} на второго (если есть), чтобы ваши заклинания били обоих. 3 врага и больше рядом друг с другом (4 и больше с талантами героя \"Призыватель огня\"): {SPELL:5740} вместо {SPELL:116858}.",
	PLAYCARD_267_HERO1 = "Призыватель огня (лучший выбор в рейдах): {SPELL:348} превращается в {SPELL:445468}. {SPELL:442726} – по готовности; тратьте осколки души, пока действует эффект.",
	PLAYCARD_267_HERO2 = "Демонопоклонник (лучший выбор в подземельях): когда демон готов появиться, применяйте {SPELL:116858}, даже против групп: это призывает демона. После появления существа \"Властитель преисподней\" кнопка превращается в \"Гибель миров\": нажмите ее.",
	PLAYCARD_267_IDEA = "Копите осколки души огненными заклинаниями, затем тратьте их на мощное применение {SPELL:116858}.",
	PLAYCARD_267_MISTAKE = "Сидеть на 5 осколках души: каждый новый пропадает.",
	PLAYCARD_267_S1 = "Ваш главный момент: {SPELL:1122} – по готовности.",
	PLAYCARD_267_S2 = "Держите {SPELL:348} на цели. Обновляйте, когда остается около 5 секунд.",
	PLAYCARD_267_S3 = "{SPELL:6353} – по готовности, когда осколков души меньше 4. {SPELL:17962} – до того, как накопятся 2 заряда.",
	PLAYCARD_267_S4 = "Почти 5 осколков души: {SPELL:116858}. {SPELL:17877} – когда кнопка загорается.",
	PLAYCARD_267_S5 = "Больше ничего? {SPELL:29722}: дает осколки души.",
	PLAYCARD_267_TERMS = "Осколки души – сила чернокнижника: держать можно максимум 5. В специализации \"Разрушение\" вы копите их частями (Soul Shard Fragments; 10 частей = 1 осколок души): их добавляют {SPELL:29722}, {SPELL:17962} и {SPELL:348}. {SPELL:116858} тратит 2, {SPELL:5740} – 3.",
	PLAYCARD_267_W1 = "{SPELL:1122} обрушивает большого огненного демона, который оглушает врагов в месте падения. Пока демон здесь, он жжет все рядом и медленно дает вам осколки души.",
	PLAYCARD_267_W2 = "{SPELL:348} продолжает гореть, и каждое срабатывание дает часть осколка души. Обновлять в последние несколько секунд безопасно: оставшееся время добавится.",
	PLAYCARD_267_W3 = "{SPELL:6353} сразу дает целый осколок души и заодно накладывает {SPELL:348}. {SPELL:17962} дает часть осколка и {SPELL:196406}: следующее медленное заклинание применяется быстрее. При 2 зарядах накопление останавливается, так что не заставляйте эту кнопку ждать.",
	PLAYCARD_267_W4 = "{SPELL:116858} стоит 2 осколка души и всегда наносит критический удар, так что тратьте осколки на это заклинание, пока не уперлись в предел 5. {SPELL:17877} обычно работает только по врагам, у которых меньше 20% здоровья, но {SPELL:1245633} иногда делает это заклинание бесплатным и применимым к любому врагу: тогда можно нажимать.",
	PLAYCARD_267_W5 = "{SPELL:29722} не имеет времени восстановления и дает часть осколка души за каждое применение, а при критическом ударе – чуть больше.",
	PLAYCARD_267_WAOE = "{SPELL:80240} заставляет ваши заклинания по одной цели бить и второго врага, и эти дополнительные удары тоже дают осколки души. {SPELL:5740} стоит 3 осколка души, но ранит всех врагов в зоне.",
	PLAYCARD_268_AOE = "Те же кнопки: {SPELL:121253}, {SPELL:115181} и {SPELL:325153} уже бьют всю группу. Продолжайте использовать {SPELL:100780} после {SPELL:205523}; оставшуюся после этого энергию можно вложить в {SPELL:322729}.",
	PLAYCARD_268_HERO1 = "Шадо-Пан (лучший выбор в подземельях): во время {SPELL:132578} продолжайте нажимать {SPELL:115181} и {SPELL:121253}.",
	PLAYCARD_268_HERO2 = "Мастер гармонии: после {SPELL:322507} следующее применение {SPELL:100780} бьет и лечит сильнее. Нажмите поскорее.",
	PLAYCARD_268_IDEA = "Удары превращаются в медленный урон под названием \"Пошатывание\". Пейте отвары, чтобы смыть его; {SPELL:121253} и {SPELL:100780} возвращают отвары.",
	PLAYCARD_268_MISTAKE = "Тратить всю энергию на {SPELL:100780}: тогда нечем оплатить {SPELL:121253}, когда кнопка готова, и отвары восстанавливаются медленнее.",
	PLAYCARD_268_S1 = "Пошатывание стало желтым или красным? {SPELL:119582}. Не держите оба заряда неиспользованными.",
	PLAYCARD_268_S2 = "Идет сильный удар? Сначала {SPELL:322507} (или {SPELL:1241059}): щит, который поглощает урон.",
	PLAYCARD_268_S3 = "{SPELL:121253} – каждый раз по готовности, так что берегите для этого энергию. {SPELL:205523} – по готовности, затем {SPELL:100780}.",
	PLAYCARD_268_S4 = "{SPELL:115181}, {SPELL:132578} и {SPELL:325153} – по готовности. Лишняя энергия уходит в {SPELL:100780}.",
	PLAYCARD_268_TERMS = "Пошатывание – это то, как хмелевар принимает удары: часть каждого удара приходится не сразу, а капает на вас в течение следующих секунд. Шкала становится желтой, когда этот отложенный урон достигает 30% вашего здоровья, и красной при 60%; {SPELL:119582} смывает половину.",
	PLAYCARD_268_W1 = "Пошатывание растягивает часть каждого удара на следующие секунды; желтый или красный цвет означает, что впереди еще много урона. {SPELL:119582} сразу смывает половину, а пока оба заряда полны, новый заряд не копится.",
	PLAYCARD_268_W2 = "{SPELL:322507} ставит на вас щит, который поглощает урон, поэтому щит должен стоять до удара. {SPELL:1241059} (то же место в талантах, выбирается одно из двух) вместо этого дольше поглощает часть каждого удара.",
	PLAYCARD_268_W3 = "{SPELL:121253} бьет всех врагов рядом с целью, дает {SPELL:322120} (больше урона от каждого удара уходит в пошатывание) и ускоряет восстановление всех ваших отваров. {SPELL:205523} тоже дает {SPELL:322120}, а с талантом {SPELL:196736} следующее применение {SPELL:100780} бьет вдвое сильнее.",
	PLAYCARD_268_W4 = "{SPELL:115181} поджигает врагов, по которым попал {SPELL:121253}, и они бьют вас чуть слабее; {SPELL:325153} заставляет их на мгновение промахиваться атаками ближнего боя и сразу возвращает {SPELL:121253}. {SPELL:132578} берет на себя часть вашего пошатывания, а каждое лишнее применение {SPELL:100780} немного ускоряет восстановление отваров.",
	PLAYCARD_268_WAOE = "{SPELL:121253}, {SPELL:115181} и {SPELL:325153} уже бьют всех врагов в радиусе, так что для группы новые кнопки не нужны. {SPELL:322729} бьет всех вокруг вас и поддерживает {SPELL:322120}, пока вы собираете врагов, но тратьте на это только ту энергию, которая не понадобится для {SPELL:121253}.",
	PLAYCARD_269_AOE = "Те же кнопки. Добавьте {SPELL:101546} сразу после {SPELL:113656} и каждый раз, когда кнопка загорается.",
	PLAYCARD_269_HERO1 = "Шадо-Пан (лучший выбор в этом сезоне): дополнительных кнопок нет. Просто применяйте свои сильные удары ногами по готовности.",
	PLAYCARD_269_HERO2 = "Проводник Небожителей: {SPELL:123904}, затем {SPELL:443028}. Дождитесь, пока закончится ускорение от {SPELL:152175}.",
	PLAYCARD_269_IDEA = "Превращайте энергию в ци с помощью {SPELL:100780}, тратьте ци на сильные удары ногами и никогда не нажимайте одну и ту же кнопку дважды подряд.",
	PLAYCARD_269_MISTAKE = "Нажимать одну и ту же кнопку дважды подряд: пропадает бонус вашей искусности.",
	PLAYCARD_269_S1 = "{SPELL:1249625} – по готовности (2 заряда): ваш главный момент. Следом {SPELL:113656} и {SPELL:107428}. Мало ци или эффект {SPELL:1249625} почти закончился? Нажмите ту же кнопку еще раз – это топот, который дает ци.",
	PLAYCARD_269_S2 = "{SPELL:113656} и {SPELL:107428} – по готовности. {SPELL:152175} – когда кнопка загорается.",
	PLAYCARD_269_S3 = "{SPELL:100780} – чтобы получить ци. Используйте до того, как шкала энергии заполнится.",
	PLAYCARD_269_S4 = "Остаток ци тратьте на {SPELL:100784}. Когда кнопка загорается, это бесплатно: используйте.",
	PLAYCARD_269_TERMS = "Ци – очки танцующего с ветром. {SPELL:100780} делает их из энергии, а удары ногами их тратят. Ваша искусность, {SPELL:115636}, дает дополнительный урон, только если кнопка отличается от той, что вы нажали перед этим.",
	PLAYCARD_269_W1 = "{SPELL:1249625} удешевляет все ваши заклинания за ци и позволяет {SPELL:100784} еще сильнее ускорять ваши сильные удары ногами, так что применяйте {SPELL:113656} и {SPELL:107428}, пока эффект действует. В это время та же кнопка превращается в {SPELL:1272696}: топот, который бьет все рядом и дает ци.",
	PLAYCARD_269_W2 = "{SPELL:113656} и {SPELL:107428} – ваши самые сильные удары, но у них есть время восстановления, так что каждая секунда, пока они стоят готовыми, – потерянный урон. {SPELL:152175} работает, только пока оба восстанавливаются; вот почему кнопка загорается сразу после них.",
	PLAYCARD_269_W3 = "{SPELL:100780} стоит энергии и дает ци – очки, которые нужны ударам ногами. Энергия восполняется сама, но когда шкала полна, остальное теряется, так что тратьте раньше.",
	PLAYCARD_269_W4 = "{SPELL:100784} стоит немного ци и при каждом применении ускоряет готовность {SPELL:107428} и {SPELL:113656}. {SPELL:137384} иногда позволяет {SPELL:100780} сделать следующее применение {SPELL:100784} бесплатным; держать можно два таких эффекта, третий пропадает.",
	PLAYCARD_269_WAOE = "{SPELL:101546} бьет всех врагов вокруг вас. С комплектом этого сезона каждый удар {SPELL:113656} усиливает следующее применение {SPELL:101546}, а когда кнопка загорается ({SPELL:325201}), это не стоит ци.",
	PLAYCARD_270_AOE = "У всей группы мало здоровья: {SPELL:115310} (или {SPELL:388615}), либо {SPELL:322118} в рейдах и {SPELL:325197} в подземельях. Не все одновременно.",
	PLAYCARD_270_EASY = "1. {SPELL:115151} – каждый раз по готовности. Ваша цель – туман на каждом.\n2. Кто-то ранен? {SPELL:116670} на него. Это также лечит всех, на ком есть туман.\n3. Никого не нужно лечить? {SPELL:107428}, {SPELL:100780} и {SPELL:100784} по врагу: ваши удары немного лечат союзников.",
	PLAYCARD_270_HERO1 = "Проводник Небожителей (лучший выбор в этом сезоне): {SPELL:443028}, когда группа получает урон. Пока эффект действует, можно ходить.",
	PLAYCARD_270_HERO2 = "Мастер гармонии: {SPELL:116680} высвобождает накопленную силу. Сразу после этого нажмите {SPELL:100780} или {SPELL:116670}.",
	PLAYCARD_270_IDEA = "Держите {SPELL:115151} на всех. Ваши удары ногами тоже лечат, а {SPELL:116670} лечит всех, на ком есть туман.",
	PLAYCARD_270_MISTAKE = "Забывать о {SPELL:115294}: выпейте до 20 стаков, иначе позже кончится мана.",
	PLAYCARD_270_S1 = "{SPELL:115151} – по готовности. Не держите заряды полными.",
	PLAYCARD_270_S2 = "{SPELL:107428} – по готовности (рейдовая сборка: {SPELL:467307}): ранит врага и продлевает ваши туманы.",
	PLAYCARD_270_S3 = "{SPELL:116680} – по готовности, затем {SPELL:115151}: этот туман длится намного дольше.",
	PLAYCARD_270_S4 = "Кто-то вот-вот умрет? {SPELL:116670} на него. Совсем плохо? {SPELL:116849}.",
	PLAYCARD_270_S5 = "Никого не нужно лечить? {SPELL:100780} и {SPELL:100784} по врагу: ваши удары немного лечат союзников.",
	PLAYCARD_270_TERMS = "\"Туман\" на этой карточке означает эффект {SPELL:115151}: исцеление, которое продолжает действовать на союзнике и перескакивает на другого раненого, когда у цели полное здоровье. Каждое применение {SPELL:116670} также лечит всех, на ком есть туман.",
	PLAYCARD_270_W1 = "{SPELL:115151} какое-то время медленно лечит союзника, а если у него уже полное здоровье, перескакивает на другого раненого. Каждый союзник с туманом также лечится при каждом применении {SPELL:116670}, так что больше туманов – сильнее групповое исцеление.",
	PLAYCARD_270_W2 = "С талантом {SPELL:274909} каждое применение {SPELL:107428} продлевает уже наложенные туманы – максимум до двойной обычной длительности. С {SPELL:388847} это также накладывает короткий новый туман на союзника.",
	PLAYCARD_270_W3 = "{SPELL:116680} усиливает следующее заклинание и не вызывает общего времени восстановления. На {SPELL:115151} это добавляет туману 10 секунд, так что одно нажатие дает гораздо более долгое исцеление.",
	PLAYCARD_270_W4 = "{SPELL:116670} – сильное исцеление одного союзника, которое также лечит всех с вашим туманом. {SPELL:116849} окутывает союзника щитом, который поглощает урон и усиливает периодические исцеления на нем, и не вызывает общего времени восстановления, так что эту способность можно нажать посреди чего угодно.",
	PLAYCARD_270_W5 = "{SPELL:100780}, {SPELL:100784} и {SPELL:107428} лечат нескольких раненых союзников на часть нанесенного урона, а первые два не стоят маны. {SPELL:100780} также заставляет следующее применение {SPELL:100784} наносить дополнительные удары, а {SPELL:100784} может сразу восстановить {SPELL:107428}.",
	PLAYCARD_270_WAOE = "{SPELL:115310} сразу лечит всех рядом с вами и заодно снимает яды, болезни и некоторые магические эффекты. {SPELL:322118} и {SPELL:325197} действуют какое-то время и продолжают лечить, так что распределяйте свои большие кнопки по разным тяжелым моментам, а не складывайте их вместе.",
	PLAYCARD_577_AOE = "Те же кнопки, но {SPELL:258920} поднимается выше: не давайте этой кнопке стоять с 2 зарядами. {SPELL:188499} важнее, чем {SPELL:162794}.",
	PLAYCARD_577_HERO1 = "Истерзанный Скверной (лучший выбор в этом сезоне): во время {SPELL:191427} используйте \"Взор глубин\" и \"Пожирающий огонь\", когда они загораются.",
	PLAYCARD_577_HERO2 = "Альдрахийский разоритель: {SPELL:442294} – по готовности, затем {SPELL:162794} и {SPELL:188499}: после этого они бьют сильнее.",
	PLAYCARD_577_IDEA = "Копите гнев быстрыми ударами, тратьте его на клинки и превращайтесь в демона, чтобы бить еще сильнее.",
	PLAYCARD_577_MISTAKE = "{SPELL:191427}, пока {SPELL:198013} или {SPELL:188499} еще готовы: способность сбрасывает их восстановление, и этот сброс пропадает зря.",
	PLAYCARD_577_S1 = "{SPELL:191427} – когда и {SPELL:198013}, и {SPELL:188499} восстанавливаются. {SPELL:370965} – когда кнопка {SPELL:198013} почти готова: это усиливает следующий луч.",
	PLAYCARD_577_S2 = "{SPELL:198793}, затем {SPELL:198013}. После луча вы на несколько секунд становитесь демоном.",
	PLAYCARD_577_S3 = "{SPELL:258860}, затем {SPELL:188499} по готовности. В облике демона кнопка превращается в {SPELL:210152}.",
	PLAYCARD_577_S4 = "Лишний гнев тратьте на {SPELL:162794}. В облике демона кнопка превращается в {SPELL:201427}.",
	PLAYCARD_577_S5 = "Мало гнева? {SPELL:232893} и {SPELL:258920}.",
	PLAYCARD_577_TERMS = "Облик демона: {SPELL:191427} на время превращает вас в демона, а с талантом {SPELL:213410} каждое применение {SPELL:198013} тоже делает это на несколько секунд. В облике демона {SPELL:162794} превращается в {SPELL:201427}, а {SPELL:188499} – в {SPELL:210152}: те же кнопки, только сильнее.",
	PLAYCARD_577_W1 = "{SPELL:191427} на время делает вас демоном, а с талантом {SPELL:388112} сразу восстанавливает {SPELL:198013} и {SPELL:188499}. Поэтому сначала используйте эти две способности: сброс даст вам бесплатный дополнительный круг. {SPELL:370965} бросает вас к цели, а с талантом {SPELL:1270898} еще и сильно усиливает следующее применение {SPELL:198013}.",
	PLAYCARD_577_W2 = "{SPELL:198793} пробуждает {SPELL:388108}: следующие несколько секунд ваши удары чаще наносят критический урон, так что начинайте {SPELL:198013} сразу после. С талантом {SPELL:213410} луч затем на несколько секунд делает вас демоном.",
	PLAYCARD_577_W3 = "{SPELL:258860} на несколько секунд помечает врагов перед вами: каждое применение {SPELL:188499} и {SPELL:162794} наносит им дополнительный урон. Так что сразу добавляйте свои клинки. В облике демона {SPELL:210152} бьет сильнее и восстанавливается быстрее.",
	PLAYCARD_577_W4 = "Шкала гнева останавливается, когда полна, так что гнев, полученный после этого, теряется. {SPELL:162794} превращает лишний гнев в урон и иногда возвращает часть. Только оставляйте достаточно для {SPELL:188499} и {SPELL:198013}: они важнее.",
	PLAYCARD_577_W5 = "Ваши автоатаки сами наполняют гнев, но медленно. {SPELL:232893} и {SPELL:258920} дают быструю дополнительную порцию, когда гнев кончился, чтобы клинки не останавливались.",
	PLAYCARD_577_WAOE = "{SPELL:258920} жжет все вокруг вас; с талантом {SPELL:427775} у этой способности 2 заряда, и пока оба полны, новый не заряжается. {SPELL:188499} бьет всех врагов рядом, {SPELL:162794} – только одного.",
	PLAYCARD_581_AOE = "Те же кнопки, но {SPELL:247454} важнее, а {SPELL:212084} поднимается выше. Ставьте {SPELL:204596} под всю группу врагов.",
	PLAYCARD_581_HERO1 = "Разрушитель (лучший выбор в этом сезоне): при 3 стаках эффекта \"Безднопад\" сразу нажимайте {SPELL:247454} или {SPELL:228477}.",
	PLAYCARD_581_HERO2 = "Альдрахийский разоритель: {SPELL:442294} – по готовности, затем {SPELL:263642}, затем {SPELL:228477}: оба бьют сильнее.",
	PLAYCARD_581_IDEA = "Выбивайте души из врагов и поглощайте их сильными ударами: это лечит вас и держит на ногах.",
	PLAYCARD_581_MISTAKE = "Позволять {SPELL:263642} стоять с 2 зарядами: вы теряете души, а души – это ваше исцеление.",
	PLAYCARD_581_S1 = "{SPELL:203720} – всегда, когда не действует другая защитная способность. Не давайте эффекту прерываться: это ваша броня.",
	PLAYCARD_581_S2 = "{SPELL:204021} и {SPELL:187827} – почти по готовности, по очереди, чтобы одна из них почти всегда действовала.",
	PLAYCARD_581_S3 = "{SPELL:263642} – до того, как накопятся 2 заряда. {SPELL:258920} и {SPELL:204596} – по готовности: они дают гнев (и души с нужными талантами).",
	PLAYCARD_581_S4 = "5 душ и больше: {SPELL:247454}. Иначе тратьте гнев и души на {SPELL:228477}: это вас лечит.",
	PLAYCARD_581_S5 = "{SPELL:212084} – по готовности: жжет все перед вами и лечит вас.",
	PLAYCARD_581_TERMS = "Души – маленькие сферы, которые выбиваются из врагов, в основном с помощью {SPELL:263642}. Поглощение души лечит вас, и тем сильнее, чем больше урона вы только что получили. {SPELL:228477} поглощает до 2, {SPELL:247454} – до 5, и обе способности бьют сильнее за каждую поглощенную душу.",
	PLAYCARD_581_W1 = "{SPELL:203720} ненадолго дает толстую броню и повышенный шанс парирования, так что обычные удары ранят намного меньше. Это ваша малая защитная способность, которая быстро восстанавливается: заполняйте ею промежутки между {SPELL:204021} и {SPELL:187827}.",
	PLAYCARD_581_W2 = "{SPELL:204021} сильно снижает получаемый урон и поджигает врага. {SPELL:187827} дает дополнительное здоровье и намного больше брони. Каждая способность действует недолго, поэтому используйте их одну за другой: тогда одна из них почти всегда вас защищает.",
	PLAYCARD_581_W3 = "{SPELL:263642} копит до 2 зарядов; при 2 накопление останавливается, так что каждая секунда ожидания – потерянное бесплатное применение {SPELL:263642}. Каждое применение выбивает из врага души и дает гнев. {SPELL:258920} и {SPELL:204596} тоже дают гнев, а с нужными талантами – и души.",
	PLAYCARD_581_W4 = "Каждая поглощенная душа лечит вас, а {SPELL:247454} и {SPELL:228477} бьют сильнее за каждую поглощенную душу. {SPELL:247454} поглощает до 5 сразу, но имеет время восстановления; {SPELL:228477} поглощает до 2, бьет то, что перед вами, и вдобавок лечит вас.",
	PLAYCARD_581_W5 = "{SPELL:212084} на мгновение выдыхает огонь на все перед вами, и нанесенный урон тоже лечит вас. Стойте лицом к врагам, пока эффект не закончится.",
	PLAYCARD_581_WAOE = "{SPELL:247454} взрывается вокруг вас и бьет всех врагов рядом, так что чем больше группа, тем лучше. {SPELL:212084} бьет всю группу перед вами. {SPELL:204596} срабатывает через мгновение и жжет всех, кто стоит в зоне.",
	PLAYCARD_62_AOE = "{SPELL:153626} – по готовности. Меньше 4 чародейских зарядов: \"Чародейский импульс\" (если есть) вместо {SPELL:30451}.",
	PLAYCARD_62_HERO1 = "Ярость солнца (лучший выбор в этом сезоне): когда эффект {SPELL:365350} заканчивается, вы получаете эффект \"Чародейская душа\". Нажимайте {SPELL:44425} снова и снова, пока он действует.",
	PLAYCARD_62_HERO2 = "Чаромет: {SPELL:44425} при 20 стаках эффекта \"Чародейский залп\", а не при 25.",
	PLAYCARD_62_IDEA = "Вы копите 4 чародейских заряда и стаки эффекта \"Чародейский залп\", а затем выпускаете их одним мощным применением {SPELL:44425}.",
	PLAYCARD_62_MISTAKE = "Нажимать {SPELL:365350} и {SPELL:321507} порознь. Вместе они бьют намного сильнее.",
	PLAYCARD_62_S1 = "Ваш главный момент: {SPELL:365350} и {SPELL:321507} вместе. В промежутках – еще одно применение {SPELL:321507} каждые 45 секунд; никогда не опаздывайте.",
	PLAYCARD_62_S2 = "Загорелся эффект \"Ясность мысли\"? {SPELL:5143}: это бесплатно.",
	PLAYCARD_62_S3 = "На месте {SPELL:30451} загорелась кнопка {SPELL:1295924}? Примените поскорее: это бьет очень сильно.",
	PLAYCARD_62_S4 = "4 чародейских заряда и полный \"Чародейский залп\" (25 стаков): {SPELL:44425}.",
	PLAYCARD_62_S5 = "При 0 чародейских зарядов: {SPELL:153626}. Иначе заполняйте с помощью {SPELL:30451}.",
	PLAYCARD_62_TERMS = "Чародейские заряды (максимум 4) усиливают {SPELL:30451} и {SPELL:44425} и повышают стоимость {SPELL:30451} в мане. Стаки {SPELL:384452} приходят в основном от каждой волны {SPELL:5143} и усиливают следующее применение {SPELL:44425}. {SPELL:44425} тратит и то и другое, и вы начинаете заново.",
	PLAYCARD_62_W1 = "{SPELL:321507} накапливает часть всего вашего урона по цели и в конце взрывается. {SPELL:365350} на время усиливает ваши заклинания, так что вместе взрыв получается огромным; а {SPELL:321507} восстанавливается ровно дважды за время восстановления {SPELL:365350}, поэтому если опоздать, опоздает и ваш следующий главный момент.",
	PLAYCARD_62_W2 = "{SPELL:5143} работает, только когда загорается {SPELL:79684}, и тогда не стоит маны. Каждая волна стрел добавляет стак {SPELL:384452}, а эти стаки усиливают следующее применение {SPELL:44425}.",
	PLAYCARD_62_W3 = "{SPELL:1295924} появляется, когда вы тратите {SPELL:384452} с помощью {SPELL:44425}. Это один из ваших самых сильных ударов: он задевает и врагов вокруг цели и сразу дает 4 чародейских заряда; второй такой эффект сверху не накапливается, так что не откладывайте.",
	PLAYCARD_62_W4 = "{SPELL:44425} бьет сильнее за каждый чародейский заряд и каждый стак {SPELL:384452}, а затем тратит их все. Поэтому сначала заполните и то и другое, а потом потратьте одним мощным ударом.",
	PLAYCARD_62_W5 = "{SPELL:153626} дает чародейский заряд при применении и еще по одному за каждого врага, сквозь которого пролетает, так что быстро восполняет заряды после {SPELL:44425}. {SPELL:30451} тоже дает заряды и бьет сильнее за каждый имеющийся заряд.",
	PLAYCARD_62_WAOE = "{SPELL:153626} пролетает сквозь всю группу и дает заряд за каждого задетого врага. {SPELL:1241462} бьет все вокруг цели и тоже дает заряды за каждого врага, так что против группы восполняет заряды гораздо быстрее, чем {SPELL:30451}.",
	PLAYCARD_63_AOE = "4 врага и больше: {SPELL:2120} вместо {SPELL:11366}, когда загорается \"Полоса везения\".",
	PLAYCARD_63_HERO1 = "Ярость солнца (лучший выбор в этом сезоне): когда эффект {SPELL:190319} заканчивается, применение {SPELL:11366} ненадолго становится мгновенным, а удар всегда критический. Продолжайте нажимать.",
	PLAYCARD_63_HERO2 = "Ледяной огонь: {SPELL:431044} заменяет {SPELL:133}. Когда кнопка загорается, заклинание мгновенное и бьет сильно: применяйте.",
	PLAYCARD_63_IDEA = "Нанесите два критических удара подряд, чтобы зажечь эффект \"Полоса везения\", затем мгновенно примените {SPELL:11366}.",
	PLAYCARD_63_MISTAKE = "Позволять {SPELL:108853} стоять с полными зарядами. Не давайте зарядам простаивать, но сохраните 2–3 для {SPELL:190319}.",
	PLAYCARD_63_S1 = "Ваш главный момент, раз в минуту: {SPELL:190319} вместе с {SPELL:153561}. Все удары критические: чередуйте {SPELL:108853} и {SPELL:11366}.",
	PLAYCARD_63_S2 = "Загорелся эффект \"Разогрев\"? {SPELL:108853} превращает его в эффект \"Полоса везения\". Это работает даже во время применения другого заклинания.",
	PLAYCARD_63_S3 = "Загорелся эффект \"Полоса везения\"? {SPELL:11366}. Лучше всего – как раз когда заканчивается применение {SPELL:133}, чтобы оба попали вместе.",
	PLAYCARD_63_S4 = "Загорелся эффект \"Пироклазм\"? Примените {SPELL:11366} с полным временем применения: это бьет намного сильнее.",
	PLAYCARD_63_S5 = "Больше ничего? {SPELL:133}. На ходу: {SPELL:2948}.",
	PLAYCARD_63_TERMS = "\"Разогрев\" означает, что вы только что нанесли один критический удар. Нанесите второй подряд, и эффект превратится в {SPELL:195283}: следующее применение {SPELL:11366} или {SPELL:2120} мгновенное. Если между ними будет удар без крита, \"Разогрев\" снова пропадает.",
	PLAYCARD_63_W1 = "{SPELL:190319} ненадолго делает каждое заклинание критическим, так что каждый удар копит {SPELL:195283}, и можно применять {SPELL:11366} за {SPELL:11366}. {SPELL:153561} падает через мгновение после применения, так что убедитесь, что удар придется на время действия {SPELL:190319}.",
	PLAYCARD_63_W2 = "\"Разогрев\" – это один крит; второй крит подряд превращает его в {SPELL:195283}. {SPELL:108853} всегда наносит критический удар, и эту способность можно применять во время применения другого заклинания, так что второй крит обходится без потери времени.",
	PLAYCARD_63_W3 = "{SPELL:195283} делает следующее применение {SPELL:11366} мгновенным. Применяйте его как раз когда заканчивается {SPELL:133}, чтобы оба попали вместе: если оба критические, вы снова получаете {SPELL:195283}, а если критический только один, у вас все равно остается \"Разогрев\".",
	PLAYCARD_63_W4 = "Трата {SPELL:195283} иногда дает {SPELL:269650}: следующее применение {SPELL:11366} со временем применения наносит намного больше урона. С комплектом этого сезона оно еще и всегда критическое, так что медленное применение того стоит.",
	PLAYCARD_63_W5 = "{SPELL:133} – ваше заклинание-заполнитель: каждый его крит приближает {SPELL:195283}. {SPELL:2948} можно применять на ходу, а по врагу с малым запасом здоровья это заклинание всегда наносит критический удар.",
	PLAYCARD_63_WAOE = "{SPELL:195283} делает мгновенным и применение {SPELL:2120}, которое жжет всех врагов в круге. С {SPELL:416094} это заклинание бьет сильнее за каждого задетого врага, так что против группы оно лучше, чем {SPELL:11366}.",
	PLAYCARD_64_AOE = "3 врага и больше: направьте {SPELL:84714} в группу, затем {SPELL:190356} (с талантом \"Леденящий дождь\" кнопка загорается и заклинание мгновенное).",
	PLAYCARD_64_HERO1 = "Чаромет (лучший выбор против одной цели): {SPELL:30455} начиная с 6 стаков эффекта \"Замерзание\" на враге.",
	PLAYCARD_64_HERO2 = "Ледяной огонь (чуть лучше в подземельях): {SPELL:431044} заменяет {SPELL:116}. {SPELL:153595} – когда появляется. {SPELL:30455} – начиная с 12 стаков эффекта \"Замерзание\". Держите один эффект \"Ледяные пальцы\" про запас: тратьте его, только пока активен {SPELL:1247729}, или когда у вас их 2.",
	PLAYCARD_64_IDEA = "Накапливайте эффект \"Замерзание\" на враге с помощью {SPELL:116}, затем раскалывайте с помощью {SPELL:30455}.",
	PLAYCARD_64_MISTAKE = "Нажимать {SPELL:205021} первым, потому что это ваша большая кнопка. Сначала потратьте эффект \"Замерзание\" с помощью {SPELL:30455}, затем луч.",
	PLAYCARD_64_S1 = "{SPELL:84714} – по готовности. Когда кнопка {SPELL:116} превращается в {SPELL:199786}, нажмите ее.",
	PLAYCARD_64_S2 = "Загорелся эффект \"Заморозка мозгов\"? {SPELL:44614}.",
	PLAYCARD_64_S3 = "Загорелся эффект \"Ледяные пальцы\" или на враге много стаков эффекта \"Замерзание\": {SPELL:30455}.",
	PLAYCARD_64_S4 = "{SPELL:205021} – после них: это ваш большой луч. Против одного врага стойте на месте, пока он не закончится.",
	PLAYCARD_64_S5 = "Больше ничего? {SPELL:116}.",
	PLAYCARD_64_TERMS = "\"Замерзание\" – ледяная метка на враге. {SPELL:116} добавляет 1, {SPELL:44614} – 3, {SPELL:205021} – 8, а на одном враге может быть максимум 20. {SPELL:30455} раскалывает сразу 4 (больше с талантами) ради дополнительного урона: это называется {SPELL:1246769}.",
	PLAYCARD_64_W1 = "{SPELL:84714} – одно из ваших самых сильных заклинаний, так что никогда не заставляйте его ждать. Эффекты {SPELL:1246832} накапливаются сами: при пяти кнопка {SPELL:116} превращается в гигантскую версию – {SPELL:199786}.",
	PLAYCARD_64_W2 = "{SPELL:190447} сразу возвращает {SPELL:44614} и усиливает этот удар. {SPELL:44614} сразу накладывает 3 стака эффекта \"Замерзание\".",
	PLAYCARD_64_W3 = "{SPELL:30455} раскалывает сразу 4 стака эффекта \"Замерзание\" (больше с талантами) ради большого урона. С {SPELL:112965} удар такой же сильный, а \"Замерзание\" остается на враге.",
	PLAYCARD_64_W4 = "{SPELL:205021} насыпает 8 новых стаков эффекта \"Замерзание\". На враге может быть максимум 20, так что сначала потратьте старые.",
	PLAYCARD_64_W5 = "{SPELL:116} добавляет стаки эффекта \"Замерзание\" и может зажечь для вас {SPELL:190447} или {SPELL:112965}.",
	PLAYCARD_64_WAOE = "{SPELL:84714} бьет всех врагов, сквозь которых пролетает. С талантом {SPELL:270233} эта способность также делает применение {SPELL:190356} мгновенным: именно тогда кнопка загорается.",
	PLAYCARD_65_AOE = "Ранена вся группа: {SPELL:200025} в момент урона, затем {SPELL:375576}. {SPELL:85222} – когда исцеление {SPELL:85673} ушло бы в избыточное лечение.",
	PLAYCARD_65_EASY = "1. {SPELL:20473} на того, по кому ударили. Это лечит и дает вам энергию Света: очки, которые вы копите, а потом тратите.\n2. 3 ед. энергии Света или больше? Потратьте на {SPELL:85673} (с талантами героя \"Вестник солнца\" эта кнопка – {SPELL:156322}) на союзника с наименьшим запасом здоровья. При 5 тратьте сразу.\n3. Ничего не готово, а у кого-то все еще падает здоровье? {SPELL:19750} (1,5 сек., дешево). {SPELL:82326} (2 сек., дорого, очень сильно) – только когда у кого-то не хватает много здоровья и у вас достаточно маны.\n4. Никого не нужно лечить? {SPELL:275773} и {SPELL:415091} по врагу: урон и немного маны обратно.",
	PLAYCARD_65_HERO1 = "Вестник солнца (лучший выбор в этом сезоне): {SPELL:85673} превращается в {SPELL:156322}. Нажимайте {SPELL:375576} по готовности: это дает {SPELL:431377}.",
	PLAYCARD_65_HERO2 = "Кузнец Света: без {SPELL:375576}. {SPELL:432459} – на союзника в опасности, {SPELL:432472} – на себя. Продолжайте использовать заряды.",
	PLAYCARD_65_IDEA = "Копите энергию Света с помощью {SPELL:20473}, затем тратьте ее на сильные исцеления. Никогда не сидите на 5 ед. энергии Света.",
	PLAYCARD_65_MISTAKE = "{SPELL:375576}, когда выбран враг: способность бьет врагов, вместо того чтобы лечить союзников.",
	PLAYCARD_65_S1 = "{SPELL:375576} и {SPELL:31884} – по готовности. {SPELL:375576} сразу заполняет энергию Света.",
	PLAYCARD_65_S2 = "{SPELL:19750}, сильная версия: после {SPELL:20473} вы иногда получаете эффект \"Прилив Света\". Этот эффект виден среди ваших положительных эффектов, 15 секунд. Тогда примените заклинание на того, по кому ударили: оно мгновенное и намного сильнее. Затем снова {SPELL:20473}: это дает энергию Света.",
	PLAYCARD_65_S3 = "Тратьте энергию Света на {SPELL:85673} (с талантами героя \"Вестник солнца\": {SPELL:156322}) на союзника с наименьшим запасом здоровья. При 5 ед. энергии Света тратьте сразу.",
	PLAYCARD_65_S4 = "Никого не нужно лечить? {SPELL:275773} и {SPELL:415091} по врагу: урон и немного маны обратно.",
	PLAYCARD_65_TERMS = "Энергия Света – очки паладина. Держать можно до 5; {SPELL:20473} дает 1, {SPELL:375576} может заполнить всю шкалу, а каждая тратящая способность ({SPELL:85673}, {SPELL:85222}, {SPELL:415091}) стоит 3. Все сверх 5 теряется.",
	PLAYCARD_65_W1 = "{SPELL:375576} применяет {SPELL:20473} сразу к нескольким союзникам, и каждое применение дает энергию Света: шкала заполняется за одно нажатие, так что используйте, когда шкала почти пуста. {SPELL:31884} на время усиливает все ваше исцеление.",
	PLAYCARD_65_W2 = "{SPELL:53576} делает следующее применение {SPELL:19750} мгновенным и намного более сильным: одно из лучших ваших исцелений. Держать можно только один такой эффект, так что потратьте его, прежде чем снова нажать {SPELL:20473}.",
	PLAYCARD_65_W3 = "{SPELL:85673} – одно большое исцеление за 3 ед. энергии Света, так что отдавайте его союзнику, которому оно нужнее всего: исцеление сверх полного здоровья пропадает. При 5 каждое новое очко теряется, так что тратьте сразу.",
	PLAYCARD_65_W4 = "{SPELL:275773} ранит врага и дает энергию Света. {SPELL:415091} тратит энергию Света на урон, возвращает немного маны и ускоряет готовность {SPELL:20473}.",
	PLAYCARD_65_WAOE = "{SPELL:200025} ненадолго помечает нескольких раненых союзников, и все они получают часть каждого другого вашего исцеления: вот почему сразу после идет {SPELL:375576}. {SPELL:85222} лечит сразу нескольких союзников рядом с вами – лучше, когда одно большое исцеление было бы лишним.",
	PLAYCARD_66_AOE = "Те же кнопки, но {SPELL:31935} поднимается выше – сразу после {SPELL:53600}.",
	PLAYCARD_66_HERO1 = "Храмовник: после {SPELL:375576} загорается \"Молот Света\". Нажмите его сразу.",
	PLAYCARD_66_HERO2 = "Кузнец Света: одна кнопка с 2 зарядами (ее можно нажать дважды, прежде чем ей нужно перезарядиться), которая чередует \"Святой оплот\" и {SPELL:432472}. Нажимайте ее, когда {SPELL:31884} (или {SPELL:389539}) не действует.",
	PLAYCARD_66_IDEA = "Собирайте энергию Света (очки, которые копятся до 5) быстрыми ударами и тратьте ее на {SPELL:53600}: это ваша броня.",
	PLAYCARD_66_MISTAKE = "Копить 5 ед. энергии Света и не тратить: {SPELL:53600} спадает, и по вам проходят сильные удары.",
	PLAYCARD_66_S1 = "{SPELL:31884} и {SPELL:375576} сразу по готовности: с них начинается ваш главный момент. С талантом {SPELL:389539} эта способность заменяет {SPELL:31884} на той же кнопке.",
	PLAYCARD_66_S2 = "3 ед. энергии Света или больше: {SPELL:53600}. Поддерживайте эффект почти без перерыва.",
	PLAYCARD_66_S3 = "{SPELL:275779} и {SPELL:204019} сразу по готовности: они дают энергию Света.",
	PLAYCARD_66_S4 = "Бросайте {SPELL:31935} сразу по готовности. Стойте в зоне {SPELL:26573}; обновляйте ее, когда больше ничего не готово.",
	PLAYCARD_66_S5 = "Против одного врага или босса можно начать с кнопки {SPELL:62124}. Против группы начните с ударов по площади: {SPELL:26573} и {SPELL:31935}. Когда враг бьет кого-то другого, провоцируйте его: {SPELL:62124}.",
	PLAYCARD_66_TERMS = "Энергия Света – это очки паладина. Можно накопить до 5; {SPELL:275779} и {SPELL:204019} дают 1, {SPELL:375576} дает 1 за каждого задетого врага, а {SPELL:53600} требует 3. Все, что сверх 5, пропадает.",
	PLAYCARD_66_W1 = "{SPELL:31884} на время усиливает ваши удары, а вместо {SPELL:275779} появляется {SPELL:1241288}. {SPELL:375576} бросает {SPELL:31935} сразу в нескольких врагов, и каждое попадание дает энергию Света, поэтому нажимайте эту кнопку, когда энергии Света мало.",
	PLAYCARD_66_W2 = "{SPELL:53600} на несколько секунд повышает вашу броню, и каждый удар по вам ранит слабее. Эта способность не ждет других кнопок, поэтому ее можно вставлять между ними и держать почти постоянно.",
	PLAYCARD_66_W3 = "{SPELL:275779} и {SPELL:204019} дают энергию Света, поэтому не давайте им простаивать. {SPELL:204019} также немного ослабляет следующий удар каждого задетого врага.",
	PLAYCARD_66_W4 = "{SPELL:31935} перескакивает на других врагов и прерывает заклинание, которое произносит ваша цель. {SPELL:26573} обжигает всех врагов, стоящих в зоне, и некоторые ваши таланты и комплект брони работают там лучше.",
	PLAYCARD_66_W5 = "{SPELL:62124} заставляет одного врага сразу атаковать вас. Враги преследуют того, кто вредит им сильнее всего, поэтому против группы ваши удары по многим целям сразу, например {SPELL:26573} и {SPELL:31935}, притягивают их всех к вам.",
	PLAYCARD_66_WAOE = "{SPELL:31935} перескакивает от врага к врагу, поэтому чем больше врагов, тем больше их задевает один бросок. Тогда эта способность ценнее кнопки, которая бьет только одну цель.",
	PLAYCARD_70_HERO1 = "Храмовник: после {SPELL:255937} вы получаете один \"Молот Света\" (3 ед. энергии Света). Нажмите его сразу.",
	PLAYCARD_70_HERO2 = "Вестник солнца: {SPELL:24275} поднимается выше – сразу после удара, который тратит энергию Света.",
	PLAYCARD_70_IDEA = "Вы копите энергию Света (до 5) быстрыми ударами и тратите ее на один сильный удар.",
	PLAYCARD_70_MISTAKE = "Держать 5 ед. энергии Света. Тогда каждая нажатая кнопка дает энергию Света, которая пропадает.",
	PLAYCARD_70_S1 = "Ваш главный момент: {SPELL:31884} и {SPELL:343527} вместе. Аксессуары и зелье – вместе с ними.",
	PLAYCARD_70_S2 = "При 5 ед. энергии Света сразу тратьте: {SPELL:383328} (2 врага и больше: {SPELL:53385}).",
	PLAYCARD_70_S3 = "{SPELL:255937} и {SPELL:375576}, как только они готовы.",
	PLAYCARD_70_S4 = "В промежутках – {SPELL:184575}, затем {SPELL:20271}. Пока действует {SPELL:31884}, кнопка {SPELL:20271} сама меняется на {SPELL:24275}.",
	PLAYCARD_70_TERMS = "Энергия Света – это очки паладина. Можно накопить до 5; {SPELL:184575} и {SPELL:20271} дают 1, {SPELL:255937} дает 3, а расходующий удар вроде {SPELL:383328} или {SPELL:53385} стоит 3. Все, что сверх 5, пропадает.",
	PLAYCARD_70_W1 = "{SPELL:31884} на время усиливает все ваши удары. {SPELL:343527} сбрасывает молот, который падает позже и добавляет часть всего урона, нанесенного вами этим врагам за это время: нажимайте их вместе и бейте сильно, пока он падает.",
	PLAYCARD_70_W2 = "Энергия Света останавливается на 5: все, что вы набираете сверх этого, пропадает. {SPELL:383328} сильно бьет одного врага, {SPELL:53385} бьет всех врагов вокруг вас, поэтому от 2 врагов вторая кнопка наносит больше урона.",
	PLAYCARD_70_W3 = "{SPELL:255937} бьет всех перед вами, поджигает их и сразу дает 3 ед. энергии Света. {SPELL:375576} одним нажатием бросает особо сильный {SPELL:20271} в нескольких врагов.",
	PLAYCARD_70_W4 = "{SPELL:184575} и {SPELL:20271} – ваши быстрые источники энергии Света, а {SPELL:20271} заставляет врага получать больше урона от вашего следующего расходующего удара. Пока действует {SPELL:31884}, на этой кнопке – {SPELL:24275}, и он бьет сильнее.",
	PLAYCARD_71_AOE = "{SPELL:260708} сразу по готовности. {SPELL:845} становится главной кнопкой и заодно накладывает {SPELL:772} на всех.",
	PLAYCARD_71_HERO1 = "Истребитель (лучший в этом сезоне): {SPELL:227847}, пока действует {SPELL:167105}. Каждый подсвеченный {SPELL:163201} приближает следующий {SPELL:227847}.",
	PLAYCARD_71_HERO2 = "Колосс: {SPELL:436358}, пока действует {SPELL:167105}. Пока идут удары, вы почти не двигаетесь; в это время вас нельзя оглушить.",
	PLAYCARD_71_IDEA = "Бейте сильно кнопкой {SPELL:12294}, вскрывайте защиту цели кнопкой {SPELL:167105} и никогда не тратьте ярость впустую.",
	PLAYCARD_71_MISTAKE = "Тратить всю ярость на {SPELL:1464}, из-за чего {SPELL:12294} приходится ждать. {SPELL:12294} всегда важнее.",
	PLAYCARD_71_S1 = "{SPELL:167105} и {SPELL:107574} вместе, сразу по готовности: ваш главный момент. Пока он длится, бейте сильнее всего.",
	PLAYCARD_71_S2 = "Держите {SPELL:772} на цели; с талантом \"Рассекающий удар\" его за вас накладывает {SPELL:845}. Обновляйте, когда осталось меньше 5 секунд.",
	PLAYCARD_71_S3 = "{SPELL:12294} сразу по готовности. {SPELL:163201} и {SPELL:1269383}: нажимайте, как только они подсветятся.",
	PLAYCARD_71_S4 = "Затем {SPELL:7384}. Больше ничего не готово? {SPELL:1464}. Цель почти мертва? {SPELL:163201} вместо {SPELL:1464}.",
	PLAYCARD_71_TERMS = "Ярость – ваше топливо. В начале боя ее нет, она копится в основном от автоматических взмахов оружия, а почти каждая атака ее тратит. После боя она убывает. С талантом {SPELL:152278} каждая потраченная единица также приближает {SPELL:167105} и {SPELL:107574}.",
	PLAYCARD_71_W1 = "{SPELL:167105} пробивает броню врага: на время все, что вы с ним делаете, бьет сильнее. {SPELL:107574} тоже усиливает весь ваш урон. Эффекты складываются, поэтому приберегите самые сильные удары на этот момент.",
	PLAYCARD_71_W2 = "{SPELL:772} – это кровотечение: один удар, а потом враг еще какое-то время истекает кровью сам. Это бесплатный урон, если эффект никогда не спадает. Прямо перед кнопкой {SPELL:167105} обновите его чуть раньше, чтобы кровотечение длилось весь этот момент.",
	PLAYCARD_71_W3 = "{SPELL:12294} – ваш главный удар, поэтому он никогда не ждет. Подсвеченный {SPELL:163201} ничего не стоит, работает при любом здоровье цели и бьет так, будто вы заплатили полную ярость; {SPELL:1269383} – улучшенный {SPELL:1464}, который появляется сам. Оба эффекта через время исчезают, так что используйте их.",
	PLAYCARD_71_W4 = "{SPELL:7384} – верный удар: от него нельзя уклониться, его нельзя блокировать или парировать. {SPELL:1464} просто тратит лишнюю ярость. Когда у врага мало здоровья, {SPELL:163201} превращает ту же ярость в гораздо более сильный удар.",
	PLAYCARD_71_WAOE = "{SPELL:260708} заставляет ваши следующие несколько ударов по одной цели задевать еще и второго врага рядом. {SPELL:845} бьет всех перед вами и одним нажатием накладывает {SPELL:772} на каждого.",
	PLAYCARD_72_AOE = "Сначала {SPELL:190411}, чтобы следующие удары задевали и врагов вокруг. {SPELL:385059} сразу по готовности.",
	PLAYCARD_72_HERO1 = "Истребитель: {SPELL:227847} сразу после кнопки {SPELL:184367}, пока действует {SPELL:1719}. Нажимайте {SPELL:5308} каждый раз, когда он подсвечивается.",
	PLAYCARD_72_HERO2 = "Горный тан: {SPELL:6343} вместо {SPELL:190411}. {SPELL:435222} – каждый раз, когда подсвечивается; не давайте накопиться 2 зарядам.",
	PLAYCARD_72_IDEA = "Быстро набирайте ярость, тратьте ее на {SPELL:184367}, чтобы впасть в исступление, и оставайтесь в нем как можно дольше.",
	PLAYCARD_72_MISTAKE = "Дать исступлению закончиться. Нажимайте {SPELL:184367} до того, как оно спадет, а не только при полной ярости.",
	PLAYCARD_72_S1 = "{SPELL:1719} сразу по готовности, вместе с {SPELL:107574}, если он у вас есть: ваш главный момент.",
	PLAYCARD_72_S2 = "{SPELL:184367}, когда вы не в исступлении или когда ярость почти полная.",
	PLAYCARD_72_S3 = "{SPELL:23881} и {SPELL:85288} дают ярость. С талантом \"Безрассудный раж\" {SPELL:1719} превращает их в более сильные версии: продолжайте их нажимать.",
	PLAYCARD_72_S4 = "{SPELL:5308}, когда он подсвечивается или цель почти мертва. Больше ничего не готово? {SPELL:190411}.",
	PLAYCARD_72_TERMS = "{SPELL:184361} – короткий положительный эффект: пока он действует, весь ваш урон выше. {SPELL:184367} дает его всегда, {SPELL:385059} тоже, а {SPELL:23881} – иногда. Он длится всего несколько секунд, поэтому поддерживайте его, снова нажимая {SPELL:184367} до того, как он спадет.",
	PLAYCARD_72_W1 = "{SPELL:1719} заставляет вас гораздо быстрее получать ярость и чаще наносить критические удары, поэтому {SPELL:184367} можно нажимать намного чаще. {SPELL:107574} добавляет еще урона, так что нажимайте их вместе.",
	PLAYCARD_72_W2 = "{SPELL:184367} – это четыре быстрых удара, и он дает вам {SPELL:184361}: несколько секунд весь ваш урон выше. Если нажать снова, пока эффект не закончился, он продлевается. Ярость сверх полной полосы пропадает, поэтому тратьте ее до того, как полоса заполнится.",
	PLAYCARD_72_W3 = "Обе кнопки дают ярость. {SPELL:23881} также немного лечит вас и может сам дать {SPELL:184361}. С талантом {SPELL:396749} {SPELL:1719} улучшает их до версий \"Кровавая баня\" и \"Сокрушающий удар\", которые бьют сильнее.",
	PLAYCARD_72_W4 = "{SPELL:5308} – сильный добивающий удар, который обычно работает только по сильно раненым врагам. Когда он подсвечивается ({SPELL:29725}), он работает по любому врагу, так что используйте его. {SPELL:190411} заполняет паузы, чтобы вы не теряли ни мгновения.",
	PLAYCARD_72_WAOE = "{SPELL:190411} заряжает ваши следующие несколько ударов по одной цели, и каждый из них задевает еще нескольких врагов вокруг. {SPELL:385059} одним нажатием бьет всех рядом, вызывает у них кровотечение и дает вам {SPELL:184361}.",
	PLAYCARD_73_AOE = "Те же кнопки. Против новой группы сначала {SPELL:6343}, чтобы все враги атаковали вас, а не ваших друзей.",
	PLAYCARD_73_HERO1 = "Горный тан: {SPELL:6343} иногда превращается в {SPELL:435222}. Нажмите его сразу; {SPELL:107574} дает вам два.",
	PLAYCARD_73_HERO2 = "Колосс: {SPELL:436358} сразу по готовности, лучше всего вместе с {SPELL:107574}. Лишняя ярость идет на {SPELL:6572}.",
	PLAYCARD_73_IDEA = "Набирайте ярость кнопкой {SPELL:23922} и тратьте ее на {SPELL:2565} и {SPELL:190456}: это ваша броня.",
	PLAYCARD_73_MISTAKE = "Тратить всю ярость на {SPELL:6572}: тогда для {SPELL:2565} и {SPELL:190456} ничего не остается.",
	PLAYCARD_73_S1 = "{SPELL:2565} почти все время, пока враги бьют вас. Никогда не держите 2 заряда.",
	PLAYCARD_73_S2 = "Ярость почти полная? {SPELL:190456}. Эта способность не мешает другим кнопкам, так что нажимайте ее между ними.",
	PLAYCARD_73_S3 = "{SPELL:107574} и {SPELL:1160} сразу по готовности. {SPELL:23922} при каждой готовности: это ваш главный источник ярости.",
	PLAYCARD_73_S4 = "{SPELL:6343} и {SPELL:385952} сразу по готовности. Больше ничего не готово? {SPELL:6572}. Враг почти мертв? {SPELL:163201} вместо {SPELL:6572}.",
	PLAYCARD_73_TERMS = "Ярость – ваше топливо. В начале боя ее нет; вы получаете ее от своих атак (прежде всего {SPELL:23922}) и когда враги бьют вас. Вы тратите ее на {SPELL:2565} и {SPELL:190456}, чтобы выжить, а ярость сверх полной полосы пропадает.",
	PLAYCARD_73_W1 = "{SPELL:2565} на несколько секунд блокирует каждый удар в ближнем бою, и пока он действует, ваш {SPELL:23922} бьет сильнее. У него 2 заряда: пока оба полные, новый не копится, и это потерянное время. Если нажать его, пока он еще действует, время добавляется.",
	PLAYCARD_73_W2 = "{SPELL:190456} поглощает половину каждого удара, пока щит не израсходован, а повторное нажатие пополняет щит до предела. Ярость сверх полной полосы пропадает, поэтому немного лишнего щита всегда лучше потраченной впустую ярости.",
	PLAYCARD_73_W3 = "{SPELL:23922} – ваш главный источник ярости, а другие атаки могут восстановить его раньше, так что следите за ним. {SPELL:107574} усиливает ваши удары и уменьшает получаемый урон; {SPELL:1160} заставляет врагов вокруг бить вас слабее.",
	PLAYCARD_73_W4 = "{SPELL:6343} бьет всех врагов вокруг и дает ярость. {SPELL:385952} бросается вперед, бьет целую группу и бесплатно включает {SPELL:2565}. Лишняя ярость идет на {SPELL:6572}, который иногда подсвечивается и ничего не стоит; против почти мертвого врага {SPELL:163201} бьет сильнее.",
	PLAYCARD_73_WAOE = "Враги идут на того, кто досаждает им больше всего. {SPELL:6343} бьет всех врагов вокруг сразу, поэтому вся группа поворачивается к вам, а не к вашим друзьям.",
	PLAYCARD_ALIVE_NONE = "У MH пока нет списка \"Не умереть\" для этой специализации.",
