	RITUAL_INFO_ACCOLADES_FMT = "Field Accolades: %d (на персонажа)",
	RITUAL_INFO_ACCOLADES_WEEKLY_FMT = "Field Accolades: %d  (на этой неделе %d/%d)",
	RITUAL_INFO_HEADER = "Награды и валюта",
	RITUAL_INFO_PARTICLES = "Обменяйте 100 Dark Particles на 10 Field Accolades.",
	RITUAL_INFO_PICKUP = "Еженедельное задание \"Midnight: Ritual Sites\" (3 места проведения ритуалов) дает Lady Liadrin в Луносвете, только в те недели, когда оно входит в ее четыре варианта. В центре на Базаре (2-й этаж: Ranger Captain Lilatha и Lady Darkglen) – задания испытаний и торговцы.",
	RITUAL_INFO_RENOWN_REWARDS = "Известность открывает покупки: ранг 3 – декор для жилья (Rae'ana), ранг 6 – питомцы, ранг 7 – декор Dark Obelisk, ранг 8 – транспорт Void-Touched Hawkstrider (Sergeant Vornin).",
	RITUAL_INFO_TIERS = "Более высокие уровни (1–6) и испытания дают больше добычи, известности и Accolades.",
	RITUAL_INFO_VAULT = "Каждый забег засчитывается в строку \"Мир\" Великого хранилища как вылазка того же уровня: уровни 1–4 дают ветерана, уровни 5–6 – чемпиона. Со 2-го сезона трек героя больше не дается.",
	RITUAL_INFO_VENDOR = "Тратьте у Maren Silverwing (Базар): снаряжение искателя приключений и ветерана. 2-й сезон понизил его с чемпиона и героя – торговец показывает, сколько что стоит сегодня.",
	RITUAL_INTRO_STEP_ALLIES = "выполните \"Outfitting and Allies\" – встретьтесь с союзниками в лагере Lilatha.",
	RITUAL_INTRO_STEP_FMT = "Вводная цепочка заданий на этом персонаже – шаг %d/%d: %s",
	RITUAL_INTRO_STEP_INLOG = "(уже в вашем журнале заданий)",
	RITUAL_INTRO_STEP_INTEREST = "\"Ritual Interest\" – отметьтесь у Lady Darkglen в центре.",
	RITUAL_INTRO_STEP_PROBLEMS = "\"Ritual Problems\" – изучите донесения о местах проведения ритуалов, затем сорвите ритуал в одном из них.",
	RITUAL_INTRO_STEP_SUMMONS = "начните \"Ranger Captain's Summons\" у Ranger Captain Lilatha, лагерь над Базаром.",
	RITUAL_INTRO_STEP_VOIDSTRIKE = "\"Void Strike\" – этот шаг проходит в зоне активного вторжения (см. \"Натиски Бездны\" ниже).",
	RITUAL_MAP_NOTE = "Щелкните по месту, чтобы поставить точку маршрута TomTom к его Curious Obelisk. Активно только одно место в неделю (фиолетовый значок на карте).",
	RITUAL_NEXT_FMT = "Следующая неделя: %s",
	RITUAL_RENOWN_LABEL = "Известность мест проведения ритуалов",
	RITUAL_RENOWN_LOCKED = "Известность не начата – возьмите Ranger Captain's Summons в центре на Базаре.",
	RITUAL_RENOWN_WORD = "Известность",
	RITUAL_SHARE_BUSY = "Отправка уже идет.",
	RITUAL_SHARE_CHALLENGES_HEADER = "Испытания ритуалов по добыче:",
	RITUAL_SHARE_COMBAT = "Нельзя отправить в бою.",
	RITUAL_SHARE_CONFIRM_FMT = "Отправить группе советы по испытаниям ритуалов (строк: %d)?",
	RITUAL_SHARE_COOLDOWN = "Отправка на перезарядке – попробуйте чуть позже.",
	RITUAL_SHARE_COPY_HINT = "Ctrl+C, затем вставьте в канал группы или в Discord.",
	RITUAL_SHARE_COPY_TITLE = "Копировать советы по ритуалам",
	RITUAL_SHARE_FAILED = "Не удалось собрать советы по испытаниям.",
	RITUAL_SHARE_NO_GROUP = "Вступите в группу или рейд, чтобы отправить эти советы (или включите тестовый режим отправки).",
	RITUAL_SHARE_SENT_FMT = "Отправлено строк: %d, получатель: %s.",
	RITUAL_SHARE_SENT_TEST_FMT = "Отправлено строк: %d (тестовый режим).",
	RITUAL_SHARE_XLOC_HEADER_FMT = "%s отправляет советы по испытаниям ритуалов:",
	RITUAL_SUBTITLE = "Контент открытого мира Midnight. Каждую неделю активно одно из двух мест; сорвите ритуал там ради Field Accolades, снаряжения и строки \"Мир\" Великого хранилища.",
	RITUAL_TIP_ALARMBELLS_MECHANIC = "• Убийство врагов призывает подкрепление; чем больше и сильнее убитая группа, тем сильнее адды.|n• Увеличивает добычу, пока активно.",
	RITUAL_TIP_ALARMBELLS_UNLOCK = "• Пройдите место уровня 4, затем поговорите с Lady Darkglen в Луносвете (требуемый уровень снижается каждую неделю).",
	RITUAL_TIP_BROKENTHRONE_NOTES = "• Tainted Bone Pile (открывает испытание Tainted Corpses): /way 47.91 36.52.|n• Dark Obelisks (задание Malevolent Boons – изучите любые 5; всего 9): 61/50 · 41/50 · 45/59 · 42/68 · 55/58 · 54/54 · 50/57 · 45/64 · 47/76.|n• Разрушение Dark Obelisks снимает усиления с врагов этого места – после этого боссы заметно проще (оставляйте их, только если идете за достижением без обелисков).|n• По всему месту разбросаны небольшие клады и сферы восстановления.",
	RITUAL_TIP_BROKENTHRONE_OVERVIEW = "• Зул'Аман – Разрушенный трон, на юге зоны.|n• Враги: культисты Twilight's Blade.|n• Активно по одной неделе; обелиск отмечен на карте фиолетовым значком.|n• Входите у Curious Obelisk и выбирайте там уровень и испытания.",
	RITUAL_TIP_BROKENTHRONE_PHASES = "• Короткий сценарий в отдельной копии из трех этапов: убейте именных врагов вокруг места, затем Corrupted Amani Dragonhawk, затем Faithbreaker Ger'lok в здании.|n• Сценарий, видимый у обелиска: \"A Corrupted Path\".|n• Corrupted Amani Dragonhawk: вставайте в маленькие красные лужи (Volatile Plumage), чтобы они не взорвались на всю группу, и никогда не стойте перед его Shadowflame Breath.|n• Только с испытанием Malevolent Boons: Dark Obelisks дают врагам дополнительные заклинания, например Binding Nebula, которая держит вас, пока вы ее не убьете, и зеркала Бездны, чей каст нужно прервать. Сначала разрушьте обелиски, и ничего этого не будет.|n• Затем заберите добычу из Ritual Chest у Faithbreaker Ger'lok.",
	RITUAL_TIP_DAGGERSPINE_NOTES = "• Tainted Bone Pile (открывает испытание Tainted Corpses): /way 66.09 62.58.|n• Dark Obelisks (задание Malevolent Boons – изучите любые 5; всего 9): 66.6/38.8 · 64.7/49.8 · 63.8/70.9 · 39.2/76.2 · 35.3/63.2 · 50/42 · 42/56 · 62/62 · 44.8/47.3.|n• По всему месту разбросаны небольшие клады и сферы восстановления.",
	RITUAL_TIP_DAGGERSPINE_OVERVIEW = "• Леса Вечной Песни – Высота Пронзающего Гребня, на западном побережье у Деревни Золотистой Дымки.|n• Враги: наги.|n• Активно по одной неделе; обелиск отмечен на карте фиолетовым значком.|n• Входите у Curious Obelisk и выбирайте там уровень и испытания.",
	RITUAL_TIP_DAGGERSPINE_PHASES = "• Короткий сценарий в отдельной копии из трех этапов: убейте именных элитных врагов вокруг места, затем Void-Infused Mindbreaker, затем саму Lady Selen'vjar.|n• Сценарий, видимый у обелиска: \"A Strike From the Sea\".|n• После победы заберите добычу из Ritual Chest у Lady Selen'vjar, затем уходите через Obelisk Portal за зданием.",
	RITUAL_TIP_EMBERS_MECHANIC = "• Случайные враги И последний босс усилены, над ними парит сфера.|n• Увеличивает добычу, пока активно (одна из самых больших прибавок).",
	RITUAL_TIP_EMBERS_UNLOCK = "• Заберите Ember of Power в месте уровня 4, чтобы начать задание (требуемый уровень снижается каждую неделю).",
	RITUAL_TIP_INTRO_ORBS = "• В бою появляются сферы восстановления, которые исцеляют 15% здоровья (известность 1).|n• Orb Potency (известность 4) усиливает это исцеление.|n• Опирайтесь на сферы, а не тратьте способности на самолечение.",
	RITUAL_TIP_INTRO_SCORING = "• Добыча – это ваш счет; Ritual Chest в конце зависит от нее.|n• Смерти: первые 2 бесплатны, затем каждая смерть снижает добычу на 5%, максимум до -50%.|n• Чистое прохождение лучше быстрых пулов – смерть прямо стоит наград.",
	RITUAL_TIP_INTRO_TIERS = "• Выбирайте уровень у Curious Obelisk; пройдите каждый уровень, чтобы открыть следующий.|n• Обелиск показывает, что нужно для каждого уровня: для уровня 3 – 1 активное испытание, для уровня 4 – 2, для уровня 5 – 4, для уровня 6 – 6.|n• Более высокие уровни дают больше добычи и известности. Уровень предметов, рекомендованный игрой, прочитан с самого обелиска 20 августа: |cffffffffT1 215 · T2 231 · T3 244 · T4 259 · T5 268 · T6 275|r. Наведите курсор на уровень в выпадающем списке, чтобы проверить сами – эти числа меняются между сезонами.",
	RITUAL_TIP_INTRO_WEEKLY = "• На старте уровень, нужный, чтобы ОТКРЫТЬ испытание, снижался на один каждую неделю. С тех пор прошли месяцы, так что сейчас, скорее всего, хватит низкого уровня.|n• Засчитывается в строку \"Мир\" Великого хранилища, как вылазка того же уровня.|n• Ускорители известности: Ritual Tablet (первое место за неделю), Ritual Tablet Fragment (второе место) и Ritual Site Reports (зависят от вашей добычи).",
	RITUAL_TIP_MALEVOLENTBOONS_MECHANIC = "• Темные обелиски усиливают врагов поблизости – разрушьте обелиски, чтобы снять усиления.|n• Увеличивает добычу, пока активно.",
	RITUAL_TIP_MALEVOLENTBOONS_UNLOCK = "• Пройдите место уровня 2, чтобы получить задание от Lady Darkglen, затем изучите 5 Dark Obelisks в одном из мест (требуемый уровень снижается каждую неделю).",
	RITUAL_TIP_MANIFESTATIONS_MECHANIC = "• Появляются духи и начинают долгий каст. Остановите каст, и дух исчезнет: работает прерывание, а также оглушение, страх и другой контроль. Если дать касту завершиться, вы получите его иссушающую магию.|n• Увеличивает добычу, пока активно.",
	RITUAL_TIP_MANIFESTATIONS_UNLOCK = "• Пройдите место уровня 3, затем поговорите с Ranger Captain Lilatha в Луносвете (требуемый уровень снижается каждую неделю).",
	RITUAL_TIP_PATROLS_MECHANIC = "• По месту патрулируют элитные враги – по возможности обходите их пути.|n• Увеличивает добычу, пока активно.",
	RITUAL_TIP_PATROLS_UNLOCK = "• \"Добудьте\" уникальные клады в месте уровня 3+ (требуемый уровень снижается каждую неделю).",
	RITUAL_TIP_REINFORCED_MECHANIC = "• По всему месту разбросаны дополнительные враги – ждите более плотных групп.|n• Увеличивает добычу, пока активно (одна из самых больших прибавок).",
	RITUAL_TIP_REINFORCED_UNLOCK = "• Пройдите место уровня 2, затем поговорите с Ranger Captain Lilatha в Луносвете (требуемый уровень снижается каждую неделю).",
	RITUAL_TIP_TAINTEDCORPSES_MECHANIC = "• Убитые враги оставляют лужу смертельной магии Бездны – выходите из нее.|n• Увеличивает добычу, пока активно.",
	RITUAL_TIP_TAINTEDCORPSES_UNLOCK = "• Заберите Tainted Bone Pile в месте уровня 2+ (место указано в заметках о месте), затем сдайте задание.",
	RITUAL_TIP_TENDRILS_MECHANIC = "• Хватающие щупальца появляются с вращающимся зеленым кругом – выходите, иначе вас обездвижит и ранит.|n• Увеличивает добычу, пока активно.",
	RITUAL_TIP_TENDRILS_UNLOCK = "• Заберите Ritual Chest в конце любого места, затем сдайте задание \"Ritual Site Challenge Report: Tendrils\".",
